local config = {
  ui_story_5080_50800100_1_dialog_content = "Embora nossas táticas nesta batalha tenham sido muito bem-sucedidas, com todo o respeito, seu plano foi extremamente arriscado.",
  ui_story_5080_50800100_2_dialog_content = "Heh, tempos desesperados exigem medidas desesperadas.",
  ui_story_5080_50800100_3_dialog_content = "Ainda assim, estou um pouco surpreso que você, de todas as pessoas, acha que é arriscado.",
  ui_story_5080_50800100_4_dialog_content = "Relatório! A Operação Especial A4 foi um sucesso e nossos operativos retornaram em segurança!",
  ui_story_5080_50800100_5_dialog_content = "O novo relatório foi enviado para a sua aprovação.",
  ui_story_5080_50800100_6_dialog_content = "Entendido. Algo mais?",
  ui_story_5080_50800100_7_dialog_content = "Sim, Grande Marechal. Alguns dos operativos fizeram pedidos pessoais, que também submeti a você.",
