  ui_story_5080_50800100_16_dialog_content = "Minhas desculpas, Grande Marechal. Eu falhei em ajudar meu subordinado.",
  ui_story_5080_50800100_17_dialog_content = "Parece que teremos que fazer algo a respeito disso.",
  ui_story_5080_50800100_18_dialog_content = "Acho que é hora de colocá-la naquela missão.",
