  ui_story_5080_50800100_23_dialog_content = "Não há como saber se vai funcionar, mas talvez um novo filhote seja o que ela precisa para abrir suas asas e voar alto novamente.",
  ui_story_5080_50800100_24_dialog_content = "Carleen, cuidado com o seu pé esquerdo!",
  ui_story_5080_50800100_25_dialog_content = "Pato, PlayerName! Mantenha o foco!",
  ui_story_5080_50800100_26_dialog_content = "Obrigado... Vice! Cuidado com suas costas!",
  ui_story_5080_50800100_27_dialog_content = "Sem chance!",
  ui_story_5080_50800100_28_dialog_content = "Por que de repente existem tantos Eclipsitas...?",
  ui_story_5080_50800100_29_dialog_content = "Estamos à beira do Deserto de Rediesel, lembra? Ainda há muitas áreas por aqui que não foram desbravadas.",
  ui_story_5080_50800100_30_dialog_content = "Ainda assim, são muitos deles... Por que o <color=#FFB400>subordinado</color> do Comandante Hiiro está nos esperando tão longe daqui? Isso não faz sentido...",
  ui_story_5080_50800100_31_dialog_content = "Ouça atentamente, Vice. A missão que estou prestes a designar para você vem da própria Grande Marechal.",
  ui_story_5080_50800100_32_dialog_content = "Para essa missão ultra-secreta, você estará trabalhando sob o comando de uma certa pessoa e a ajudará a completar sua missão.",
  ui_story_5080_50800100_33_dialog_content = "Você tem permissão para trazer quaisquer companheiros que considere necessários para a missão, mesmo aqueles que não são de Illumina.",
  ui_story_5080_50800100_34_dialog_content = "Tenho certeza de que a Grande Marechal tem seus motivos para permitir isso.",
  ui_story_5080_50800100_35_dialog_content = "Eu não acho que já ouvi falar de uma missão como essa, Comandante Hiiro. Quem exatamente é a pessoa em questão?",
  ui_story_5080_50800100_36_dialog_content = "Você não deveria ser estranho para ela. Afinal, ela é uma das suas veteranas—",
  ui_story_5080_50800100_37_dialog_content = "O nome dela é <color=#FFB400>Rachel.</color>",
  ui_story_5080_50800100_38_dialog_content = "Eles simplesmente não param de vir. Tem certeza de que este é o caminho certo, Vice?",
  ui_story_5080_50800100_39_dialog_content = "Tenho certeza disso. De acordo com o mapa, esta é a melhor rota possível.",
  ui_story_5080_50800100_40_dialog_content = "O capitão que estamos procurando é o que te enviou esse mapa, certo? Como você pode confiar tanto em alguém que nunca conhecemos antes?",
  ui_story_5080_50800100_41_dialog_content = "Você parece especialmente sério sobre essa missão, Vice.",
  ui_story_5080_50800100_42_dialog_content = "Eu diria até que você está entusiasmado com isso. Você estava se preparando para a missão bem antes do sol nascer hoje.",
  ui_story_5080_50800100_43_dialog_content = "Bem, isso é porque... Esta pessoa é uma lenda da 3ª Legião.",
  ui_story_5080_50800100_44_dialog_content = "Quando eu ainda estava na academia, aprendemos tudo sobre suas realizações brilhantes e era esperado que seguíssemos seu exemplo.",
  ui_story_5080_50800100_45_dialog_content = "Ela já era uma capitã altamente condecorada antes de ter a minha idade!",
  ui_story_5080_50800100_46_dialog_content = "Uma lenda da 3ª Legião... Por que nunca ouvimos falar dela antes?",
  ui_story_5080_50800100_47_dialog_content = "Não tenho certeza do porquê, mas depois que ela desapareceu repentinamente um dia, ninguém nunca mais a viu...",
  ui_story_5080_50800100_48_dialog_content = "Graah—",
  ui_story_5080_50800100_49_dialog_content = "Há muitos Eclipsitas.",
  ui_story_5080_50800100_50_dialog_content = "Este lugar é uma zona de pouso terrível...",
  ui_story_5080_50800100_51_dialog_content = "E se eu pedir para <color=#FFB400>Soroz</color> vir nos buscar agora? Espere, isso só atrairia ainda mais Eclipsitas.",
  ui_story_5080_50800100_52_dialog_content = "Isso até colocaria este capitão em perigo!",
  ui_story_5080_50800100_53_dialog_content = "Parece que não temos escolha. Carleen, vou conter os Eclipsitas enquanto você corre para um terreno mais alto!",
  ui_story_5080_50800100_54_dialog_content = "O quê? Não perca o foco, PlayerName! Volte para trás de mim!",
  ui_story_5080_50800100_55_dialog_content = "Graaah!",
  ui_story_5080_50800100_56_dialog_content = "(Eles estão atacando de baixo da areia?! Não dá, não consigo desviar a tempo!)",
  ui_story_5080_50800100_57_dialog_content = "PlayerName!",
  ui_story_5080_50800100_58_dialog_content = "Você deve aprender a se proteger antes de se preocupar com os outros, <color=#FFB400>Primeiro Celestita</color>.",
  ui_story_5080_50800100_59_dialog_content = "Isso foi apenas um pequeno teste. Foi realmente tão difícil para você?",
  ui_story_5080_50800100_60_dialog_content = "Não importa. Avaliar sua verdadeira força também é uma das minhas responsabilidades.",
  ui_story_5080_50800100_61_dialog_content = "Você tá bem, PlayerName?",
  ui_story_5080_50800100_62_dialog_content = "Eu-Eu estou bem... Quem é aquela pessoa...",
  ui_story_5080_50800100_63_dialog_content = "Uma mulher com um olhar penetrante, cercada por drones...",
  ui_story_5080_50800100_64_dialog_content = "E vestindo o uniforme de um capitão de elite...",
  ui_story_5080_50800100_65_dialog_content = "Você deve ser...!",
  ui_story_5080_50800100_66_dialog_content = "Você é o capitão do <color=#FFB400>Esquadrão Eagleeye</color>? M-Muito obrigado por salvar PlayerName!",
  ui_story_5080_50800100_67_dialog_content = "<color=#FFB400>Eagleeye</color>... Não há necessidade de mencionar isso mais.",
  ui_story_5080_50800100_68_dialog_content = "O Comandante disse que vocês estão trabalhando juntos há muito tempo. Como ainda podem cometer tantos erros amadores?",
  ui_story_5080_50800100_69_dialog_content = "Você investe emoções desnecessárias demais em seus companheiros de equipe, Celestita.",
  ui_story_5080_50800100_70_dialog_content = "Na minha opinião, sua lança é mais do que capaz de proteger você e se defender sozinha.",
  ui_story_5080_50800100_71_dialog_content = "Em vez de abandonar sua posição de forma tão imprudente, você deveria ter deixado Vice eliminar os alvos mais importantes.",
  ui_story_5080_50800100_72_dialog_content = "E você. Você também é um capitão, não é?",
  ui_story_5080_50800100_73_dialog_content = "S-Sim, senhora!",
  ui_story_5080_50800100_74_dialog_content = "Sua especialidade também está na exploração. Não há razão para você... se meter em algo acima de suas capacidades.",
  ui_story_5080_50800100_75_dialog_content = "(Ela... está demonstrando preocupação pelo Vice?)",
  ui_story_5080_50800100_76_dialog_content = "Para um esquadrão de três pessoas enfrentando ondas de Eclipsitas, sua primeira prioridade deve ser romper rapidamente as fileiras do inimigo.",
  ui_story_5080_50800100_77_dialog_content = "Com um atirador no esquadrão, o ataque deve ser deixado quase inteiramente para o lancero, enquanto os outros se concentram em seu objetivo.",
  ui_story_5080_50800100_78_dialog_content = "Mas já que você escolheu lutar defensivamente... Lançador, por que você continua desviando sua atenção para proteger sua franco-atiradora? Considerando que ela é mais ágil do que você, deveria se concentrar em proteger a pessoa atrás de você.",
  ui_story_5080_50800100_79_dialog_content = "(T-Tão rigoroso.)",
  ui_story_5080_50800100_80_dialog_content = "De alguma forma, estou sendo lembrado de alguém...",
  ui_story_5080_50800100_81_dialog_content = "Por que todos vocês estão me encarando?",
  ui_story_5080_50800100_82_dialog_content = "Mas ainda assim, acho difícil confiar em alguém que nos testou de maneira tão perigosa.",
  ui_story_5080_50800100_83_dialog_content = "... Isso não faz diferença para mim. Meu entendimento original era de que apenas duas pessoas foram designadas para esta missão; Eu não esperava que a princesa de Lumopolis também estivesse aqui.",
  ui_story_5080_50800100_84_dialog_content = "Você investigou o meu passado?",
  ui_story_5080_50800100_85_dialog_content = "Não fique tão surpreso. Eu descobri tudo isso apenas olhando para você.",
  ui_story_5080_50800100_86_dialog_content = "Quanto a você, O Último Celestita... De acordo com as regulamentações da Illumina, estranhos não são permitidos em nossas missões. Mas, como o Comandante estava disposto a abrir uma exceção para você, não tenho mais nada a dizer.",
  ui_story_5080_50800100_87_dialog_content = "De-Deveria agradecer por isso...?",
  ui_story_5080_50800100_88_dialog_content = "Meu nome é Rachel. Serei seu oficial comandante para esta missão.",
  ui_story_5080_50800100_89_dialog_content = "Uh, prazer em conhecer você. Eu sou...",
  ui_story_5080_50800100_90_dialog_content = "Durante esta missão, realizaremos operações como uma unidade coesa. Uma vez que a missão esteja concluída, o esquadrão será dispensado; até lá, nos comunicaremos usando codinomes.",
  ui_story_5080_50800100_91_dialog_content = "Você é o Celestita Um.",
  ui_story_5080_50800100_92_dialog_content = "Você é Filhote Dois.",
  ui_story_5080_50800100_93_dialog_content = "...",
  ui_story_5080_50800100_94_dialog_content = "Quanto a você, princesa de Lumopolis, você é uma completa estranha para o exército da Federação Illumina. No entanto, como você chegou junto, isso significa que você também concordou com as condições da missão.",
  ui_story_5080_50800100_95_dialog_content = "De agora em diante, vou me referir a você como o Lanceiro Branco.",
  ui_story_5080_50800100_96_dialog_content = "Eu deveria concordar com isso? Eu esperava tanto de um soldado da Illumina...",
  ui_story_5080_50800100_97_dialog_content = "Isso é altamente desrespeitoso.",
  ui_story_5080_50800100_98_dialog_content = "Isso deve ser como nossas forças especiais operam. Eu não acho que ela quis dizer algo com isso, Carleen.",
  ui_story_5080_50800100_99_dialog_content = "Os três podem me chamar de Caçador Águia Zero ou Capitão.",
  ui_story_5080_50800100_100_dialog_content = "Entendido... Caçador Águia Zero.",
  ui_story_5080_50800100_101_dialog_content = "(Ela parecia tão carinhosa há um minuto atrás... por que ela de repente parece tão fria e distante?)",
  ui_story_5080_50800100_102_dialog_content = "Capitão Rach—Capitão! Você pode não me conhecer, mas eu era um dos seus juniores. Mesmo estando em um campo de estudo diferente, eu sabia tudo sobre você.",
  ui_story_5080_50800100_103_dialog_content = "Tudo sobre... eu...?",
  ui_story_5080_50800100_104_dialog_content = "Isso mesmo! Quando eu ainda estava na escola, ouvimos falar de todas as suas conquistas e como você liderou o Esquadrão Eagleeye.",
  ui_story_5080_50800100_105_dialog_content = "O Comandante Hiiro sempre nos diz para aprender com o seu exemplo sempre que você volta de uma missão bem-sucedida.",
  ui_story_5080_50800100_106_dialog_content = "Mesmo que muita coisa tenha acontecido desde então, e mesmo que eu raramente retorne a Illumina por causa das minhas aventuras com PlayerName, eu ainda te admiro.",
  ui_story_5080_50800100_107_dialog_content = "Só podíamos adivinhar o que tinha acontecido quando paramos de ouvir notícias suas. Mas agora está claro que você e o Esquadrão Eagleeye devem ter estado em uma missão secreta, certo?",
  ui_story_5080_50800100_108_dialog_content = "...",
  ui_story_5080_50800100_109_dialog_content = "E com você no comando da nossa missão, tenho certeza de que será um enorme sucesso! Esta é a oportunidade perfeita para eu estudar seu trabalho em ação também.",
  ui_story_5080_50800100_110_dialog_content = "Vamos deixar a conversa fiada de lado por enquanto. Venha comigo para que possamos discutir a missão.",
  ui_story_5080_50800100_111_dialog_content = "(Parece que ela não quer trazer o passado à tona de jeito nenhum... Mas por quê? Ela é uma lenda, afinal de contas...)",
  ui_story_5080_50800100_112_dialog_content = "Para esta missão, vou te levar ao fundo do deserto, território do Rediesel Wrench, para investigar a presença de um Eclipsite único.",
  ui_story_5080_50800100_113_dialog_content = "Este tipo de Eclipsita comanda o poder da lava. Como tal, só aparece em ambientes de alta temperatura, onde tende a deixar sinais claros de seus movimentos.",
  ui_story_5080_50800100_114_dialog_content = "Eclipsitas como esses representam uma séria ameaça e devem ser tratados com cautela.",
  ui_story_5080_50800100_115_dialog_content = "Todos vocês devem seguir meu comando sem desvios se quiserem evitar baixas inesperadas.",
  ui_story_5080_50800100_116_dialog_content = "Além disso, haverá momentos em que terei que investigar outros assuntos. Você está livre para se movimentar por conta própria durante esses momentos.",
  ui_story_5080_50800100_117_dialog_content = "Quais outros assuntos, posso perguntar?",
  ui_story_5080_50800100_118_dialog_content = "Me diga, você sabe algo sobre o Esquadrão <color=#FFB400>Freebird</color>?",
  ui_story_5080_50800100_119_dialog_content = "Não posso dizer que sim... Desculpe.",
  ui_story_5080_50800100_120_dialog_content = "Então não há nada com que você precise se preocupar. Isso está fora do escopo da nossa missão, então não há necessidade de você me ajudar... Embora você seja bem-vindo para me dar quaisquer pistas que possa encontrar.",
  ui_story_5080_50800100_121_dialog_content = "Somos bastante amigos de Sinsa. Se nossa missão é investigar os Eclipsitas, devemos tentar pedir a ajuda dele.",
  ui_story_5080_50800100_122_dialog_content = "Entendo... Talvez seja por isso que o Grande Marechal te escolheu para essa missão. A troca de informações pode ser útil e eficiente. Você tem minha permissão para entrar em contato com ele, agora vá.",
  ui_story_5080_50800100_123_dialog_content = "Hã? Mas e você, Capitão...?",
  ui_story_5080_50800100_124_dialog_content = "Como oficial da Federação Illumina, não tenho negócios para discutir com foras da lei do deserto. Se nos encontrássemos, eu não teria escolha a não ser prendê-los e levá-los à justiça.",
  ui_story_5080_50800100_125_dialog_content = "Agora vá. Ainda tenho meus próprios assuntos para investigar.",
  ui_story_5080_50800100_126_dialog_content = "Sozinho? Mas este lugar é tão perigoso, Capitão... Não deveríamos nos dividir em pares?",
  ui_story_5080_50800100_127_dialog_content = "Dado o histórico de vocês lutando lado a lado, a sinergia de combate de vocês será mais eficaz sem a adição de um lutador desconhecido como eu.",
  ui_story_5080_50800100_128_dialog_content = "Agora siga para o acampamento base da Rediesel Wrench e comece a coletar informações - Isso é uma ordem.",
  ui_story_5080_50800100_129_dialog_content = "Encontrarei com você em um momento posterior.",
  ui_story_5080_50800100_130_dialog_content = "E assim mesmo, ela se foi.",
  ui_story_5080_50800100_131_dialog_content = "Deixando a falta de modos de lado, ela é inegavelmente uma soldada capaz.",
  ui_story_5080_50800100_132_dialog_content = "... Ei, Vice? Ainda estou pensando em algo que Rachel disse agora mesmo.",
  ui_story_5080_50800100_133_dialog_content = "O Esquadrão Freebird que ela mencionou... Poderia estar de alguma forma conectado ao Esquadrão Eagleeye?",
  ui_story_5080_50800100_134_dialog_content = "Não tenho certeza. Eles podem ser semelhantes apenas no nome, mas... Huh? O Esquadrão Freebird é realmente da Illumina...",
  ui_story_5080_50800100_135_dialog_content = "Se nossa missão atual é investigar a presença de um certo Eclipsita, por que o Capitão também está investigando um de seus esquadrões companheiros?",
  ui_story_5080_50800100_136_dialog_content = "Eu não vejo a conexão de jeito nenhum... Mas, julgando pelo caráter dela, duvido que ela faria algo sem motivo.",
  ui_story_5080_50800100_137_dialog_content = "Ah, você também está me deixando curioso... De qualquer forma, a Chefe Philyshy deve ter a resposta. Deixe-me perguntar a ela.",
  ui_story_5080_50800100_138_dialog_content = "Miau? Uma comunicação surpresa de Vice. Você se deparou com algum tipo de problema?",
  ui_story_5080_50800100_139_dialog_content = "Eu só queria perguntar se você tem alguma informação sobre um grupo conhecido como Esquadrão Freebird?",
  ui_story_5080_50800100_140_dialog_content = "Hmm... Bem, a convenção de nomes parece com a nossa, mas é definitivamente de algum tempo atrás. Tenho certeza de que posso encontrar algo em nossos arquivos.",
  ui_story_5080_50800100_141_dialog_content = "Obrigado, Chefe Philyshy. Estou tão curioso sobre isso. Com certeza vou trazer para você uma esfirra de peixe de primeira qualidade na próxima vez que nos encontrarmos!",
  ui_story_5080_50800100_142_dialog_content = "Contanto que a informação não seja classificada, não fará mal compartilhá-la com você - Mas de qualquer maneira, estarei esperando aquele peixe!",
  ui_story_5080_50800100_143_dialog_content = "Desculpe pela espera, miau! Diz aqui que o Esquadrão Freebird existiu há quase quarenta anos. Eles eram uma equipe de operações especiais de elite com mais de uma dúzia de missões altamente perigosas concluídas sem falhas.",
  ui_story_5080_50800100_144_dialog_content = "Mas durante a última missão deles, foram enviados ao Deserto de Rediesel em busca de algo específico. E essa missão... terminou em fracasso, miau.",
  ui_story_5080_50800100_145_dialog_content = "Infelizmente, o restante dos detalhes neste arquivo são tão altamente classificados que nem mesmo tenho autorização para visualizá-los.",
  ui_story_5080_50800100_146_dialog_content = "O que? Existem arquivos que nem você consegue acessar?",
  ui_story_5080_50800100_147_dialog_content = "Não consigo nem ver o nome do líder do esquadrão deles... Mas quando algo é classificado assim por tanto tempo, geralmente implica que uma pessoa desertou da Federação.",
  ui_story_5080_50800100_148_dialog_content = "Isso é algo bem interessante. Onde você encontrou esse nome, miau?",
  ui_story_5080_50800201_1_dialog_content = "Eu me pergunto o que está demorando tanto o Sinsa?",
  ui_story_5080_50800201_2_dialog_content = "Eles estão longe de nós agora e estão todos muito ocupados trabalhando em algum tipo de projeto.",
  ui_story_5080_50800201_3_dialog_content = "...",
  ui_story_5080_50800201_4_dialog_content = "Você está bem, Vice? Por que você parece tão sério?",
  ui_story_5080_50800201_5_dialog_content = "Hã? Ah, estou bem... Só estou me perguntando por que o Capitão mencionou um esquadrão de tanto tempo atrás.",
  ui_story_5080_50800201_6_dialog_content = "Não apenas isso, mas um esquadrão cujo capitão era suspeito de deserção.",
  ui_story_5080_50800201_7_dialog_content = "Considerando a maneira como ela faz as coisas, eu diria que ela provavelmente se especializa em coletar informações.",
  ui_story_5080_50800201_8_dialog_content = "Talvez seja isso que ela está fazendo: coletando informações sobre o desertor suspeito?",
  ui_story_5080_50800201_9_dialog_content = "Possivelmente, mas isso foi quase quarenta anos atrás. Qual seria o ponto de continuar uma investigação tão antiga?",
  ui_story_5080_50800201_10_dialog_content = "Será que Rachel está de alguma forma ligado àquela pessoa?",
  ui_story_5080_50800201_11_dialog_content = "O Esquadrão Freebird... E o Esquadrão Eagleeye...",
  ui_story_5080_50800201_12_dialog_content = "Ei! O que há com todas essas caras sérias?",
  ui_story_5080_50800201_13_dialog_content = "Sinsa!",
  ui_story_5080_50800201_14_dialog_content = "Há quanto tempo! Você parece muito mais forte agora também! Finalmente decidiu trabalhar para nós?",
  ui_story_5080_50800201_15_dialog_content = "Uh, isso provavelmente ainda é...",
  ui_story_5080_50800201_16_dialog_content = "Hahaha! Não se preocupe com isso. Você pode nos encontrar sempre que decidir! Então, o que te traz aqui hoje, hein?",
  ui_story_5080_50800201_17_dialog_content = "Na verdade, estamos aqui em uma missão especial... Você sabe sobre algum Eclipsita único ou anormal aqui no deserto?",
  ui_story_5080_50800201_18_dialog_content = "Eh? Tal como...?",
  ui_story_5080_50800201_19_dialog_content = "Uh, deixe-me pensar... Talvez um que pareça estar queimando? Ou um que fica perto de vulcões?",
  ui_story_5080_50800201_20_dialog_content = "Do que você está falando? Há toneladas de Eclipsitas à espreita ao redor dos vulcões.",
  ui_story_5080_50800201_21_dialog_content = "Sim, mas esses Eclipsitas são particularmente atraídos por vulcões e podem até mesmo manipular o poder da lava.",
  ui_story_5080_50800201_22_dialog_content = "Eles são anormalmente fortes e deixam sinais óbvios de seus movimentos por onde passam.",
  ui_story_5080_50800201_23_dialog_content = "Você consegue pensar em algum Eclipsita que se encaixe?",
  ui_story_5080_50800201_24_dialog_content = "Eclipsitas de Lava... De jeito nenhum. Já faz mais de uma década...",
  ui_story_5080_50800201_25_dialog_content = "Então você sabe algo sobre eles?",
  ui_story_5080_50800201_26_dialog_content = "Por favor, nos diga o que você sabe. Precisamos de tanta informação sobre eles quanto possível agora mesmo.",
  ui_story_5080_50800201_27_dialog_content = "Na opinião da maioria das pessoas, isso é história antiga. Também tem muito a ver com a nossa família...",
  ui_story_5080_50800201_28_dialog_content = "Mas, já que é tão importante para vocês, acho que posso contar sobre isso.",
  ui_story_5080_50800201_29_dialog_content = "Eu sei sobre os Eclipsitas que você está procurando... Ou melhor, os antigos membros da <color=#FFB400>Rediesel Wrench</color> tinham uma rixa de sangue com eles.",
  ui_story_5080_50800201_30_dialog_content = "Como assim?",
  ui_story_5080_50800201_31_dialog_content = "Isso aconteceu durante a <color=#FFB400>Crise Darkover</color>. Naquela época, eu era apenas um garoto de recados para o líder do Rediesel Wrench.",
  ui_story_5080_50800201_32_dialog_content = "Um dia, os Eclipsitas passaram por nossa antiga casa como uma tempestade de areia, e não tivemos escolha a não ser deixá-la para trás.",
  ui_story_5080_50800201_33_dialog_content = "Para nos dar tempo para escapar, nosso líder levou alguns de nossos melhores lutadores para cobrir nossa retaguarda.",
  ui_story_5080_50800201_34_dialog_content = "Ainda me lembro do que vi naquele dia... Um verdadeiro monstro, que transformava a areia sob seus pés em vidro derretido...",
  ui_story_5080_50800201_35_dialog_content = "Uhh?",
  ui_story_5080_50800201_36_dialog_content = "O que, você não me ouviu? Eu disse...",
  ui_story_5080_50800201_37_dialog_content = "Hã?!",
  ui_story_5080_50800201_38_dialog_content = "Uau-!",
  ui_story_5080_50800201_39_dialog_content = "Desculpe-me! Ajude-me, <color=#FFB400>Guerreiro Amaldiçoado</color>!",
  ui_story_5080_50800201_40_dialog_content = "Cuidado, PlayerName!",
  ui_story_5080_50800201_41_dialog_content = "Ahhh—Pare com isso, agora!",
  ui_story_5080_50800201_42_dialog_content = "Aaaaaahhh—",
  ui_story_5080_50800201_43_dialog_content = "Desculpe, querida, mas nada pode parar o poder da música!",
  ui_story_5080_50800201_44_dialog_content = "Graças a Deus pelo <color=#FFB400>Guerreiro Amaldiçoado</color> e sua força monstruosa!",
  ui_story_5080_50800201_45_dialog_content = "Zeta? Barbara e Tiny One também?! O que vocês estão fazendo?!",
  ui_story_5080_50800201_46_dialog_content = "Você simplesmente invade a base com seu caminhão, isso é apenas...",
  ui_story_5080_50800201_47_dialog_content = "Não há tempo para explicar! Entre agora!",
  ui_story_5080_50800201_48_dialog_content = "Hã?!",
  ui_story_5080_50800201_49_dialog_content = "Não me diga que você não me ouviu, <color=#FFB400>Guerreiro Amaldiçoado</color>?! Aqueles passos de uma terra distante—",
  ui_story_5080_50800201_50_dialog_content = "Ela está aqui! O Caçador das Areias!",
  ui_story_5080_50800201_51_dialog_content = "Olhe para lá! É—",
  ui_story_5080_50800201_52_dialog_content = "<size=45>Rachel!!!</size>",
  ui_story_5080_50800201_53_dialog_content = "E quem é esse? Tudo bem Zeta, você tem cinco segundos para me dizer que tipo de confusão você se meteu!",
  ui_story_5080_50800201_54_dialog_content = "Ah, isso é ruim...",
  ui_story_5080_50800201_55_dialog_content = "O airbag me prendeu no lugar. Eu não consigo sair!",
  ui_story_5080_50800201_56_dialog_content = "Apenas espere, eu vou te tirar daí.",
  ui_story_5080_50800201_57_dialog_content = "Não! Precisamos nos afastar dela! Ela é a Lacaia do Rei Demônio!",
  ui_story_5080_50800201_58_dialog_content = "Bandidos do Deserto Rediesel! Entreguem o que vocês roubaram!",
  ui_story_5080_50800201_59_dialog_content = "Hum, você é bem ousada, senhora.",
  ui_story_5080_50800201_60_dialog_content = "Com uma olhada mais de perto, você é da Illumina, não é?",
  ui_story_5080_50800201_61_dialog_content = "Espere! Sinsa, Rachel, apenas nos ouça...",
  ui_story_5080_50800201_62_dialog_content = "Tranquilo!",
  ui_story_5080_50800201_63_dialog_content = "Um soldado Illumina que tentou caçar um grupo de nossas crianças e os forçou a bater o carro em nossa base...",
  ui_story_5080_50800201_64_dialog_content = "Alguns bandidos do deserto tiveram a audácia de roubar meus camaradas de armas... Não terei piedade de vocês!",
  ui_story_5080_50800201_65_dialog_content = "Procurando por uma luta, hein? Bom! Faz muito tempo que não dou socos em vocês!",
  ui_story_5080_50800201_66_dialog_content = "Venha até mim!",
  ui_story_5080_50800201_67_dialog_content = "Isso não está certo! Vice, Carleen, temos que impedi-los!",
  ui_story_5080_50800201_68_dialog_content = "Vamos fazer isso juntos, agora vamos!",
  ui_story_5080_50800202_1_dialog_content = "Insetos voadores irritantes - vou esmagar cada um de vocês!",
  ui_story_5080_50800202_2_dialog_content = "O que mais você recebe agora?",
  ui_story_5080_50800202_3_dialog_content = "Não se mexa. A menos que queira ser lançado ao céu, é claro...",
  ui_story_5080_50800202_4_dialog_content = "Então você plantou explosivos em mim agora, huh? Nada mal.",
  ui_story_5080_50800202_5_dialog_content = "Nesta distância, nenhum de nós sobreviverá à explosão.",
  ui_story_5080_50800202_6_dialog_content = "E ainda assim você não parece estar com medo... Eu gosto disso! Agora, vamos descobrir o que acontece a seguir!",
  ui_story_5080_50800202_7_dialog_content = "Estou mais do que disposto a dar minha vida se isso significar derrubar o líder da Rediesel Wrench...",
  ui_story_5080_50800202_8_dialog_content = "Ei, ei, ei! Já chega, vocês dois!",
  ui_story_5080_50800202_9_dialog_content = "A missão, Capitão! Pense na missão!",
  ui_story_5080_50800202_10_dialog_content = "O que os outros farão se algo acontecer com você, Sinsa?!",
  ui_story_5080_50800202_11_dialog_content = "As crianças aqui ainda precisam de você!",
  ui_story_5080_50800202_12_dialog_content = "\"Crianças\"?",
  ui_story_5080_50800202_13_dialog_content = "Boo-hoo—",
  ui_story_5080_50800202_14_dialog_content = "Vamos apenas abaixar as armas e descobrir o que está acontecendo, ok?",
  ui_story_5080_50800202_15_dialog_content = "Eu sou o que provocou o Lacaio do Rei Demônio. Eu assumirei total responsabilidade, então apenas deixe meus amigos irem!",
  ui_story_5080_50800202_16_dialog_content = "...",
  ui_story_5080_50800202_17_dialog_content = "O que está acontecendo aqui, Zeta?",
  ui_story_5080_50800202_18_dialog_content = "Tudo começou com a lenda de Zeta, o maior guerreiro de todos os tempos—",
  ui_story_5080_50800202_19_dialog_content = "Depois de praticar arduamente a arte das corridas, ainda não consegui derrotar a Bruxa da Pista em uma disputa de velocidade.",
  ui_story_5080_50800202_20_dialog_content = "Eu tinha certeza que tinha algo a ver com ela ter o Último Celestita como aliado, então decidi procurar um poderoso camarada para mim.",
  ui_story_5080_50800202_21_dialog_content = "Foi quando encontrei Barbara, a <color=#FFB400>Cantora Supernova</color> e Regina discutindo sobre algum tipo de competição de canto!",
  ui_story_5080_50800202_22_dialog_content = "\"Ó poderoso guerreiro Zeta, por favor, empreste-me sua força!\"",
  ui_story_5080_50800202_23_dialog_content = "\"Com você ao meu lado, posso atrair um público maior do que Regina jamais poderia esperar! Meu público é a fonte do meu poder!\"",
  ui_story_5080_50800202_24_dialog_content = "\"Parece divertido! Só não se esqueça de mim: o leal <color=#FFB400>Mestre de Armas</color> de Zeta!\"",
  ui_story_5080_50800202_25_dialog_content = "Ah! Seriam estes os aliados que procuro? Eles devem ter sido atraídos pela minha majestade!",
  ui_story_5080_50800202_26_dialog_content = "E assim, partimos em nossa gloriosa jornada para percorrer o furioso deserto e reunir ainda mais fãs!",
  ui_story_5080_50800202_27_dialog_content = "E com a nossa mais recente e incrível invenção, o <color=#FFB400>Super Idol-mobile Rediesel</color>, entramos na batalha—",
  ui_story_5080_50800202_28_dialog_content = "O quê? Você poderia por favor ir direto à parte importante?!",
  ui_story_5080_50800202_29_dialog_content = "... Suspirar.",
  ui_story_5080_50800202_30_dialog_content = "Enquanto nossa equipe aventurava-se pelo deserto com nossa canção ardendo em nossos corações, de repente notei algo!",
  ui_story_5080_50800202_31_dialog_content = "Um falcão solitário empoleirado no topo das areias.",
  ui_story_5080_50800202_32_dialog_content = "\"Aposto que poderíamos usar esse pequeno para iluminação ou som!\"",
  ui_story_5080_50800202_33_dialog_content = "Essas foram as palavras do meu Mestre de Armas—Mas eu pude ver sua verdadeira força por mim mesmo.",
  ui_story_5080_50800202_34_dialog_content = "Então decidi trazer a águia como membro da nossa festa!",
  ui_story_5080_50800202_35_dialog_content = "Mas não muito tempo depois, um ser maligno veio perseguindo a águia. Ela era implacável em sua perseguição e até nos atacou.",
  ui_story_5080_50800202_36_dialog_content = "Os tiros dela foram alguns dos mais temíveis que já vi. Eu estava com muito medo para parar o carro... Quer dizer, eu estava com muito medo pela segurança dos meus companheiros!",
  ui_story_5080_50800202_37_dialog_content = "Então você bateu em cheio na nossa casa?!",
  ui_story_5080_50800202_38_dialog_content = "E-Eu tinha fé que o Guerreiro Amaldiçoado seria capaz de nos parar a tempo!",
  ui_story_5080_50800202_39_dialog_content = "Céus, Zeta...",
  ui_story_5080_50800202_40_dialog_content = "... Já tive o suficiente.",
  ui_story_5080_50800202_41_dialog_content = "Devolva o <color=#FFB400>Caçador de Águias Três</color> para mim agora mesmo.",
  ui_story_5080_50800301_1_dialog_content = "Então o nome dele é <color=#FFB400>Eagle Hunter Three</color>, huh... Que nome legal!",
  ui_story_5080_50800301_2_dialog_content = "Tudo bem... Vendo que o <color=#FFB400>Águia Caçador Três</color> já tem um dono, eu vou devolvê-lo... Apenas parem de lutar, por favor...",
  ui_story_5080_50800301_3_dialog_content = "Ei! Onde você pensa que está indo?!",
  ui_story_5080_50800301_4_dialog_content = "Você não vai simplesmente ir embora depois de destruir nosso acampamento e machucar essas pobres crianças, vai?!",
  ui_story_5080_50800301_5_dialog_content = "Independentemente do que você diga, eles são os que roubaram <color=#FFB400>Eagle Hunter Three</color> de mim primeiro.",
  ui_story_5080_50800301_6_dialog_content = "Pode ser, mas nós, bandidos de Rediesel, sempre cuidamos uns dos outros, não importa o quê.",
  ui_story_5080_50800301_7_dialog_content = "Então você ainda quer lutar?",
  ui_story_5080_50800301_8_dialog_content = "Deem um tempo, vocês dois!",
  ui_story_5080_50800301_9_dialog_content = "O que está acontecendo aqui fora? O lugar todo está uma bagunça e todos parecem tão nervosos!",
  ui_story_5080_50800301_10_dialog_content = "J-Jeriah?!",
  ui_story_5080_50800301_11_dialog_content = "E o que exatamente você está fazendo aqui, hein?",
  ui_story_5080_50800301_12_dialog_content = "Não é como se eu quisesse vir... Mas você não ouviu o vulcão rugindo agora, Sinsa?",
  ui_story_5080_50800301_13_dialog_content = "O Vulcão Rugidor despertou, assim como fez <color=#FFB400>quinze anos atrás</color>.",
  ui_story_5080_50800301_14_dialog_content = "O que seria?",
  ui_story_5080_50800301_15_dialog_content = "Ei, chefe! Você está bem?",
  ui_story_5080_50800301_16_dialog_content = "Finalmente limpamos a maioria dos destroços lá fora. Tá todo mundo bem?",
  ui_story_5080_50800301_17_dialog_content = "Tiny One! Barbara! Zeta! Onde vocês três estão?",
  ui_story_5080_50800301_18_dialog_content = "Não entrem assim de repente, rapazes!",
  ui_story_5080_50800301_19_dialog_content = "Estamos falando de coisas importantes! Ei! Parem com isso, seus idiotas—!!!",
  ui_story_5080_50800301_20_dialog_content = "Estão dizendo que o Vulcão Rugidor está acordado novamente. É verdade?",
  ui_story_5080_50800301_21_dialog_content = "Você está bem, Zeta? Você não está ferido, está?",
  ui_story_5080_50800301_22_dialog_content = "Não! Estou perfeitamente bem, Princesa Kindheart!",
  ui_story_5080_50800301_23_dialog_content = "Até eu ouvi o estrondo agora. Não há dúvida: o Vulcão Rugidor está ativo novamente.",
  ui_story_5080_50800301_24_dialog_content = "A última vez que entrou em erupção foi durante a <color=#FFB400>Crise Darkover</color>, e tem estado adormecida desde então. O que poderia ter acontecido—",
  ui_story_5080_50800301_25_dialog_content = "<size=45>Todos vocês calem a boca já!!!</size>",
  ui_story_5080_50800301_26_dialog_content = "Droga, para onde foi aquele idiota da Illumina?!",
  ui_story_5080_50800301_27_dialog_content = "Hã? Que idiota da Illumina? Você não está falando de mim, está?",
  ui_story_5080_50800301_28_dialog_content = "Huff—Huff—",
  ui_story_5080_50800301_29_dialog_content = "*ofegante* Nós... devemos estar seguros... aqui.",
  ui_story_5080_50800301_30_dialog_content = "D-Não fale, apenas tente recuperar o fôlego.",
  ui_story_5080_50800301_31_dialog_content = "Foi por pouco. Se não estivéssemos em bons termos com Sinsa, teria sido um desastre ainda maior.",
  ui_story_5080_50800301_32_dialog_content = "Felizmente, seu raciocínio rápido nos permitiu escapar enquanto ele estava distraído.",
  ui_story_5080_50800301_33_dialog_content = "... Eu tinha a sensação de que essas pessoas seriam irracionais.",
  ui_story_5080_50800301_34_dialog_content = "Afinal, eles não são nada além de bandidos e desertores.",
  ui_story_5080_50800301_35_dialog_content = "Não é isso!",
  ui_story_5080_50800301_36_dialog_content = "Os membros da Rediesel Wrench não são tão ruins assim... Se tivéssemos apenas abordado Sinsa de maneira amigável, ele teria sido perfeitamente razoável!",
  ui_story_5080_50800301_37_dialog_content = "Eles também vivem no Deserto Rediesel há anos. Se alguém sabe mais sobre o Esquadrão Freebird, são eles...",
  ui_story_5080_50800301_38_dialog_content = "Debater a credibilidade de um bando de desertores é inútil, então vamos apenas deixar pra lá.",
  ui_story_5080_50800301_39_dialog_content = "Enquanto você estava coletando informações no acampamento deles, consegui encontrar rastros do nosso alvo. Venha comigo.",
  ui_story_5080_50800301_40_dialog_content = "Você poderia pelo menos me ouvir...",
  ui_story_5080_50800301_41_dialog_content = "Dê uma olhada. A areia aqui foi queimada e a área tem vestígios de cinzas vulcânicas.",
  ui_story_5080_50800301_42_dialog_content = "Não há erro. É logo adiante.",
  ui_story_5080_50800301_43_dialog_content = "Mas... Há vários conjuntos de rastros.",
  ui_story_5080_50800301_44_dialog_content = "É possível que nosso alvo já tenha se reproduzido. Fiquem alerta.",
  ui_story_5080_50800301_45_dialog_content = "Alvos avistados, Capitão!",
  ui_story_5080_50800301_X45_dialog_content = "Graah... Urk—",
  ui_story_5080_50800301_46_dialog_content = "Isto é... lava? Não, são Eclipsitas!",
  ui_story_5080_50800301_47_dialog_content = "Eles são completamente diferentes de tudo que já vimos antes. Eles parecem pilhas ambulantes de lava...",
  ui_story_5080_50800301_48_dialog_content = "Você está certo, e a aparência estranha deles torna difícil identificar suas partes fracas.",
  ui_story_5080_50800301_49_dialog_content = "Com esse calor intenso protegendo-os, duvido que ataques à distância tenham muito efeito.",
  ui_story_5080_50800301_50_dialog_content = "Prepare-se para a batalha.",
  ui_story_5080_50800301_51_dialog_content = "Mas...",
  ui_story_5080_50800301_52_dialog_content = "Sua força é mais do que suficiente para eles, Lanceiro Branco. Como você é mais adequado para lutar de frente, ficará na frente de nossa formação.",
  ui_story_5080_50800301_53_dialog_content = "Desculpe, mas você ainda não tem autoridade sobre mim.",
  ui_story_5080_50800301_54_dialog_content = "Você pode invocar o poder de um corcel voador, certo? Você deveria usá-lo para lançar ataques aéreos surpresa durante o combate.",
  ui_story_5080_50800301_55_dialog_content = "Julgando pela composição de seus corpos, parece difícil para eles manterem sua proteção total. Encontrar até a menor brecha em suas defesas tornará seus ataques fatais.",
  ui_story_5080_50800301_56_dialog_content = "...",
  ui_story_5080_50800301_57_dialog_content = "Enquanto o White Lancer enfrenta os Eclipsitas em combate, Hatchling Two, use seu Torrente Rápido para atacá-los de longe.",
  ui_story_5080_50800301_58_dialog_content = "Independentemente do tipo, todos os Eclipsitas exporão seus pontos fracos quando sob ataque pesado. Esse será o seu momento para atacar.",
  ui_story_5080_50800301_59_dialog_content = "Eles certamente perderão o equilíbrio assim que explorarmos suas fraquezas, o que permitirá ao White Lancer dar o golpe fatal.",
  ui_story_5080_50800301_60_dialog_content = "Entendido!",
  ui_story_5080_50800301_61_dialog_content = "Os Caçadores de Águia e eu forneceremos fogo supressor e direcionaremos os Eclipsitas em direção ao Lancer Branco.",
  ui_story_5080_50800301_62_dialog_content = "O fogo constante deve impedi-los de se agruparem, tornando mais fácil eliminá-los um a um.",
  ui_story_5080_50800301_63_dialog_content = "Essa é uma estratégia e tanto... Faremos como você disse então.",
  ui_story_5080_50800301_64_dialog_content = "(Mesmo que ela só os tenha visto em combate uma vez, Rachel conhece exatamente suas habilidades e como usá-las em seu máximo potencial...)",
  ui_story_5080_50800301_65_dialog_content = "Celestita Um.",
  ui_story_5080_50800301_66_dialog_content = "Muito mal!",
  ui_story_5080_50800301_67_dialog_content = "Você estará encarregado de comandar esta batalha.",
  ui_story_5080_50800301_68_dialog_content = "Uhh?",
  ui_story_5080_50800301_69_dialog_content = "Mesmo as preparações de combate mais minuciosas podem se tornar inúteis no calor da batalha.",
  ui_story_5080_50800301_70_dialog_content = "Sua habilidade única de perceber rastros de luz torna você um comandante muito mais capaz para essa luta.",
  ui_story_5080_50800301_71_dialog_content = "... Não só isso, vocês três têm muita experiência lutando como uma equipe.",
  ui_story_5080_50800301_72_dialog_content = "Se alguém deve liderá-los na batalha... É você.",
  ui_story_5080_50800301_73_dialog_content = "Rachel, você...",
  ui_story_5080_50800301_74_dialog_content = "Isso é \"Capitão\" para você.",
  ui_story_5080_50800301_75_dialog_content = "Agora prepare-se para a batalha, Celestita Um!",
  ui_story_5080_50800302_1_dialog_content = "Cuidado, Capitão!",
  ui_story_5080_50800302_2_dialog_content = "Urgh... Agora, Lanceiro Branco!",
  ui_story_5080_50800302_3_dialog_content = "Véus Penetrantes!",
  ui_story_5080_50800302_4_dialog_content = "Ah não, o Capitão está ferido! Nós temos que...",
  ui_story_5080_50800302_5_dialog_content = "Concentre-se na batalha, Hatchling Two! Ainda há outro Eclipsita indo em sua direção!",
  ui_story_5080_50800302_6_dialog_content = "Águia Caçador Um, Águia Caçador Dois, preparem-se para interceptar!",
  ui_story_5080_50800302_7_dialog_content = "Graaaaah—!",
  ui_story_5080_50800302_8_dialog_content = "... Bem na hora.",
  ui_story_5080_50800302_9_dialog_content = "Essa foi por pouco... Acho que pegamos o último deles.",
  ui_story_5080_50800302_10_dialog_content = "O que foi isso agora, Filhote Dois?",
  ui_story_5080_50800302_11_dialog_content = "(Eu...)",
  ui_story_5080_50800302_12_dialog_content = "Não deixe suas emoções nublarem seu julgamento, soldado.",
  ui_story_5080_50800302_13_dialog_content = "Mesmo que eu me machuque, a missão vem antes de qualquer coisa. Lembre-se disso.",
  ui_story_5080_50800302_14_dialog_content = "Acabamos com um esquadrão inteiro de poderosos Eclipsitas. Esta ferida é o menor preço que poderíamos ter pago pela nossa vitória.",
  ui_story_5080_50800302_15_dialog_content = "Diga-me... depois de passar tanto tempo com seus amigos, você esqueceu o que significa ser um soldado da Illumina?",
  ui_story_5080_50800302_16_dialog_content = "N-Não, senhora... Não é isso de jeito nenhum.",
  ui_story_5080_50800302_17_dialog_content = "Você está sendo muito duro, Rachel. Vice estava apenas preocupado com você.",
  ui_story_5080_50800302_18_dialog_content = "... Codinomes, Caelestite Um. Perder o foco no campo de batalha pode ter consequências graves. E se ela também tivesse se machucado agora mesmo?",
  ui_story_5080_50800302_19_dialog_content = "Se você seguir minhas instruções e a missão ainda resultar em falha, então a culpa cai sobre mim.",
  ui_story_5080_50800302_20_dialog_content = "Assumo total responsabilidade pela segurança e bem-estar dos meus subordinados... Contanto que você confie em mim.",
  ui_story_5080_50800302_21_dialog_content = "Como um capitão veterano, tudo o que você disse agora é completamente verdadeiro.",
  ui_story_5080_50800302_22_dialog_content = "Entendo e concordo com sua maneira de pensar.",
  ui_story_5080_50800302_23_dialog_content = "Carleen?",
  ui_story_5080_50800302_24_dialog_content = "Ah... Vice, você tá bem?",
  ui_story_5080_50800302_25_dialog_content = "Uhum...",
  ui_story_5080_50800302_26_dialog_content = "Esses Eclipsitas... Dê uma olhada nos corpos deles...",
  ui_story_5080_50800302_27_dialog_content = "Capitão, você ainda está sangrando...",
  ui_story_5080_50800302_28_dialog_content = "Apenas deixe-a em paz. Ela não vai te ouvir de qualquer maneira.",
  ui_story_5080_50800302_29_dialog_content = "Ela está carregando um peso que nenhum de nós consegue compreender.",
  ui_story_5080_50800302_30_dialog_content = "Conheço bem o olhar em seus olhos. Eu já vi isso tantas vezes em Lumópolis...",
  ui_story_5080_50800302_31_dialog_content = "Estou lutando na linha de frente há muito tempo e já vi mais Eclipsitas do que posso contar.",
  ui_story_5080_50800302_32_dialog_content = "Mas eu nunca encontrei Eclipsitas assim antes.",
  ui_story_5080_50800302_33_dialog_content = "Julgando por suas cabeças, esses Eclipsitas estiveram fora da Zona Escura por muito tempo.",
  ui_story_5080_50800302_34_dialog_content = "Além disso, a anatomia deles indica que a evolução deles não foi direcionada para o combate.",
  ui_story_5080_50800302_35_dialog_content = "A carne deles é altamente resistente ao calor, e seus corpos podem armazenar quantidades significativas de energia... Esses Eclipsitas evoluíram para se adaptar ao seu ambiente.",
  ui_story_5080_50800302_36_dialog_content = "Estranhamente, os corpos deles permanecem por muito mais tempo do que os de outros Eclipsitas...",
  ui_story_5080_50800302_37_dialog_content = "... Eu também notei algo. Eles parecem todos incrivelmente semelhantes.",
  ui_story_5080_50800302_38_dialog_content = "Muito perspicaz de você notar... Além de suas tendências emocionais, você é um digno capitão de reconhecimento.",
  ui_story_5080_50800302_39_dialog_content = "Desculpe, mas o que você quer dizer com \"notavelmente semelhante\"? A maioria dos Eclipsitas não se parecem?",
  ui_story_5080_50800302_40_dialog_content = "Eu diria que os outros Eclipsites são exatamente iguais.",
  ui_story_5080_50800302_41_dialog_content = "Muitos soldados pensaram que os Eclipsitas não se reproduzem no sentido normal.",
  ui_story_5080_50800302_42_dialog_content = "Por outro lado, esses Eclipsitas parecem ter descendido de um ancestral comum... eles se parecem, mas não são exatamente iguais.",
  ui_story_5080_50800302_43_dialog_content = "As características que eles possuem são semelhantes àquelas que são passadas de pais para filhos.",
  ui_story_5080_50800302_44_dialog_content = "Nossos registros indicam que a última investigação sobre esses Eclipsitas foi há mais de trinta anos.",
  ui_story_5080_50800302_45_dialog_content = "Eles são menores do que os observados naquela época, e também menos poderosos. Isso pode ser o resultado de alguma forma desconhecida de reprodução...",
  ui_story_5080_50800302_46_dialog_content = "Correto.",
  ui_story_5080_50800302_47_dialog_content = "Durante a <color=#FFB400>Crise de Darkover</color>, muitas pessoas na Rediesel Wrench viram esses Eclipsitas. Comparados aos de antes, os Eclipsitas que você derrotou eram quase comicamente fracos.",
  ui_story_5080_50800302_48_dialog_content = "Jeriah?! Como é isso—não apareça assim do nada!",
  ui_story_5080_50800302_49_dialog_content = "Bem, afinal, fui designado para este deserto inteiro.",
  ui_story_5080_50800302_50_dialog_content = "Você... Como conseguiu passar despercebido pela detecção do Caçador de Águias Três?",
  ui_story_5080_50800302_51_dialog_content = "Ah, esse é o nome do seu drone? Parece estar com um pequeno mal funcionamento.",
  ui_story_5080_50800302_52_dialog_content = "O quê? Caçador de Águia Três, retorne!",
  ui_story_5080_50800302_53_dialog_content = "Ainda assim, eu nunca esperava ouvir o vulcão rugir como fez há quinze anos ou ver esses caras novamente...",
  ui_story_5080_50800302_54_dialog_content = "O que você sabe sobre eles?",
  ui_story_5080_50800302_55_dialog_content = "Heheh, estou aqui procurando por <color=#FFB400>respostas</color>, assim como você.",
  ui_story_5080_50800302_56_dialog_content = "O transmissor do Caçador Águia Três foi danificado. Também tem algo estranho anexado a ele...",
  ui_story_5080_50800302_57_dialog_content = "Olá? Vocês podem me ouvir? Oláaa...",
  ui_story_5080_50800302_58_dialog_content = "Essa voz...",
  ui_story_5080_50800302_59_dialog_content = "Zeta?",
  ui_story_5080_50800302_60_dialog_content = "Graças ao meu brilhante <color=#FFB400>Mestre de Armas</color>, conseguimos pegar isso, uh... Como você chamou isso de novo?",
  ui_story_5080_50800302_61_dialog_content = "Ah certo, nós \"hackeamos\" isso! Que coisa legal de se fazer... De qualquer forma, hackeamos seu drone e anexamos este comunicador nele.",
  ui_story_5080_50800302_62_dialog_content = "Se você quer que nós <color=#FFB400>consertemos isso</color>, encontre-nos na casa da Jeriah Feiticeira.",
  ui_story_5080_50800302_63_dialog_content = "... Não olhe para mim! Você realmente acha que eu teria inventado um nome assim?",
  ui_story_5080_50800302_64_dialog_content = "O inimigo mexeu com o Eagle Hunter Three. Preciso consertá-lo imediatamente—",
  ui_story_5080_50800302_65_dialog_content = "!!!",
  ui_story_5080_50800302_66_dialog_content = "Meu kit de ferramentas... Quando foi que ele incinerou?!",
  ui_story_5080_50800302_67_dialog_content = "Você estava tão focado na missão anterior que quando se machucou, seu kit de ferramentas também foi chamuscado.",
  ui_story_5080_50800302_68_dialog_content = "Eles disseram que estão nos esperando em sua casa. Qual é a sua conexão com tudo isso, Mensageiro?",
  ui_story_5080_50800302_69_dialog_content = "Como eu disse, eu só vim em busca de respostas. Não estou aqui por nenhum outro motivo.",
  ui_story_5080_50800302_70_dialog_content = "No entanto, sinto uma presença muito familiar vinda de você.",
  ui_story_5080_50800302_71_dialog_content = "Por que não voltamos todos juntos? Podemos até encontrar mais algumas respostas se o fizermos.",
  ui_story_5080_50800302_72_dialog_content = "...",
  ui_story_5080_50800302_73_dialog_content = "Jeriah é um membro sênior da Courier Union. Podemos confiar nela.",
  ui_story_5080_50800302_74_dialog_content = "Então vamos.",
  ui_story_5080_50800401_1_dialog_content = "Desculpe por incomodá-lo assim, Jeriah.",
  ui_story_5080_50800401_2_dialog_content = "Não se preocupe com isso, agora sente-se. Não é a primeira vez mesmo.",
  ui_story_5080_50800401_3_dialog_content = "Hum...",
  ui_story_5080_50800401_4_dialog_content = "Ah! Abaixe-se! O acampamento da Rediesel Wrench está logo à frente!",
  ui_story_5080_50800401_5_dialog_content = "Não se preocupe, eles estão ocupados agora.",
  ui_story_5080_50800401_6_dialog_content = "Argh, essa coisa está completamente quebrada!!! Zeta, seu pequeno monstro... Só espere até eu colocar as mãos em você!!!",
  ui_story_5080_50800401_7_dialog_content = "Ei, não é aquele o carro do Jeriah? Ei, Jeriah! A comida está pronta, se você quiser comer algo conosco!",
  ui_story_5080_50800401_8_dialog_content = "Próxima vez!",
  ui_story_5080_50800401_9_dialog_content = "Acomode-se! Eu vou apenas perguntar ao Azure então.",
  ui_story_5080_50800401_10_dialog_content = "Desacelere um pouco, Jeriah. Há muitas armadilhas à frente.",
  ui_story_5080_50800401_11_dialog_content = "Obrigado pelo lembrete.",
  ui_story_5080_50800401_12_dialog_content = "Ei Jeriah, dê uma olhada neste livro! Ele realmente diz \"Como se Tornar o Chefe da Rediesel Wrench\" na capa? Esses idiotas é melhor que não estejam brincando comigo só porque eu não consigo ler muito bem!",
  ui_story_5080_50800401_13_dialog_content = "Claro que não diz isso. Se você quer que eles parem, então aprenda a ler.",
  ui_story_5080_50800401_14_dialog_content = "Obrigado novamente por nos trazer essas ferramentas na sua última corrida, Jeriah. Eu vou te encaixar em algum momento desta semana para trabalhar no seu carro.",
  ui_story_5080_50800401_15_dialog_content = "Parece um acordo.",
  ui_story_5080_50800401_16_dialog_content = "Jeriah... Acho que você mudou desde a última vez que te vi.",
  ui_story_5080_50800401_17_dialog_content = "Você costumava viver em um lugar tão difícil de encontrar, mas agora você está em bons termos com todos na Rediesel Wrench.",
  ui_story_5080_50800401_18_dialog_content = "Heheh, que bom que você notou, PlayerName.",
  ui_story_5080_50800401_19_dialog_content = "Todos mudam com o tempo.",
  ui_story_5080_50800401_20_dialog_content = "Graças a você, também comecei a pensar em construir conexões com os outros.",
  ui_story_5080_50800401_21_dialog_content = "... O-Oi, Vice? Está um pouco apertado aqui atrás—",
  ui_story_5080_50800401_22_dialog_content = "Se você quer que sua música alcance todos os cantos do mundo, então você deve tocá-la alto, alto, ALTO!",
  ui_story_5080_50800401_23_dialog_content = "Vá em frente, dê o seu melhor! A pessoa mais alta da sala é sempre a mais burra!",
  ui_story_5080_50800401_24_dialog_content = "Fracasso, frustração e medo fizeram você fugir de mim!",
  ui_story_5080_50800401_25_dialog_content = "E nada me deixa mais irritado do que um covarde!",
  ui_story_5080_50800401_26_dialog_content = "Zeta ainda não é bom em dirigir! Mas um verdadeiro amigo nunca ficaria chateado!",
  ui_story_5080_50800401_27_dialog_content = "Tem algo errado, Vice? Você parece indisposto...",
  ui_story_5080_50800401_28_dialog_content = "N-Não é nada... Capitã, você realmente não deveria tentar trocar suas bandagens em uma viagem de carro tão instável.",
  ui_story_5080_50800401_29_dialog_content = "Posso cuidar de suas feridas assim que chegarmos, então por favor não se esforce tanto.",
  ui_story_5080_50800401_30_dialog_content = "Tudo bem, estou acostumado a trabalhar sozinho.",
  ui_story_5080_50800401_31_dialog_content = "Isso não é nada... Além disso, não precisa ser tão educado. Eu não sou muito mais velho que você.",
  ui_story_5080_50800401_32_dialog_content = "Você é apenas um ano mais novo que eu, mas já conseguiu se tornar um capitão excepcional. Não há necessidade de ser tão respeitoso.",
  ui_story_5080_50800401_33_dialog_content = "Você é um batedor da Illumina, certo? Pela sua roupa, presumo que você também seja um soldado de elite.",
  ui_story_5080_50800401_34_dialog_content = "Posso dizer que você é diferente dos outros passarinhos. Você é um verdadeiro pássaro de rapina, não é?",
  ui_story_5080_50800401_35_dialog_content = "Que tipo de missão exigiria os serviços de alguém como você?",
  ui_story_5080_50800401_36_dialog_content = "Isso é altamente classificado e também não é da sua conta.",
  ui_story_5080_50800401_37_dialog_content = "Odeio dizer isso, mas o destino pode ser tão imprevisível às vezes.",
  ui_story_5080_50800401_38_dialog_content = "Bem, tenho certeza de que há uma boa razão para um caçador como você aparecer em um lugar como este.",
  ui_story_5080_50800401_39_dialog_content = "Olha, jovem Sinsa, aquelas <color=#FFB400>pegadas</color> novamente.",
  ui_story_5080_50800401_40_dialog_content = "Eles são exatamente como os que Kafka encontrou. Estes devem ser os <color=#FFB400>rastros</color> sobre os quais Jeriah estava falando antes.",
  ui_story_5080_50800401_41_dialog_content = "Eu disse para você não me chamar assim... De qualquer forma, essas trilhas são apenas globos de lava, não são?",
  ui_story_5080_50800401_42_dialog_content = "Por que haveria lava em um lugar como este?",
  ui_story_5080_50800401_43_dialog_content = "Talvez descobriremos mais se continuarmos?",
  ui_story_5080_50800401_44_dialog_content = "Ei, Roy! Estes são restos de Eclipsites, não são? Eles foram despedaçados, mas não há como negar, certo?",
  ui_story_5080_50800401_45_dialog_content = "Alguém os eliminou... Mas o que é ainda mais estranho é que seus corpos ainda não desapareceram.",
  ui_story_5080_50800401_46_dialog_content = "Dê uma boa olhada neles, Roy. Eles são os mesmos que <color=#FFB400>o Eclipsite</color> que você viu naquela época?",
  ui_story_5080_50800401_47_dialog_content = "Quinze anos atrás, quando estávamos tentando escapar... Quando <color=#FFB400>o chefe</color> tentou nos comprar mais tempo antes daquele <color=#FFB400>Eclipsite</color>...",
  ui_story_5080_50800401_48_dialog_content = "Você é o único que pode confirmar isso.",
  ui_story_5080_50800401_49_dialog_content = "Eles parecem semelhantes àquele <color=#FFB400>Eclipsite</color>, mas não são os mesmos. Se for o caso, eles parecem ser seus <color=#FFB400>descendentes</color>.",
  ui_story_5080_50800401_50_dialog_content = "Maldito monstro... Então ele tem se reproduzido todos esses anos, hein?",
  ui_story_5080_50800401_51_dialog_content = "Hora de ir à caça! Vamos rastrear <color=#FFB400>aquela coisa</color> até seu ninho e destruí-la de uma vez por todas!",
  ui_story_5080_50800401_52_dialog_content = "Estamos nas proximidades do vulcão, e a temperatura definitivamente está muito mais quente. Parece que o jovem Jeriah estava certo - o vulcão realmente está acordado novamente.",
  ui_story_5080_50800401_53_dialog_content = "Por que as faixas simplesmente desaparecem aqui?",
  ui_story_5080_50800401_54_dialog_content = "Essas pegadas pertencem a diferentes Eclipsitas... Talvez eles tenham bagunçado as coisas.",
  ui_story_5080_50800401_55_dialog_content = "O Vulcão Rugidor está localizado bem no subsolo. Pode haver ainda mais caminhos escondidos bem debaixo de nossos pés.",
  ui_story_5080_50800401_56_dialog_content = "E sem um alvo claro à vista, correr às cegas seria muito perigoso.",
  ui_story_5080_50800401_57_dialog_content = "Pare de se esconder, seu grande covarde! Venha aqui e me encare!",
  ui_story_5080_50800401_58_dialog_content = "Eu não sou o mesmo moleque atrevido de quinze anos atrás, agora mostre-se! É hora de acabar com isso!!!",
  ui_story_5080_50800401_59_dialog_content = "Droga!!!",
  ui_story_5080_50800401_60_dialog_content = "Pare com isso, Sinsa! Este lugar todo pode desabar a qualquer segundo—Ahhh—!",
  ui_story_5080_50800401_61_dialog_content = "<color=#e8d9bb>As paredes tremem enquanto os socos de Sinsa ecoam mais fundo na caverna. Logo, o barulho de inúmeros Eclipsitas pode ser ouvido.</color>",
  ui_story_5080_50800401_62_dialog_content = "A caverna está prestes a desabar, mas parece que nosso velho amigo finalmente está saindo para nos cumprimentar!",
  ui_story_5080_50800401_63_dialog_content = "Olhe para lá, Roy! São eles, não são?",
  ui_story_5080_50800401_64_dialog_content = "Demorou o suficiente para eles aparecerem! O ninho deles deve estar por perto!",
  ui_story_5080_50800401_65_dialog_content = "Tenha cuidado, jovem Sinsa... Vamos fazer isso rápido.",
  ui_story_5080_50800401_66_dialog_content = "Hmph, não vou parar até que minha chave esteja satisfeita. Vamos lá, Roy!",
  ui_story_5080_50800402_1_dialog_content = "Entrem e fiquem à vontade. Não tenho muito, já que quase nunca recebo pessoas em casa—",
  ui_story_5080_50800402_2_dialog_content = "Eis! Uma obra-prima do único e inigualável Zeta!",
  ui_story_5080_50800402_3_dialog_content = "Uau! É tão realista!",
  ui_story_5080_50800402_4_dialog_content = "Ha! Isso não é nada para um guerreiro lendário como eu!",
  ui_story_5080_50800402_5_dialog_content = "Invadindo e colocando um monte de desenhos de novo, eu vejo?",
  ui_story_5080_50800402_6_dialog_content = "Sua casa é muito antiquada, Encantadora! Pegue este maravilhoso desenho para animar seu espaço de vida com um sorriso maior, pois é uma cortesia do lendário Zeta!",
  ui_story_5080_50800402_7_dialog_content = "... Não importa. Apenas tente não quebrar nada.",
  ui_story_5080_50800402_8_dialog_content = "E pare de me chamar de Encantadora já. Se alguém merece esse título, é a Senhorita Naroxel.",
  ui_story_5080_50800402_9_dialog_content = "Nunca a conheci, mas o nome dela parece super legal! Ah, a propósito, aqui está o seu correio!",
  ui_story_5080_50800402_10_dialog_content = "Nós separamos aquela pilha bagunçada de envelopes e jogamos o lixo para você.",
  ui_story_5080_50800402_11_dialog_content = "Sério? Que gentileza da sua parte.",
  ui_story_5080_50800402_12_dialog_content = "Heehee, é justo que eu retribua adequadamente por todas as recompensas de missões que você me deu!",
  ui_story_5080_50800402_13_dialog_content = "Claro, agora você poderia por favor parar de sujar a correspondência com tinta? Quanto ao resto de vocês, não fiquem aí parados. Sente-se.",
  ui_story_5080_50800402_14_dialog_content = "Você realmente mudou muito, Jeriah... Você parece muito mais feliz agora que fez conexões com tantas outras pessoas.",
  ui_story_5080_50800402_15_dialog_content = "E eu não poderia estar mais feliz por você!",
  ui_story_5080_50800402_16_dialog_content = "É mesmo? Essas crianças podem ser um punhado às vezes, mas pelo menos meus dias não são mais tão chatos.",
  ui_story_5080_50800402_17_dialog_content = "Eagle Hunter Three é um drone biônico com capacidades de combate e reconhecimento, e é o produto da tecnologia mais avançada da Illumina... Vocês têm certeza que podem consertá-lo?",
  ui_story_5080_50800402_18_dialog_content = "Deixe apenas com o meu Mestre de Armas!",
  ui_story_5080_50800402_19_dialog_content = "Vamos começar com um pequeno teste de toque. Esquerda, direita, esquerda... Sim, parece que o transmissor foi danificado por impacto excessivo.",
  ui_story_5080_50800402_20_dialog_content = "Viu? Nada está fora do alcance das habilidades do nosso orgulhoso Mestre de Armas!",
  ui_story_5080_50800402_21_dialog_content = "Bem, então? Você consegue fazer isso?",
  ui_story_5080_50800402_22_dialog_content = "Eu definitivamente vou tentar o meu melhor!",
  ui_story_5080_50800402_23_dialog_content = "Empreste-me suas ferramentas. Eu também devo conseguir ajudar.",
  ui_story_5080_50800402_24_dialog_content = "Esses drones são meus parceiros em combate... Não estou disposto a entregá-los tão facilmente.",
  ui_story_5080_50800402_25_dialog_content = "Não se preocupe tanto, Eagle Huntershot o Herói da Neutralidade!",
  ui_story_5080_50800402_26_dialog_content = "...",
  ui_story_5080_50800402_27_dialog_content = "Não se importe com Zeta, é assim que ela é.",
  ui_story_5080_50800402_28_dialog_content = "Agora que sei que essas águias são seus companheiros queridos, eu não encostaria um dedo nelas.",
  ui_story_5080_50800402_29_dialog_content = "É minha culpa que este se machucou, então por favor me deixe cuidar dele para você!",
  ui_story_5080_50800402_30_dialog_content = "Mas você está fazendo Tiny One fazer todo o trabalho...",
  ui_story_5080_50800402_31_dialog_content = "N-Nos encontramos novamente, o Último Celestita! Vejo que o destino te favoreceu com mais um aliado poderoso!",
  ui_story_5080_50800402_32_dialog_content = "Você poderia falar normalmente comigo, sabe?",
  ui_story_5080_50800402_33_dialog_content = "Mas eu, o lendário guerreiro Zeta, ainda não perdi a esperança!",
  ui_story_5080_50800402_34_dialog_content = "Como um Herói da Neutralidade, se você pode se aliar ao Último Celestita, então isso significa que você também pode se juntar a mim na minha missão!",
  ui_story_5080_50800402_35_dialog_content = "Se isso significa ter um guerreiro poderoso como você na minha equipe, eu até vou ignorar o seu passado maligno!",
  ui_story_5080_50800402_36_dialog_content = "(Eu...)",
  ui_story_5080_50800402_37_dialog_content = "Não precisa dizer mais nada! Eu já sei exatamente o que está em sua mente!",
  ui_story_5080_50800402_38_dialog_content = "Tenho certeza que um guerreiro orgulhoso como você não é facilmente convencido.",
  ui_story_5080_50800402_39_dialog_content = "Mas tudo bem! Você e eu podemos lutar em pé de igualdade assim que meu Mestre de Armas consertar seu drone.",
  ui_story_5080_50800402_40_dialog_content = "E depois que eu te vencer de forma justa e honesta... Você se tornará uma adição inestimável ao meu grupo, e aquela bruxa nunca terá chance contra mim!",
  ui_story_5080_50800402_41_dialog_content = "Seu juramento soa mais como uma declaração de guerra para mim.",
  ui_story_5080_50800402_42_dialog_content = "Não se preocupe demais com ela, Capitão. Zeta apenas tem um... jeito diferente de falar.",
  ui_story_5080_50800402_43_dialog_content = "É-É isso mesmo, Capitão. Assim que o Eagle Hunter Three estiver consertado, vamos nos despedir.",
  ui_story_5080_50800402_44_dialog_content = "Tudo bem.",
  ui_story_5080_50800402_45_dialog_content = "Ouviu isso, Zeta? Agora, por que você não se desculpa... Hã?",
  ui_story_5080_50800402_46_dialog_content = "Apesar de sua afiliação com esses bandidos da Rediesel...",
  ui_story_5080_50800402_47_dialog_content = "Você não parece estar ciente do passado, então estou disposto a ignorar isso desta vez.",
  ui_story_5080_50800402_48_dialog_content = "Você ainda é jovem, então não deixe que eles te corrompam com seus métodos de bandidos do deserto.",
  ui_story_5080_50800402_49_dialog_content = "Heheh, você parece ter a ideia errada! Meu sonho é me tornar um herói lendário e também o salvador do deserto!",
  ui_story_5080_50800402_50_dialog_content = "Fico feliz em ouvir que você tem um objetivo tão nobre. Eu não te machuquei mais cedo, machuquei?",
  ui_story_5080_50800402_51_dialog_content = "Hã? D-De jeito nenhum! Um ataque desses nem sequer poderia me arranhar! E eu definitivamente não estava chorando de medo ou algo assim!",
  ui_story_5080_50800402_52_dialog_content = "Bom. Você realmente é um guerreiro corajoso.",
  ui_story_5080_50800402_53_dialog_content = "Estou vendo coisas...?",
  ui_story_5080_50800402_54_dialog_content = "Ela acabou de lidar perfeitamente com Zeta.",
  ui_story_5080_50800402_55_dialog_content = "... Eu não sabia que ela poderia ser assim.",
  ui_story_5080_50800402_56_dialog_content = "Talvez ela seja exatamente como você a descreveu antes, Carleen. Faz sentido que uma capitã experiente e madura cuide de seus subordinados.",
  ui_story_5080_50800402_57_dialog_content = "Mas...",
  ui_story_5080_50800402_58_dialog_content = "(Esta é a verdadeira ela? Se sim, então por que ela é tão fria conosco?)",
  ui_story_5080_50800402_59_dialog_content = "(Ela está reprimindo suas emoções pelo bem da missão? Ou... ela poderia estar escondendo um tipo de dor mais profunda?)",
  ui_story_5080_50800402_60_dialog_content = "Interessante. Eu já vi pássaros de todas as formas e tamanhos passarem pelo deserto em suas rotas migratórias, mas esta é a primeira vez que vejo um falcão que pode guardar suas garras.",
  ui_story_5080_50800402_61_dialog_content = "Uh, Zeta? As fendas deste drone estão cheias de areia, o que explica porque alguns dos circuitos foram danificados.",
  ui_story_5080_50800402_62_dialog_content = "Não estou acostumado a trabalhar com coisas tão afinadas como esta. Consertá-la não será fácil.",
  ui_story_5080_50800402_63_dialog_content = "O-O quê?",
  ui_story_5080_50800402_64_dialog_content = "Se você não consegue fazer, então me passe as ferramentas para que eu possa cuidar disso.",
  ui_story_5080_50800402_65_dialog_content = "N-Agora espere só um segundo!",
  ui_story_5080_50800402_66_dialog_content = "Dei minha palavra como um guerreiro orgulhoso de que assumiria total responsabilidade por isso! Como mais poderíamos ter nossa batalha épica?!",
  ui_story_5080_50800402_67_dialog_content = "Você não pode se esgotar antes de dar o primeiro passo. Você não vai desistir, vai?",
  ui_story_5080_50800402_68_dialog_content = "Sabe quem é ótimo nesse tipo de trabalho? Odi a Maníaca da Máquina! Você não quer perder para ela, quer?!",
  ui_story_5080_50800402_69_dialog_content = "Wha... O que você disse?!",
  ui_story_5080_50800402_70_dialog_content = "Afastem-se e observem, todos vocês! Este trabalho não é nada para alguém como eu!",
  ui_story_5080_50800402_71_dialog_content = "Vou consertar isso num instante! As habilidades de Odi nem se comparam às minhas!",
  ui_story_5080_50800402_72_dialog_content = "Acho que sei como Zeta continua envolvendo Tiny One em seus esquemas agora.",
  ui_story_5080_50800402_73_dialog_content = "Está ficando tarde e não parece que os reparos serão concluídos tão cedo. Vocês todos deveriam apenas ficar aqui esta noite.",
  ui_story_5080_50800402_74_dialog_content = "Não estaríamos nos intrometendo, estaríamos?",
  ui_story_5080_50800402_75_dialog_content = "Não se preocupe, já estou acostumado com \"intrusões\" como essa agora.",
  ui_story_5080_50800402_76_dialog_content = "Além disso... Acho que tenho muito a discutir com uma certa ave de rapina.",
  ui_story_5080_50800500_1_dialog_content = "<color=#e8d9bb>À medida que a noite cai sobre o deserto, a temperatura começa a despencar. De repente, uma duna de areia se agita na vastidão aparentemente vazia.</color>",
  ui_story_5080_50800500_2_dialog_content = "<color=#e8d9bb>Com um som de cuspindo, uma figura irrompe de debaixo das areias!</color>",
  ui_story_5080_50800500_3_dialog_content = "Ah—Pfft!",
  ui_story_5080_50800500_4_dialog_content = "Pfft, pfft, pfft!",
  ui_story_5080_50800500_5_dialog_content = "*Tosse* R-Roy...! Você... Você está bem?",
  ui_story_5080_50800500_6_dialog_content = "Urgh... Eu sou muito velho para esse tipo de coisa, jovem Sinsa. Da próxima vez que decidir derrubar uma montanha sobre nossas cabeças, pelo menos me avise!",
  ui_story_5080_50800500_7_dialog_content = "Heheh—Faz um tempo desde que nos soltamos assim, não é?",
  ui_story_5080_50800500_8_dialog_content = "Sim, mas brincadeiras à parte, ainda não sabemos a localização exata do ninho deles... E o número deles também não é motivo de riso.",
  ui_story_5080_50800500_9_dialog_content = "Tudo bem, agora vamos voltar para o acampamento. Se alguém perguntar, apenas diga que eliminamos o ninho dos Eclipsitas e deixamos por isso mesmo.",
  ui_story_5080_50800500_10_dialog_content = "Mas isso é realmente certo? Matamos muitos Eclipsitas, mas claramente não foram todos eles.",
  ui_story_5080_50800500_11_dialog_content = "Com todas as passagens subterrâneas que atravessam este lugar, é possível que esses monstros derretidos estejam aninhados dentro do vulcão.",
  ui_story_5080_50800500_12_dialog_content = "Então vamos atacar aquele vulcão!",
  ui_story_5080_50800500_13_dialog_content = "É realmente a melhor ideia que temos?",
  ui_story_5080_50800500_14_dialog_content = "Estou preocupado que o mesmo tipo de Eclipsita que matou nosso líder ainda esteja escondido em algum lugar do vulcão, um que seja mais forte do que qualquer coisa que já enfrentamos.",
  ui_story_5080_50800500_15_dialog_content = "Precisamos informar a todos imediatamente e garantir que eles estejam prontos para lutar quando chegar a hora.",
  ui_story_5080_50800500_16_dialog_content = "Se as coisas ficarem perigosas, é claro, eu vou avisá-los. Mas se nos depararmos com <color=#FFB400>aquilo</color>, não posso deixar que esses pequenos pestinhas se coloquem em perigo.",
  ui_story_5080_50800500_17_dialog_content = "O que mudou tanto agora? Você também era apenas um moleque atrevido naquela época, mas agora você é nosso líder.",
  ui_story_5080_50800500_18_dialog_content = "Eu entendo esse sentimento, mas de jeito nenhum vou contar para todos! Nosso problema com <color=#FFB400>aquele monstro</color>? Não, não tem nada a ver com os pirralhos em casa!",
  ui_story_5080_50800500_19_dialog_content = "Esta chave inglesa foi passada para mim, junto com esse rancor. Como líder, cabe a mim vingar nosso antigo chefe e nossos irmãos caídos. É por isso que...",
  ui_story_5080_50800500_20_dialog_content = "Prometa-me que você não dirá uma palavra, Roy.",
  ui_story_5080_50800500_21_dialog_content = "Então você está fazendo isso pelas crianças, huh? O chefe disse algo assim no passado também.",
  ui_story_5080_50800500_22_dialog_content = "Mesmo que tenhamos tido sorte o suficiente para escapar, meu coração tem estado cheio de arrependimento desde então.",
  ui_story_5080_50800500_23_dialog_content = "Se deixarmos as crianças lutarem contra <color=#FFB400>aquilo</color>, e elas acabarem sentindo a mesma impotência e desespero que sentimos naquela época, elas acabarão exatamente como...",
  ui_story_5080_50800500_24_dialog_content = "Não, eles não vão, jovem Sinsa. Depois de tudo que passamos, não me diga que você não viu o quanto eles cresceram?",
  ui_story_5080_50800500_25_dialog_content = "Sim, alguns deles são inexperientes ou não se lembram do que aconteceu naquela época, mas essas crianças já são membros orgulhosos e efetivos da Rediesel Wrench.",
  ui_story_5080_50800500_26_dialog_content = "Zeta tinha apenas dois anos quando perdeu os pais. Ela não era mais alta do que um pneu naquela época, mas agora ela é forte o suficiente para vagar pelo deserto sozinha.",
  ui_story_5080_50800500_27_dialog_content = "Você realmente vai privá-la da oportunidade de enfrentar o passado dela?",
  ui_story_5080_50800500_28_dialog_content = "Não foi isso que eu quis dizer. Você me conhece melhor do que isso.",
  ui_story_5080_50800500_29_dialog_content = "Eu sei, e também sei que você é muito arrogante para soltar as mãos deles.",
  ui_story_5080_50800500_30_dialog_content = "Você se lembra do que nossa antiga chefe costumava dizer? Ela acreditava que deveríamos respeitar cada decisão que uma criança toma, já que cada pessoa tem direito à liberdade.",
  ui_story_5080_50800500_31_dialog_content = "Agora que as crianças estão todas crescidas, nós, velhos como nós, precisamos aprender a deixar ir.",
  ui_story_5080_50800500_32_dialog_content = "Quando a tempestade chegar, teremos que enfrentá-la juntos, em vez de tentar protegê-los dela.",
  ui_story_5080_50800500_33_dialog_content = "A tempestade, hein...",
  ui_story_5080_50800500_34_dialog_content = "Sinsa! Roy!",
  ui_story_5080_50800500_35_dialog_content = "Eve? Estávamos falando de você agora mesmo. O que está fazendo aqui, hein?",
  ui_story_5080_50800500_36_dialog_content = "Eu estava tão preocupado com vocês dois, então viemos aqui para encontrá-los.",
  ui_story_5080_50800500_37_dialog_content = "Vamos lá, Sinsa! Vamos para casa!",
  ui_story_5080_50800500_38_dialog_content = "Roy... Quando a tempestade veio naquela época, eu não queria soltar a Eve... Porque eu tinha medo de perdê-la...",
  ui_story_5080_50800500_39_dialog_content = "Mas no final, foi ela quem nos salvou a ambos...",
  ui_story_5080_50800500_40_dialog_content = "Não importa o que aconteça, eu nunca vou abandonar minha família. Mas... Acho que você pode estar certo sobre essas crianças. Elas são muito mais fortes do que poderíamos imaginar.",
  ui_story_5080_50800500_41_dialog_content = "Sim, mas isso não significa que eu tenho que levá-los comigo. Eles podem ajudar defendendo nossa casa.",
  ui_story_5080_50800500_42_dialog_content = "De qualquer forma, podemos discutir os arranjos de trabalho depois que voltarmos... Ei, o que há com o lenço?",
  ui_story_5080_50800500_43_dialog_content = "Estou tão emocionado, jovem Sinsa... Você cresceu tanto nos últimos quinze anos.",
  ui_story_5080_50800500_44_dialog_content = "Pare com isso, seu idiota! Eu tenho sido o líder da Wrench por anos agora, então pare de me juntar com as outras crianças!",
  ui_story_5080_50800500_45_dialog_content = "Por que vocês demoraram tanto? Ah, não importa. É hora de comer, então não atrapalhem! Esperem por mim, Rabbie!",
  ui_story_5080_50800500_46_dialog_content = "O que aconteceu lá fora? Vocês dois parecem que estavam rolando em uma fornalha.",
  ui_story_5080_50800500_47_dialog_content = "Nada aconteceu, nós apenas fomos verificar o vulcão.",
  ui_story_5080_50800500_48_dialog_content = "Tch—Ouvi dizer que Azure está voltando em breve. Da próxima vez que vocês saírem por conta própria, lembrem-se de nos trazer de volta algumas bebidas.",
  ui_story_5080_50800500_49_dialog_content = "Vamos comer logo! Estou prestes a morrer de fome aqui!",
  ui_story_5080_50800500_50_dialog_content = "Hã? Onde estão Zeta e Tiny One?",
  ui_story_5080_50800500_51_dialog_content = "Não faço ideia, mas essa carne seca de lagarto é demais! Talvez eles tenham se metido em algum problema e tiveram que escapar por um túnel secreto?",
  ui_story_5080_50800500_52_dialog_content = "Estou um pouco preocupado, considerando o quão tarde é.",
  ui_story_5080_50800500_53_dialog_content = "Ei Barbara, você estava causando um alvoroço com eles mais cedo. Alguma ideia de para onde eles foram?",
  ui_story_5080_50800500_54_dialog_content = "Hmm... Foi muito agitado para lembrar de algo claramente, mas acho que eles saíram com Jeriah.",
  ui_story_5080_50800500_55_dialog_content = "Ela disse algo sobre recrutar um novo membro para o grupo dela. Será que ela está se referindo àquela mulher de antes?",
  ui_story_5080_50800500_56_dialog_content = "Ela foi com Jeriah, eh... Se eles querem procurar aquele Soldado Illumina, então eu digo que os deixe ser.",
  ui_story_5080_50800500_57_dialog_content = "Mas mal conhecemos algo sobre essa mulher. E com toda essa atividade vulcânica, é muito perigoso simplesmente deixá-los sozinhos lá fora...",
  ui_story_5080_50800500_58_dialog_content = "Vamos procurá-los. Estamos quase terminando de comer.",
  ui_story_5080_50800500_59_dialog_content = "Você vai precisar de um bom motorista. Eu também vou!",
  ui_story_5080_50800500_60_dialog_content = "Eu sugiro que nós...",
  ui_story_5080_50800500_61_dialog_content = "Tem certeza de que pode dirigir à noite sem capotar o carro?",
  ui_story_5080_50800500_62_dialog_content = "Conta comigo! Além disso, eu não preciso comer muito ultimamente.",
  ui_story_5080_50800500_63_dialog_content = "Ainda acho que devemos...",
  ui_story_5080_50800500_64_dialog_content = "Eu também vou! Meu canto apaixonado guiará nossos pequenos durante a noite!",
  ui_story_5080_50800500_65_dialog_content = "Isso é apenas porque será alto e irritante demais para ignorar.",
  ui_story_5080_50800500_66_dialog_content = "Quer dizer isso na minha cara?!",
  ui_story_5080_50800500_67_dialog_content = "Chega!",
  ui_story_5080_50800500_68_dialog_content = "Vou encontrá-los, então todos vocês apenas calem a boca e comam!",
  ui_story_5080_50800500_69_dialog_content = "Comam, todos! Huh? Tem algo errado com a comida?",
  ui_story_5080_50800500_70_dialog_content = "Perdoe-me se estou sendo rude, mas isso realmente conta como comida... Hã?!",
  ui_story_5080_50800500_71_dialog_content = "Uau! Este verme da areia frito está muito mais crocante do que antes!",
  ui_story_5080_50800500_72_dialog_content = "E esta cauda de cobra grelhada é tão macia e fresca!",
  ui_story_5080_50800500_73_dialog_content = "Por que você não está comendo, Carleen? Não se preocupe, Vice e eu sentimos o mesmo antes, mas essa comida é totalmente deliciosa!",
  ui_story_5080_50800500_74_dialog_content = "E-Eu agradeço sua preocupação... Mas você poderia segurar esse espeto um pouco mais longe de mim?",
  ui_story_5080_50800500_75_dialog_content = "Esse sabor...!!!",
  ui_story_5080_50800500_76_dialog_content = "É ainda melhor do que as melhores rações enlatadas do nosso exército!",
  ui_story_5080_50800500_77_dialog_content = "Parece que a Federação Illumina poderia tratar um pouco melhor seus soldados...",
  ui_story_5080_50800500_78_dialog_content = "Eu não pensei que você fosse gostar tanto da comida do Deserto Rediesel, Capitão.",
  ui_story_5080_50800500_79_dialog_content = "Para ser honesto, não tenho particular interesse em prazeres culinários.",
  ui_story_5080_50800500_80_dialog_content = "Ahh, isso foi bom! Hora de voltar ao trabalho, então não me incomode!",
  ui_story_5080_50800500_81_dialog_content = "Então você gosta de ratos de areia assados com mel assim como eu, hein?",
  ui_story_5080_50800500_82_dialog_content = "Heheh, até mesmo um sinistro soldado de Illumina não está além da graça salvadora de uma comida deliciosa!",
  ui_story_5080_50800500_83_dialog_content = "Se alguém é sinistro, é a Rediesel Wrench. Eu me recuso a aceitar... que temos algo em comum.",
  ui_story_5080_50800500_84_dialog_content = "(Huh? Por que ela está sendo tão má de repente?)",
  ui_story_5080_50800500_85_dialog_content = "Sério? Porque eu acho ótimo que temos algo em comum! Não tema, o lendário salvador do mundo também irá resgatá-lo de sua organização maligna!",
  ui_story_5080_50800500_86_dialog_content = "Sempre haverá um lugar para você no meu veículo!",
  ui_story_5080_50800500_87_dialog_content = "Parece bem legal, certo? Eu sempre quis dizer isso!",
  ui_story_5080_50800500_88_dialog_content = "O Rediesel Wrench... não é nada mais que uma gangue vergonhosa de desertores da Illumina.",
  ui_story_5080_50800500_89_dialog_content = "Não apenas esqueceram sua identidade e honra, mas também caíram no banditismo e voltaram suas armas contra os civis.",
  ui_story_5080_50800500_90_dialog_content = "Ninguém jamais poderia aprovar suas ações. Nem mesmo... uma criança como você.",
  ui_story_5080_50800500_91_dialog_content = "Eu não sou uma criança, e nós não somos nada como isso! Você deve estar nos confundindo com algum outro grupo!",
  ui_story_5080_50800500_92_dialog_content = "E permitir que crianças inocentes como você caiam nas mãos deles é culpa da Illumina, e é por isso que faremos tudo o que pudermos para corrigir as coisas.",
  ui_story_5080_50800500_93_dialog_content = "E com isso, você quer dizer entregá-los aos <color=#FFB400>Executores</color> da Illumina?",
  ui_story_5080_50800500_94_dialog_content = "O quê?! Eu nunca ouvi falar de algo assim antes...!",
  ui_story_5080_50800500_95_dialog_content = "Antes deste deserto ter um nome, quando a <color=#FFB400>Rediesel Wrench</color> ainda não existia, Illumina tinha sua parcela justa de desertores que vieram para este lugar.",
  ui_story_5080_50800500_96_dialog_content = "O desejo deles por liberdade os levou a abandonar Illumina e buscar refúgio nesta terra árida e desolada.",
  ui_story_5080_50800500_97_dialog_content = "Mas no final, os <color=#FFB400>Executores</color> de Illumina os perseguiram até o deserto e os abateram.",
  ui_story_5080_50800500_98_dialog_content = "Eita...",
  ui_story_5080_50800500_99_dialog_content = "Illumina é a razão pela qual os colonos originais deste deserto pegaram em armas e por que desconfiavam tanto um do outro.",
  ui_story_5080_50800500_100_dialog_content = "... Mas isso tudo era no passado. A Grande Marechal de hoje não apoia esses métodos, mas defende um novo sistema.",
  ui_story_5080_50800500_101_dialog_content = "Illumina não persegue mais seus desertores! Contanto que os bandidos de Rediesel baixem suas armas e retornem pacificamente, ninguém será—",
  ui_story_5080_50800500_102_dialog_content = "Durante a Crise Darkover, Sinsa e os outros até foram à cidade de Gannon para fornecer reforços... Uma pena que nunca foram devidamente recompensados por sua bondade.",
  ui_story_5080_50800500_103_dialog_content = "Deve ter havido algum tipo de mal-entendido. Tenho certeza de que ambos os lados poderiam chegar a um acordo se apenas discutissem as coisas de maneira razoável.",
  ui_story_5080_50800500_104_dialog_content = "Se possível... Eu preferiria não machucar nenhum de vocês. Mas como pessoas de fora, é impossível para vocês entenderem o significado de deserção.",
  ui_story_5080_50800500_105_dialog_content = "A decisão egoísta de uma pessoa pode prejudicar inúmeras outras pessoas... Pode arruinar tudo, assim como suas famílias.",
  ui_story_5080_50800500_106_dialog_content = "(Ela parece estranhamente agitada agora... O que ela poderia estar lembrando?)",
  ui_story_5080_50800500_107_dialog_content = "É mesmo? Por que as asas de um pássaro deveriam ser amarradas apenas porque ele nasceu em Illumina?",
  ui_story_5080_50800500_108_dialog_content = "Nasci na Rediesel Wrench, embora nunca tenha realmente me encaixado com eles. Mesmo assim, eu podia dizer que eles eram apenas um bando de tolos amantes da liberdade.",
  ui_story_5080_50800500_109_dialog_content = "Fui autorizado a sair e construir uma vida para mim mesmo quando quisesse. Todos eles também têm suas escolhas a fazer.",
  ui_story_5080_50800500_110_dialog_content = "Pedir para eles retornarem à Illumina e serem controlados pelo sistema, privados de sua individualidade. Não consigo imaginar que eles concordariam com isso.",
  ui_story_5080_50800500_111_dialog_content = "Não é justo dizer isso, eu não me sinto assim sobre a Illumina de jeito nenhum!",
  ui_story_5080_50800500_112_dialog_content = "Então não podemos fazer o que quisermos em Illumina? E sobre corrida de arrancada? Ainda é permitido?",
  ui_story_5080_50800500_113_dialog_content = "Bem, as Cidades Baixas têm muitas máquinas valiosas e delicadas, então... não.",
  ui_story_5080_50800500_114_dialog_content = "Isso parece horrível! Eu nunca iria querer ir lá!",
  ui_story_5080_50800500_115_dialog_content = "E-Eu juro que não é tão ruim! Temos todos os tipos de outras competições também! E você sempre pode se candidatar para o serviço de transporte!",
  ui_story_5080_50800500_116_dialog_content = "A missão da Illumina é proteger todos os Aurorianos. Sacrifícios individuais são necessários pelo bem do todo.",
  ui_story_5080_50800500_117_dialog_content = "Oh, meu pequeno pássaro de rapina. Illumina deve ter poupado nenhum esforço para treinar um soldado tão firme.",
  ui_story_5080_50800500_118_dialog_content = "Não há necessidade de obscurecer as coisas. Venho de uma longa linhagem de heróis orgulhosos, e a fé da minha família em Illumina é mais forte do que você jamais poderia imaginar.",
  ui_story_5080_50800500_119_dialog_content = "Nenhum sacrifício é grande demais para o esplendor da Illumina! Nossas vidas são efêmeras, mas a glória é eterna!",
  ui_story_5080_50800500_120_dialog_content = "E quando todos tiverem sido sacrificados, quem restará para lembrar dos heróis?",
  ui_story_5080_50800500_121_dialog_content = "Você diz que vem de uma longa linhagem de heróis, mas você se lembra do que o avô do seu avô realizou? Ou do que ele gostava na vida?",
  ui_story_5080_50800500_122_dialog_content = "Tenho certeza de que desde cedo te contaram sobre a grandeza dos seus ancestrais... Mas o que você realmente sabe sobre a existência deles?",
  ui_story_5080_50800500_123_dialog_content = "(Eu...)",
  ui_story_5080_50800500_124_dialog_content = "... Embora seus atos de bravura possam ser esquecidos com o tempo, os frutos das conquistas de um herói sempre permanecerão.",
  ui_story_5080_50800500_125_dialog_content = "Em um mundo dominado pelos Eclipsitas, devemos continuar a viver, crescer e passar a nossa vontade... Assim como inúmeros heróis caídos fizeram antes de nós. ",
  ui_story_5080_50800500_126_dialog_content = "Embora eu possa não conhecer todos eles pelo nome, seus sacrifícios e conquistas vivem através de nós, os herdeiros de Astra.",
  ui_story_5080_50800500_127_dialog_content = "Esses heróis me influenciaram, dando-me a determinação para atravessar milhares de caminhos para chegar aqui... Não tenho arrependimentos!",
  ui_story_5080_50800500_128_dialog_content = "As histórias e existências deles nunca desaparecerão verdadeiramente! Eles continuarão a alcançar os corações e vidas de outras pessoas de mais maneiras do que podemos imaginar!",
  ui_story_5080_50800500_129_dialog_content = "Carleen...",
  ui_story_5080_50800500_130_dialog_content = "A princesa de Lumopolis realmente sabe como fazer um excelente discurso.",
  ui_story_5080_50800500_131_dialog_content = "Lanceiro Branco... Você tem toda razão.",
  ui_story_5080_50800500_132_dialog_content = "Ei, chefe, você não vai entrar? Você esteve nos espionando esse tempo todo!",
  ui_story_5080_50800500_133_dialog_content = "Shhh! Quieto, Tiny One. Ainda estou tentando ouvir...",
  ui_story_5080_50800500_134_dialog_content = "O Lanceiro Branco faz um excelente ponto! Eu... uma vez pertenci a um esquadrão de soldados leais que deram suas vidas em nome da justiça. Eles me agraciaram com sua bondade, e sempre me orgulharei disso.",
  ui_story_5080_50800500_135_dialog_content = "O exemplo deles é um que merece ser seguido.",
  ui_story_5080_50800500_136_dialog_content = "Isso mesmo... Porque se eu não, eu...",
  ui_story_5080_50800500_137_dialog_content = "Huh? Para onde você está indo, Capitão—",
  ui_story_5080_50800500_138_dialog_content = "Apenas dê a ela algum espaço.",
  ui_story_5080_50800500_139_dialog_content = "Hmph... Zeta, Tiny One, vamos para casa.",
  ui_story_5080_50800500_140_dialog_content = "O-O líder dos bandidos Rediesel?! Quando você...",
  ui_story_5080_50800500_141_dialog_content = "Está feito! Eu consertei! Ohhh, espere até Odi descobrir que consertei algo em que ela nunca trabalhou antes!!!",
  ui_story_5080_50800500_142_dialog_content = "Mas <color=#FFB400>Guerreiro Amaldiçoado</color>... Eu realmente gostaria de ficar...",
  ui_story_5080_50800500_143_dialog_content = "... Então vá em frente. Você já é adulto afinal. Fique de olho nesses pirralhos, pode, Jeriah?",
  ui_story_5080_50800500_144_dialog_content = "Espere! Você... Você sabe sobre aquele Eclipsite, não sabe?",
  ui_story_5080_50800500_145_dialog_content = "Depois de todos esses anos vagando pelo deserto, a Rediesel Wrench deve saber mais sobre sua existência. Você poderia me dizer onde encontrar o ninho deles?",
  ui_story_5080_50800500_146_dialog_content = "Você não é o primeiro soldado Illumina a vir procurá-lo, nem de longe... Mas infelizmente, nenhum desses caras jamais voltou.",
  ui_story_5080_50800500_147_dialog_content = "Você não é nada especial comparado a eles, então desista já. Não há razão para se matar por causa de sua missão.",
  ui_story_5080_50800500_148_dialog_content = "Me irrita saber que, depois de todos esses anos, eles ainda estão enviando pessoas para a morte.",
  ui_story_5080_50800500_149_dialog_content = "Você não entende! Essas são nossas ordens como soldados, e os inimagináveis tesouros escondidos nos Territórios Secretos valem cada nobre sacrifício!",
  ui_story_5080_50800500_150_dialog_content = "Você continua repetindo essa palavra várias e várias vezes, mas você realmente sabe o que \"sacrifício\" significa?",
  ui_story_5080_50800500_151_dialog_content = "Vá em frente, me diga o que você acha que isso significa!",
  ui_story_5080_50800500_152_dialog_content = "É a disposição de sacrificar a própria vida pelo esplendor de Illumina e pelo bem maior!",
  ui_story_5080_50800500_153_dialog_content = "Assim como... a determinação para cumprir a missão a qualquer custo!",
  ui_story_5080_50800500_154_dialog_content = "Hahahaha—",
  ui_story_5080_50800500_155_dialog_content = "Por que você está rindo? Você acha que isso é uma piada?!",
  ui_story_5080_50800500_156_dialog_content = "Sim, eu entendo. Você realmente não é diferente das pessoas que vieram antes de você, então apenas volte para casa. Este deserto já reivindicou vidas demais.",
  ui_story_5080_50800500_157_dialog_content = "Vamos, Tiny One.",
  ui_story_5080_50800500_158_dialog_content = "Você não sabe de nada... Não somos iguais... Você não faz ideia de que tipo de determinação me trouxe até aqui...",
  ui_story_5080_50800500_159_dialog_content = "Não vou mais desonrar minha família... Eu tenho que... lavar nossa vergonha...",
  ui_story_5080_50800601_1_dialog_content = "Você não vai dormir um pouco, Vice?",
  ui_story_5080_50800601_2_dialog_content = "Bocejo—Ainda preciso terminar o relatório da missão de hoje... Mas não se preocupe comigo! Vá em frente e descanse um pouco.",
  ui_story_5080_50800601_3_dialog_content = "Você me parece bastante cansado.",
  ui_story_5080_50800601_4_dialog_content = "É uma grande oportunidade trabalhar com o Capitão... Esta é uma experiência tão rara...",
  ui_story_5080_50800601_5_dialog_content = "Eu tenho que... anotar tudo...",
  ui_story_5080_50800601_6_dialog_content = "Aqui, deixe-me ajudá-lo com isso.",
  ui_story_5080_50800601_7_dialog_content = "Nng... Isso não... vai funcionar...",
  ui_story_5080_50800601_8_dialog_content = "Tudo bem. Só falta um pouquinho para escrever. Eu termino para você.",
  ui_story_5080_50800601_9_dialog_content = "Depois de passar tanto tempo com Vice, até mesmo PlayerName se acostumou a fazer isso por ela.",
  ui_story_5080_50800601_10_dialog_content = "Não tenho certeza de quando aconteceu, mas provavelmente foi por todas as palestras que ela me dá... Não se preocupe, isso não vai demorar. Vá dormir um pouco, Carleen.",
  ui_story_5080_50800601_11_dialog_content = "Parece que você ainda tem algo em mente... Mas se você insiste. Boa noite.",
  ui_story_5080_50800601_12_dialog_content = "(Só preciso adicionar a última parte e o relatório dela estará pronto.)",
  ui_story_5080_50800601_13_dialog_content = "Mas espere, tem mais... E essa é a melhor parte também!",
  ui_story_5080_50800601_14_dialog_content = "(É a voz de Zeta? Eu posso ouvi-la daqui... Como ela ainda tem tanta energia?)",
  ui_story_5080_50800601_15_dialog_content = "E assim, a garota bruxa e eu pulamos para dentro do nosso carro de corrida!",
  ui_story_5080_50800601_16_dialog_content = "(Com quem ela está falando? Terminei de escrever agora... Acho que não custa dar uma olhada.)",
  ui_story_5080_50800601_17_dialog_content = "Uau! Meu carro avançou rapidamente e nós quase fomos atingidos pelas garras do dragão! Bang! Estrondo!",
  ui_story_5080_50800601_18_dialog_content = "Eu bati meu carro no dragão e o mandei voar! Até a bruxa não teve escolha senão reconhecer minha força!",
  ui_story_5080_50800601_19_dialog_content = "(Parece que ela pode estar exagerando um pouco... Huh? É isso... Rachel? Zeta está incomodando ela enquanto ela está de guarda?)",
  ui_story_5080_50800601_20_dialog_content = "Ah, e aposto que você não sabia disso! Quando eu acelero meu motor, toneladas de lagartos começam a sair da areia!",
  ui_story_5080_50800601_21_dialog_content = "Esses lagartos têm o melhor sabor! Eles são ainda mais macios do que os que comemos hoje!",
  ui_story_5080_50800601_22_dialog_content = "Todos nós somos bastante bons em cozinhar por aqui, então aposto que você também gostaria!",
  ui_story_5080_50800601_23_dialog_content = "... Gostaria de experimentar um dos meus biscoitos militares comprimidos?",
  ui_story_5080_50800601_24_dialog_content = "Não, obrigado, esses parecem horríveis.",
  ui_story_5080_50800601_25_dialog_content = "Isso me lembra! Já te contei que eu organizo comícios sozinho?",
  ui_story_5080_50800601_26_dialog_content = "Ao contrário daquela garota bruxa malvada, eu não dependo do Último Celestita para cruzar a linha de chegada!",
  ui_story_5080_50800601_27_dialog_content = "A glória de atravessar o impiedoso deserto em chamas pertence apenas a mim!",
  ui_story_5080_50800601_28_dialog_content = "Isso é impressionante. Eu nunca teria sabido disso apenas olhando para você.",
  ui_story_5080_50800601_29_dialog_content = "Heheh, bem legal, certo? A guerreira lendária Zeta e suas gloriosas conquistas são suficientes para convencer qualquer malfeitor a abandonar seus caminhos perversos! É por isso que você deve ficar comigo!",
  ui_story_5080_50800601_30_dialog_content = "Sua habilidade de sobreviver sozinho no deserto por tanto tempo te tornaria um excelente navegador nos meus ralis!",
  ui_story_5080_50800601_31_dialog_content = "Entre no meu carro e podemos compartilhar a glória de vencer nossa próxima corrida!",
  ui_story_5080_50800601_32_dialog_content = "Glória, hein... Eu sou realmente bom apenas com máquinas. Será que sou uma boa escolha para a sua equipe?",
  ui_story_5080_50800601_33_dialog_content = "Claro! Apenas deixe o treinamento comigo, e eu vou transformá-lo em um membro lendário da minha equipe!",
  ui_story_5080_50800601_34_dialog_content = "Você pode ficar encarregado de... Como é que se chama aquilo de novo? É como um mapa, mas com muitas outras informações... O livro de bordo! Eu vou te ensinar como fazer um livro de bordo adequado para nossos ralis!",
  ui_story_5080_50800601_35_dialog_content = "Claro. Isso parece bastante interessante para mim.",
  ui_story_5080_50800601_36_dialog_content = "(Isso é real? Aqueles dois estão realmente tendo uma conversa...)",
  ui_story_5080_50800601_37_dialog_content = "Há muitas outras coisas interessantes aqui no deserto também! A partir de amanhã, vou ensinar tudo sobre elas para você!",
  ui_story_5080_50800601_38_dialog_content = "E depois de treiná-lo... Finalmente poderei derrotar aquela bruxa...",
  ui_story_5080_50800601_39_dialog_content = "Mas agora, é hora de eu ir para a cama... Boa noite...",
  ui_story_5080_50800601_40_dialog_content = "<color=#828282>Tum!</color>",
  ui_story_5080_50800601_41_dialog_content = "Sinceramente... Isso não dói?",
  ui_story_5080_50800601_42_dialog_content = "Descanse bastante então... Boa noite.",
  ui_story_5080_50800601_43_dialog_content = "(Em um minuto ela é fria e distante, e no próximo ela é calorosa e gentil... Qual é a verdadeira você, Rachel?)",
  ui_story_5080_50800601_44_dialog_content = "(Talvez agora seja um bom momento para falar com ela... Huh? Aquelas emoções poderosas... Elas estão de volta...)",
  ui_story_5080_50800601_45_option_content = "Sentido Rachel",
  ui_story_5080_50800601_46_dialog_content = "O alvo foi adquirido e nossa missão agora está completa. Conseguimos, Capitão!",
  ui_story_5080_50800601_47_dialog_content = "Bem feito... Mas não baixe a guarda ainda, não enquanto as ruínas ainda estão cheias de Eclipsitas. Precisamos sair daqui.",
  ui_story_5080_50800601_48_dialog_content = "Coruja Verde, Gavião Vermelho, peguem o núcleo de dados e recuem pela nossa rota de infiltração.",
  ui_story_5080_50800601_49_dialog_content = "Essa coisa é bem pesada, Capitão. Deixe-me carregá-la em vez disso.",
  ui_story_5080_50800601_50_dialog_content = "Tudo bem, apenas fique atento. Precisamos nos reagrupar com os outros no ponto de exfiltração.",
  ui_story_5080_50800601_51_dialog_content = "Capitão, parece haver uma perturbação nas fileiras dos Eclipsitas.",
  ui_story_5080_50800601_52_dialog_content = "Eles estão se movendo em uma direção diferente... Por que estão se agrupando assim?",
  ui_story_5080_50800601_53_dialog_content = "Não... Eles estão começando a vir em nossa direção!",
  ui_story_5080_50800601_54_dialog_content = "Corre!",
  ui_story_5080_50800601_55_dialog_content = "Coruja Verde, Gavião Vermelho, respondam! Qual é a situação no ponto de extração?",
  ui_story_5080_50800601_56_dialog_content = "Os Eclipsitas parecem estar convergindo para um único ponto... Isso é ruim, Capitão! Eles estão se aproximando da sua posição!",
  ui_story_5080_50800601_57_dialog_content = "Apenas mantenha a calma e siga o plano. Chegaremos lá em breve, então certifique-se de que nossa rota de fuga permaneça aberta!",
  ui_story_5080_50800601_58_dialog_content = "Não se preocupe com esses Eclipsitas, Ganso Branco! Vamos embora!",
  ui_story_5080_50800601_59_dialog_content = "Acompanhe o Capitão para fora daqui, Asa Cinza! Eu vou desviar a atenção deles de você!",
  ui_story_5080_50800601_60_dialog_content = "Do que você está falando? Vamos sair daqui juntos! Capitão, você tem que se livrar do núcleo de dados, ou não conseguiremos fugir desses Eclipsitas!",
  ui_story_5080_50800601_61_dialog_content = "Como essas coisas estão cientes da nossa posição? É como se estivessem tentando proteger o núcleo...",
  ui_story_5080_50800601_62_dialog_content = "Mantenha o ritmo, White Goose! Chega de fugir por conta própria!",
  ui_story_5080_50800601_63_dialog_content = "Mas Capitão... Neste ritmo, nunca vamos conseguir...",
  ui_story_5080_50800601_64_dialog_content = "<color=#e8d9bb>Bang, bang, bang—</color>",
  ui_story_5080_50800601_65_dialog_content = "Por aqui, Capitão!",
  ui_story_5080_50800601_66_dialog_content = "É a Coruja Verde e o Quiriquiri Vermelho!",
  ui_story_5080_50800601_67_dialog_content = "Idiotas! Eu dei ordens claras para vocês guardarem a saída, então o que estão fazendo aqui?!",
  ui_story_5080_50800601_68_dialog_content = "Você não teria conseguido se não tivéssemos desobedecido suas ordens, Capitão.",
  ui_story_5080_50800601_69_dialog_content = "Se você vai nos disciplinar, pelo menos espere até chegarmos em segurança!",
  ui_story_5080_50800601_70_dialog_content = "Idiotas...",
  ui_story_5080_50800601_71_dialog_content = "Estava me perguntando o que estava demorando tanto! Você esteve carregando essa coisa pesada todo esse tempo, Capitão?",
  ui_story_5080_50800601_72_dialog_content = "Então este é o núcleo, huh? Essa coisa não é exatamente portátil, Capitão. Nós deveríamos...",
  ui_story_5080_50800601_73_dialog_content = "Não! A missão vem em primeiro lugar! Os dados neste núcleo têm o poder de mudar toda a Illumina... O Esquadrão Eagleeye não pode se dar ao luxo de falhar, mesmo que coloque nossas vidas em risco!",
  ui_story_5080_50800601_74_dialog_content = "Se falharmos, todos nós seremos desertores... Eu não... Vou deixar você colocar suas famílias nesse tipo de vergonha.",
  ui_story_5080_50800601_75_dialog_content = "A saída está logo à frente e eu vou ficar na retaguarda. Agora vá! Certifique-se de que o núcleo de dados volte para Illumina!",
  ui_story_5080_50800601_76_dialog_content = "Não posso fazer, Capitã!",
  ui_story_5080_50800601_77_dialog_content = "Você está desobedecendo ordens novamente, Asa Cinza?!",
  ui_story_5080_50800601_78_dialog_content = "De acordo com o Capítulo 6, Subseção 31 do Decreto de Conclusão de Missão da Illumina, um vice-capitão de esquadrão pode substituir as ordens do capitão, desde que o resto do esquadrão esteja de acordo!",
  ui_story_5080_50800601_79_dialog_content = "Nunca houve um batedor melhor do que você, Capitão. Mesmo que consigamos passar pela saída, não há garantia de que retornaremos em segurança à superfície.",
  ui_story_5080_50800601_80_dialog_content = "Como vice-capitão, eu inicio uma votação! Todos a favor de apoiar o Capitão e cobrir sua fuga, digam \"sim\"!",
  ui_story_5080_50800601_81_dialog_content = "Sim!",
  ui_story_5080_50800601_82_dialog_content = "Sim.",
  ui_story_5080_50800601_83_dialog_content = "Irmã, você...",
  ui_story_5080_50800601_84_dialog_content = "\"A missão vem antes de tudo\", lembra? Desculpe, Capitão... Mas sua missão agora é diferente.",
  ui_story_5080_50800601_85_dialog_content = "Pegue o núcleo e retorne para Illumina. Sua família ainda está esperando por você, não está?",
  ui_story_5080_50800601_86_dialog_content = "Não se preocupe, estaremos logo atrás de você.",
  ui_story_5080_50800601_87_dialog_content = "Agora vá em frente, Capitão!",
  ui_story_5080_50800601_88_dialog_content = "Eu...",
  ui_story_5080_50800601_89_dialog_content = "Apenas espere, Caçadores da Águia! Vou chamar reforços assim que chegar à superfície!",
  ui_story_5080_50800601_90_dialog_content = "Os Eclipsitas estão chegando. Alguém já está com medo?",
  ui_story_5080_50800601_91_dialog_content = "O Capitão saiu em segurança. Do que temos que ter medo agora?",
  ui_story_5080_50800601_92_dialog_content = "Exploda a saída. Não podemos deixar nenhum desses monstros passar por nós.",
  ui_story_5080_50800601_93_dialog_content = "O quê?! Não, Asa Cinza! Não faça isso—!",
  ui_story_5080_50800601_94_dialog_content = "Você sempre carrega tanto peso nos ombros, Capitão... Eu sinto muito... Por fazer você carregar um pouco mais.",
  ui_story_5080_50800601_95_dialog_content = "Acenda!!!",
  ui_story_5080_50800602_1_dialog_content = "(Isso foi Rachel... É por isso que ela sempre insiste em trabalhar sozinha? Então, quando fomos designados para ajudá-la...)",
  ui_story_5080_50800602_2_dialog_content = "(O motivo dela continuar escondendo suas emoções e nos tratando de forma tão fria... Será que é porque ela tem medo de nos perder?)",
  ui_story_5080_50800602_3_dialog_content = "(Após ver o passado doloroso dela, devo realmente continuar tentando falar com ela sobre isso?)",
  ui_story_5080_50800602_4_dialog_content = "Asa Cinza, Ganso Branco, Coruja Verde, Peneireiro Vermelho... Vocês... Ainda estão cuidando de mim?",
  ui_story_5080_50800602_5_dialog_content = "<color=#828282>Tum!</color>",
  ui_story_5080_50800602_6_dialog_content = "Quem está aí? Como ousa espionar—",
  ui_story_5080_50800602_7_dialog_content = "Miau!",
  ui_story_5080_50800602_8_dialog_content = "Gato?",
  ui_story_5080_50800602_9_dialog_content = "... Venha aqui, gatinho pequeno.",
  ui_story_5080_50800602_10_dialog_content = "Você gostaria de um pouco de peixe seco?",
  ui_story_5080_50800602_11_dialog_content = "Bom gatinho... Você é o pet do Mensageiro?",
  ui_story_5080_50800602_12_dialog_content = "Seu pelo é tão macio e suave. Que gatinho lindo e pequeno.",
  ui_story_5080_50800602_13_dialog_content = "O tilintar dessas placas de identificação chamou sua atenção? Você também quer falar com eles, não quer?",
  ui_story_5080_50800602_14_dialog_content = "Esse gato foi acolhido pela Roy há algum tempo e criado na base da Rediesel Wrench. Ele pode ser bastante mimado às vezes.",
  ui_story_5080_50800602_15_dialog_content = "Gah!",
  ui_story_5080_50800602_16_dialog_content = "Miau—!",
  ui_story_5080_50800602_17_dialog_content = "Q-Quando foi que você... Você não viu nada, viu?!",
  ui_story_5080_50800602_18_dialog_content = "Não se preocupe, conheci todos os tipos de pessoas durante minhas viagens. Não me sinto de uma maneira ou de outra sobre suas preferências.",
  ui_story_5080_50800602_19_dialog_content = "Além disso, eu sei há muito tempo que você não é tão insensível quanto parece.",
  ui_story_5080_50800602_20_dialog_content = "Mas se você não se importa que eu diga, acho que sua aparência fria só está prejudicando ainda mais seus aliados.",
  ui_story_5080_50800602_21_dialog_content = "... O que te faz tão diferente? Você afastou a Rediesel Wrench, não foi?",
  ui_story_5080_50800602_22_dialog_content = "Afastei-os? De maneira nenhuma. Eu simplesmente me movi um pouco mais longe de todo o barulho e tumulto.",
  ui_story_5080_50800602_23_dialog_content = "Como eu suspeitava, você é exatamente como <color=#FFB400>aquela pessoa</color>. Não é de se admirar que você me deu uma sensação tão familiar.",
  ui_story_5080_50800602_24_dialog_content = "\"Essa pessoa\"?",
  ui_story_5080_50800602_25_dialog_content = "Há muitos ex-soldados da Illumina na Rediesel Wrench, mas um deles é especialmente diferente.",
  ui_story_5080_50800602_26_dialog_content = "Assim como você, ela era uma soldada dedicada e de elite em uma missão especial, que liderou sua equipe para o deserto em uma idade muito jovem.",
  ui_story_5080_50800602_27_dialog_content = "Ela... Sobreviveu à sua exploração dos Territórios Secretos aqui fora?",
  ui_story_5080_50800602_28_dialog_content = "Você se lembra do nome dela, ou do nome do esquadrão dela? É possível que eu a conheça.",
  ui_story_5080_50800602_29_dialog_content = "O nome dela...? Quando a conheci pela primeira vez, ela já havia abandonado seu passado. Não tenho certeza se o nome que ela está usando é realmente o nome dela.",
  ui_story_5080_50800602_30_dialog_content = "Mas eu me lembro do nome do esquadrão dela: o Esquadrão Freebird. É o mesmo nome que me fez ter tanta inveja dos pássaros e sua capacidade de voar livremente pelo céu.",
  ui_story_5080_50800602_31_dialog_content = "\"Esquadrão Freebird\"?!",
  ui_story_5080_50800602_32_dialog_content = "(Não é esse o nome do esquadrão que o Rachel está procurando agora?)",
  ui_story_5080_50800602_33_dialog_content = "Aquela pessoa... Fugiu para o deserto também? Então, ela não apenas se tornou uma traidora, mas também se juntou à Rediesel Wrench—",
  ui_story_5080_50800602_34_dialog_content = "Você está errado, Jeriah: Eu não sou nada como aquela pessoa. Ela pode ser uma desertora sem vergonha, mas eu não sou!",
  ui_story_5080_50800602_35_dialog_content = "Desculpe, meu pequeno pássaro de rapina, mas receio que você é quem está enganado.",
  ui_story_5080_50800602_36_dialog_content = "Aquela mulher não era nem sem vergonha nem desertora. Até o fim, ela foi uma das pessoas mais orgulhosas que já conheci.",
  ui_story_5080_50800602_37_dialog_content = "Sua paixão ardente era tão vermelha quanto a chave inglesa que ela empunhava em suas mãos. Mesmo após passá-la para Sinsa, ela não perdeu nada de sua cor.",
  ui_story_5080_50800602_38_dialog_content = "Se é nisso que você acredita... Então eu tenho uma história para compartilhar com você.",
  ui_story_5080_50800602_39_dialog_content = "Foi-me contado pela primeira vez por <color=#FFB400>minha tia</color>, que já foi membro do Esquadrão Freebird—",
  ui_story_5080_50800602_40_dialog_content = "Trinta anos atrás, a Illumina montou uma equipe de forças especiais conhecida como Esquadrão Freebird.",
  ui_story_5080_50800602_41_dialog_content = "Os membros de elite, cuidadosamente selecionados desta equipe, foram encarregados de realizar missões que eram impossíveis para qualquer outro esquadrão.",
  ui_story_5080_50800602_42_dialog_content = "Apesar dos desafios incomparáveis que enfrentavam a cada operação, o Esquadrão Freebird manteve uma taxa de sucesso de missão perfeita. Entrar para o seu esquadrão era a maior aspiração de todo soldado.",
  ui_story_5080_50800602_43_dialog_content = "Se esse esquadrão ainda existisse, tenho certeza de que você seria o candidato perfeito para ele.",
  ui_story_5080_50800602_44_dialog_content = "Mas então eles foram designados para uma missão altamente confidencial, que acabou sendo a última deles. Minha tia e seus camaradas arriscaram suas vidas por isso...",
  ui_story_5080_50800602_45_dialog_content = "O preço que eles pagaram foi inimaginável, mas no final... Sua capitã os traiu. Ela abandonou a missão sem autorização e levou o resto dos sobreviventes de volta para Illumina como uma <color=#FFB400>desertora</color>.",
  ui_story_5080_50800602_46_dialog_content = "Não muito tempo depois, ela desertou completamente da Illumina, o que lançou minha tia nas profundezas do desespero!",
  ui_story_5080_50800602_47_dialog_content = "Eles a marcaram como traidora e a acusaram de ser separatista. Despojada de sua honra e rebaixada inúmeras vezes, ela foi desprezada por todos ao seu redor!",
  ui_story_5080_50800602_48_dialog_content = "Ela se recusou a voltar para casa por medo de sobrecarregar nossa família, e seu relacionamento com meu pai se desfez—",
  ui_story_5080_50800602_49_dialog_content = "Mas, apesar de todos os sacrifícios da minha tia, a honra da nossa família ainda estava...",
  ui_story_5080_50800602_50_dialog_content = "(Rachel...)",
  ui_story_5080_50800602_51_option_content = "Sinta as Memórias de Rachel",
  ui_story_5080_50800602_52_dialog_content = "Ei, olha só! A filha daquela traidora está aqui de novo!",
  ui_story_5080_50800602_53_dialog_content = "Não me diga que ela está tentando entrar no Museu. Esse lugar é onde honramos nossos verdadeiros heróis! Traidores não são permitidos lá!",
  ui_story_5080_50800602_54_dialog_content = "Dado o histórico de traição de sua família, é difícil imaginar que ela tenha sido criada de maneira diferente.",
  ui_story_5080_50800602_55_dialog_content = "Podemos realmente confiar em alguém como ela para cuidar das nossas costas, capitão?",
  ui_story_5080_50800602_56_dialog_content = "Rachel? Aquela garotinha de aparência frágil? Eu não acho que ela tenha determinação para isso...",
  ui_story_5080_50800602_57_dialog_content = "De jeito nenhum! Ela não presta! Livre-se dela—",
  ui_story_5080_50800602_58_dialog_content = "Não sou esse tipo de pessoa! Vou provar... Vou provar a todos!",
  ui_story_5080_50800602_59_dialog_content = "Eu sei que você não é, Rachel. Você já é uma mocinha maravilhosa e uma soldado excepcional. Você não tem nada a provar para ninguém.",
  ui_story_5080_50800602_60_dialog_content = "Não, tia... Eu... Eu não quis dizer isso...",
  ui_story_5080_50800602_61_dialog_content = "Tudo bem, Rachel. Eu não me importo com o que as outras pessoas dizem, e você também não deveria.",
  ui_story_5080_50800602_62_dialog_content = "Mantenha essa paixão em seu coração e mostre a eles que você é melhor do que sua tia inútil.",
  ui_story_5080_50800602_63_dialog_content = "Tia... sinto muito...",
  ui_story_5080_50800602_64_dialog_content = "Levante-se e olhe para mim, Rachel. Nada disso é culpa sua.",
  ui_story_5080_50800602_65_dialog_content = "A culpa é minha por trazer tantos problemas para a sua vida. Você vai ter que suportar muito mais críticas no futuro.",
  ui_story_5080_50800602_66_dialog_content = "Mas você não pode deixá-lo derrubar você. Nunca ceda ao que eles dizem sobre você. Lute alto e com todo o seu coração, assim como agora.",
  ui_story_5080_50800602_67_dialog_content = "Sei que você será ainda melhor do que eu jamais poderia esperar ser.",
  ui_story_5080_50800602_68_dialog_content = "Acredite em si mesmo, Rachel. Não importa quais decisões você tome, mantenha-se firme até o amargo fim - E não ouça o que ninguém diz sobre você!",
  ui_story_5080_50800602_69_dialog_content = "Minha tia foi forçada a viver sozinha ao ar livre, mas ela sempre me tratou como sua própria filha... E é por isso... Eu nunca posso perdoar aquela pessoa pelo que ela fez com ela.",
  ui_story_5080_50800602_70_dialog_content = "Então decidi me tornar mais forte, superar meus limites e vencer as amarras do passado da minha família... Eu não queria que aquela tragédia se repetisse nunca mais.",
  ui_story_5080_50800602_71_dialog_content = "Ela vem de uma família de desertores, então ela está destinada a desistir às vezes, certo?",
  ui_story_5080_50800602_72_dialog_content = "De jeito nenhum! Eu acho que ela é super legal por ser tão persistente, então pare de falar dela pelas costas.",
  ui_story_5080_50800602_73_dialog_content = "Então, algum dos novos recrutas chamou sua atenção, Hiiro?",
  ui_story_5080_50800602_74_dialog_content = "De jeito nenhum. Nenhum deles sequer chegou perto de acompanhar meu regime de treinamento.",
  ui_story_5080_50800602_75_dialog_content = "Acho que você está sendo muito duro com eles... Espere, e quanto a <color=#FFB400>ela</color>? Não me diga que <color=#FFB400>ela</color> também não estava à altura?",
  ui_story_5080_50800602_76_dialog_content = "<color=#FFB400>Essa garota</color>... Ela espera muito de si mesma, considerando que não é tão fisicamente apta quanto seus colegas. Se esforçar assim nunca funcionará para ela.",
  ui_story_5080_50800602_77_dialog_content = "Tenho tentado desqualificá-la antes que ela cause algum dano duradouro a si mesma. No entanto, não importa o quão difícil eu torne as coisas para ela, ela teimosamente se recusa a desistir.",
  ui_story_5080_50800602_78_dialog_content = "Em termos de aptidão física, ela é completamente comum, mas no final... Ela foi a única que conseguiu me acompanhar.",
  ui_story_5080_50800602_79_dialog_content = "A Academia está fervilhando com rumores sobre ela e sua família, mas pouco a pouco, seus colegas estão começando a respeitá-la.",
  ui_story_5080_50800602_80_dialog_content = "Não tenho certeza se devo elogiá-la ou não.",
  ui_story_5080_50800602_81_dialog_content = "Um soldado que nunca deixa de se levantar depois de ser derrubado inúmeras vezes... Parece-me que ela tem o que é preciso para ser uma heroína, Hiiro.",
  ui_story_5080_50800602_82_dialog_content = "Você não pode continuar negando ela, então apenas reconheça a determinação dela e cuide bem dela.",
  ui_story_5080_50800602_83_dialog_content = "Não há como ela se deixar ser desqualificada.",
  ui_story_5080_50800602_84_dialog_content = "Cadete Rachel! Em reconhecimento ao seu desempenho exemplar e ao seu espírito indomável, você foi especialmente escolhido pelo Comandante Hiiro para se juntar às fileiras da 3ª Legião!",
  ui_story_5080_50800602_85_dialog_content = "(Então esta é a Rachel... É assim que ela lutou para subir nas fileiras... E se tornou uma capitã de elite digna do respeito de todos.)",
  ui_story_5080_50800602_86_dialog_content = "Entendo... Você sofreu tanto para se tornar a ave de rapina que é hoje.",
  ui_story_5080_50800602_87_dialog_content = "Heh, então você está livre para vê-la como uma traidora se quiser. Afinal, nós apenas trocamos algumas palavras antes dela desaparecer de nossas vidas para sempre.",
  ui_story_5080_50800602_88_dialog_content = "Com a astúcia que ela tinha, eu realmente desejo que ela tivesse conseguido escapar naquela época... Talvez então ela pudesse me dar as respostas que estou procurando.",
  ui_story_5080_50800602_89_dialog_content = "Quais respostas?",
  ui_story_5080_50800602_90_dialog_content = "Este deserto é vasto, não acha? Você poderia ficar de guarda durante a noite sem limites e ainda assim ver apenas uma pequena fração deste lugar.",
  ui_story_5080_50800602_91_dialog_content = "Sua vastidão também é o que o torna tão vazio.",
  ui_story_5080_50800602_92_dialog_content = "Esse vazio... É por isso que você nunca se encaixou com aquelas pessoas?",
  ui_story_5080_50800602_93_dialog_content = "Você disse que viajou para inúmeros lugares, e ainda assim nunca encontrou um lugar onde realmente pertencia, não é? Então você voltou para este lugar...",
  ui_story_5080_50800602_94_dialog_content = "É verdade que o deserto sempre me pareceu estranhamente desconhecido, e que nunca me entendi com os tolos de sangue quente da Rediesel Wrench.",
  ui_story_5080_50800602_95_dialog_content = "Eles são tão barulhentos e selvagens todos os dias, mas eles realmente estão procurando o sentido da vida?",
  ui_story_5080_50800602_96_dialog_content = "Preocupo-me que eles venham a recuperar o juízo algum dia e percebam o quanto de suas vidas desperdiçaram. Só de pensar nisso é aterrorizante.",
  ui_story_5080_50800602_97_dialog_content = "As pessoas estão destinadas a seguir seus próprios caminhos, e a festa tem que acabar algum dia. Não importa o quão brilhantemente brilhemos na vida, todos nós retornaremos ao nada. É assustador, não é?",
  ui_story_5080_50800602_98_dialog_content = "Então você permanece neste deserto, um lugar que não é sua casa nem uma terra desconhecida.",
  ui_story_5080_50800602_99_dialog_content = "Você é apenas outro pássaro solitário no Deserto Rediesel, igual a mim.",
  ui_story_5080_50800602_100_dialog_content = "Você é realmente muito bom em entender os pontos de vista de outras pessoas, sabia? E essa é a marca de um verdadeiro grande capitão.",
  ui_story_5080_50800602_101_dialog_content = "(Se ao menos Vice estivesse acordada para ver isso! Terei que encontrar uma chance para contar a ela sobre isso amanhã.)",
  ui_story_5080_50800602_102_dialog_content = "Eu era apenas uma criança quando aquela pessoa ainda estava viva. Ela me ensinou muitas coisas e abriu meus olhos para a vastidão do mundo.",
  ui_story_5080_50800602_103_dialog_content = "Ela também me motivou a buscar uma vida de liberdade com todo o meu coração. Eu queria encontrar o significado da minha vida e mergulhar de cabeça em um futuro de infinitas possibilidades.",
  ui_story_5080_50800602_104_dialog_content = "Mas então ela morreu sem dizer mais uma palavra. Sua figura orgulhosa e poderosa se tornou apenas mais uma imagem borrada em nossas memórias.",
  ui_story_5080_50800602_105_dialog_content = "Então, o que eu poderia me tornar? Depois de me separar dos meus pais e da Rediesel Wrench, não há lugar para mim neste mundo.",
  ui_story_5080_50800602_106_dialog_content = "E enquanto estou preso neste profundo vazio, esses tolos continuam sem uma única preocupação no mundo. Suspiro... Eu realmente gostaria de saber o que fazer.",
  ui_story_5080_50800602_107_dialog_content = "Por que você está me contando tudo isso?",
  ui_story_5080_50800602_108_dialog_content = "Porque não tenho certeza se poderia falar sobre isso com mais alguém.",
  ui_story_5080_50800602_109_dialog_content = "Suponho que deve haver uma razão melhor para compartilhar meus pensamentos com você. Talvez seja porque você me lembra muito dela... Ou talvez você me lembre de mim mesmo?",
  ui_story_5080_50800602_110_dialog_content = "Tem certeza de que não é apenas... Um pequeno pássaro perdido que se desviou para o deserto?",
  ui_story_5080_50800602_111_dialog_content = "Parte de mim deseja que você estivesse aqui para procurar desertores. Dessa forma, você poderia encontrar aquela pessoa e dar uma lição nela por desaparecer de nossas vidas assim.",
  ui_story_5080_50800602_112_dialog_content = "Se não fosse por ela, talvez eu não estivesse tão frustrado na vida. Afinal, ela transformou a Rediesel Wrench de um grupo de idiotas desonrados em um grupo de despreocupados...",
  ui_story_5080_50800602_113_dialog_content = "Então, por que eu não posso ser como eles?",
  ui_story_5080_50800602_114_dialog_content = "Jeriah, você...",
  ui_story_5080_50800602_115_dialog_content = "Eu vou levar Zeta para a cama. Você deveria descer e dormir um pouco também.",
  ui_story_5080_50800602_116_dialog_content = "Você diz que tudo deve retornar ao nada... E ainda assim, está disposto a segurá-la e carregá-la.",
  ui_story_5080_50800602_117_dialog_content = "Não tem jeito. Depois de cobrir minha casa com a \"arte\" deles, é impossível ignorá-los.",
  ui_story_5080_50800602_118_dialog_content = "O deserto fica frio à noite. Vou pedir para o Speaker substituir você, então descanse um pouco.",
  ui_story_5080_50800602_119_dialog_content = "Além disso... Nosso pobre amigo Celestita vai congelar até a morte se ficarmos aqui fora por mais tempo.",
  ui_story_5080_50800602_120_dialog_content = "(Ela sabia que eu estava aqui o tempo todo!)",
  ui_story_5080_50800602_121_dialog_content = "(Tenho que dar o fora daqui... Ai!)",
  ui_story_5080_50800602_122_dialog_content = "Qu-Quem deixou este balde cheio de água aqui?!",
  ui_story_5080_50800701_1_dialog_content = "Acorda. A missão ainda não acabou.",
  ui_story_5080_50800701_2_dialog_content = "Bocejo... Bom dia, Capitão.",
  ui_story_5080_50800701_3_dialog_content = "... Bom dia, agora vá jogar um pouco de água no rosto e acorde!",
  ui_story_5080_50800701_4_dialog_content = "S-Sim, senhora!",
  ui_story_5080_50800701_5_dialog_content = "Continuamos nosso trabalho de reconhecimento hoje! Acordem e encontrem-se em dez minutos!",
  ui_story_5080_50800701_6_dialog_content = "Deixe-me juntar a você.",
  ui_story_5080_50800701_7_dialog_content = "Se você está procurando por um certo Eclipsite, eu posso ter algumas informações que podem ser úteis.",
  ui_story_5080_50800701_8_dialog_content = "Por que de repente você se interessou em vir conosco? Não pode ser apenas por curiosidade, né?",
  ui_story_5080_50800701_9_dialog_content = "Mesmo que tudo deva retornar ao nada, ainda quero ver como isso termina.",
  ui_story_5080_50800701_10_dialog_content = "Você não me mandaria embora, mandaria?",
  ui_story_5080_50800701_11_dialog_content = "Além disso, se conseguirmos encontrar o lugar de descanso dessa pessoa, gostaria de prestar meus respeitos.",
  ui_story_5080_50800701_12_dialog_content = "... Todos já estão acordados? Vamos nos preparar para partir!",
  ui_story_5080_50800701_13_dialog_content = "Zeta ainda está apagado como uma luz.",
  ui_story_5080_50800701_14_dialog_content = "Deixe a criança dormir. Estamos saindo.",
  ui_story_5080_50800701_15_dialog_content = "Aqui está o mapa que estamos usando para nossa investigação, Jeriah.",
  ui_story_5080_50800701_16_dialog_content = "Pelo que descobri ontem, o ninho dos Eclipsitas provavelmente está em algum lugar ao redor do cinturão vulcânico.",
  ui_story_5080_50800701_17_dialog_content = "Marquei vários locais no mapa. Você poderia nos ajudar a descartar algum desses lugares?",
  ui_story_5080_50800701_18_dialog_content = "Infelizmente, minha pequena ave de rapina, você não encontrará sua resposta em nenhum desses locais.",
  ui_story_5080_50800701_19_dialog_content = "O que você e a maioria dos outros estrangeiros não sabem é que um enorme vulcão adormecido está escondido sob as areias do Deserto de Rediesel.",
  ui_story_5080_50800701_20_dialog_content = "Um vulcão adormecido?",
  ui_story_5080_50800701_21_dialog_content = "Sim, embora eu suponha que isso não seja exatamente o caso agora. Apenas ontem, confirmei que o vulcão está ativo novamente.",
  ui_story_5080_50800701_22_dialog_content = "Embora esse tipo de Eclipsita tenha sido visto vagando por todo o deserto, temo que seu ninho só possa estar naquele lugar.",
  ui_story_5080_50800701_23_dialog_content = "Afinal, é o único lugar que a Chave Rediesel geralmente evita.",
  ui_story_5080_50800701_24_dialog_content = "Por quê?",
  ui_story_5080_50800701_25_dialog_content = "A última vez que o vulcão subterrâneo entrou em erupção foi durante a Crise Darkover. Naquela época, inúmeros Eclipsitas surgiram das fissuras no chão e atacaram o Rediesel Wrench.",
  ui_story_5080_50800701_26_dialog_content = "O líder deles na época morreu durante aquela batalha, junto com os pais de Zeta e muitos outros.",
  ui_story_5080_50800701_27_dialog_content = "Desde então, a Rediesel Wrench fez do deserto sua casa, mas eles sempre evitam aquele lugar.",
  ui_story_5080_50800701_28_dialog_content = "Mas se eles sabem que esses Eclipsitas saíram do vulcão, por que não tentaram investigar isso depois de todos esses anos?",
  ui_story_5080_50800701_29_dialog_content = "Eles fizeram, mas nunca encontraram nada.",
  ui_story_5080_50800701_30_dialog_content = "O vulcão tem estado completamente adormecido desde aquele dia, e agora apenas Eclipsitas regulares habitam aquele lugar.",
  ui_story_5080_50800701_31_dialog_content = "A Rediesel Wrench já foi limpar a área algumas vezes, mas nenhum sinal dos Eclipsitas jamais foi descoberto.",
  ui_story_5080_50800701_32_dialog_content = "No início, todos pensavam que eram os únicos de sua espécie e haviam perecido naquela batalha junto com o líder da Rediesel Wrench e os outros.",
  ui_story_5080_50800701_33_dialog_content = "Após tantas campanhas de extermínio, até mesmo os Eclipsitas regulares no vulcão diminuíram em números.",
  ui_story_5080_50800701_34_dialog_content = "As pessoas tendem a evitar suas memórias mais dolorosas. Com o tempo, elas pararam de ir àquele lugar completamente.",
  ui_story_5080_50800701_35_dialog_content = "Mas essa costumava ser a casa deles... Como eles poderiam simplesmente abandoná-la assim?",
  ui_story_5080_50800701_36_dialog_content = "Não fique tão triste, PlayerName! Fizemos um ótimo trabalho reconstruindo Eraveil, lembra? Tudo o que temos que fazer agora é encontrar mais do seu povo!",
  ui_story_5080_50800701_37_dialog_content = "Heheh, Vice pode estar certo. Talvez alguns de seus compatriotas Celestitas tenham escolhido viajar pelo mundo tão livremente quanto os próprios pássaros.",
  ui_story_5080_50800701_38_dialog_content = "E talvez um dia... Aqueles pássaros voltarão para o ninho novamente.",
  ui_story_5080_50800701_39_dialog_content = "...",
  ui_story_5080_50800701_40_dialog_content = "De qualquer forma, sou a única pessoa que ainda visita sua antiga casa de vez em quando.",
  ui_story_5080_50800701_41_dialog_content = "E enquanto minhas investigações não foram frutíferas, ainda sei o caminho para lá.",
  ui_story_5080_50800701_42_dialog_content = "Então deixaremos a navegação por sua conta, Jeriah. Aqui está o mapa.",
  ui_story_5080_50800701_43_dialog_content = "Entendido, agora vamos indo.",
  ui_story_5080_50800701_44_dialog_content = "O-O chão tá tremendo!",
  ui_story_5080_50800701_45_dialog_content = "Olha! O vulcão está em erupção!",
  ui_story_5080_50800701_46_dialog_content = "Não fique tão alarmado. Devemos continuar seguindo nosso caminho.",
  ui_story_5080_50800701_47_dialog_content = "A atividade vulcânica não é novidade no Deserto Rediesel, mas esse não é o lugar que estamos procurando.",
  ui_story_5080_50800701_48_dialog_content = "O vulcão em questão esteve adormecido por anos. Mesmo na borda de sua cratera, não encontrei sinais de atividade até recentemente.",
  ui_story_5080_50800701_49_dialog_content = "Mas agora... Rugidos começaram a surgir das profundezas do vulcão. Os rugidos dos Eclipsitas.",
  ui_story_5080_50800701_50_dialog_content = "E se esse tipo de Eclipsita retornou ao vulcão, então algo estranho deve estar acontecendo neste exato momento.",
  ui_story_5080_50800701_51_dialog_content = "Precisamos nos apressar!",
  ui_story_5080_50800701_52_dialog_content = "Por aqui. Podemos chegar à cratera do vulcão descendo daqui.",
  ui_story_5080_50800701_53_dialog_content = "Uau... Este lugar está coberto de marcas de queimadura da lava!",
  ui_story_5080_50800701_54_dialog_content = "Esses poderiam ter sido deixados pelos Eclipsitas? Ou talvez seja apenas do vulcão?",
  ui_story_5080_50800701_55_dialog_content = "Não tenho certeza... Eu estava tão ocupado com a minha investigação ontem que não me aventurei muito para baixo.",
  ui_story_5080_50800701_56_dialog_content = "Mas uma coisa é certa: este vulcão está ativo agora.",
  ui_story_5080_50800701_57_dialog_content = "Espere, isso não significa que é perigoso ir lá embaixo?",
  ui_story_5080_50800701_58_dialog_content = "Carleen, você pode ficar aqui e guardar a entrada e nosso carro?",
  ui_story_5080_50800701_59_dialog_content = "Entendido. Deixe comigo.",
  ui_story_5080_50800701_60_dialog_content = "Um poder inimaginável está fazendo o chão tremer levemente.",
  ui_story_5080_50800701_61_dialog_content = "Este vulcão está longe de estar extinto.",
  ui_story_5080_50800701_62_dialog_content = "Esses rastros no chão... Foram deixados pelos Eclipsitas?",
  ui_story_5080_50800701_63_dialog_content = "Eles parecem estar indo mais fundo no vulcão. Vamos lá.",
  ui_story_5080_50800701_64_dialog_content = "Espere, Rachel!",
  ui_story_5080_50800701_65_dialog_content = "Dê uma olhada nisso!",
  ui_story_5080_50800701_66_dialog_content = "Esta passagem parece ter sido escavada recentemente.",
  ui_story_5080_50800701_67_dialog_content = "Olha! A cratera está logo à frente!",
  ui_story_5080_50800701_68_dialog_content = "Por que há um túnel tão grande e recentemente escavado tão perto da cratera...?",
  ui_story_5080_50800701_69_dialog_content = "Dê uma olhada naquela parede, jovem Celestita.",
  ui_story_5080_50800701_70_dialog_content = "Marcas de garras? Elas são realmente profundas, como se tivessem sido deixadas por algo gigantesco...",
  ui_story_5080_50800701_71_dialog_content = "Não há como negar. Essas marcas de garras pertencem àquele dragão de antigamente.",
  ui_story_5080_50800701_72_dialog_content = "Parece que este lugar é seu covil, ou talvez seu terreno de caça.",
  ui_story_5080_50800701_73_dialog_content = "Não é de se admirar que Azure não tenha conseguido encontrar todo esse tempo.",
  ui_story_5080_50800701_74_dialog_content = "É porque o dragão tem várias tocas, e uma delas está em um lugar que a maioria das pessoas evita no Deserto de Rediesel...",
  ui_story_5080_50800701_75_dialog_content = "Mas Jeriah... Como você sabia que Azure estava procurando por isso?",
  ui_story_5080_50800701_76_dialog_content = "Heh, como eu disse, fui designado para este deserto inteiro, afinal.",
  ui_story_5080_50800701_77_dialog_content = "(Por favor... É tão claro quanto o dia, Jeriah... Você realmente se importa com todos na Rediesel Wrench.)",
  ui_story_5080_50800701_78_dialog_content = "Agora que penso nisso, os avistamentos do dragão parecem corresponder às erupções do vulcão.",
  ui_story_5080_50800701_79_dialog_content = "Talvez ele tenha que evacuar o vulcão e procurar outro covil sempre que ele entra em erupção?",
  ui_story_5080_50800701_80_dialog_content = "Mas se tem medo de lava, por que escolheu viver em um vulcão?",
  ui_story_5080_50800701_81_dialog_content = "Isso não faz sentido.",
  ui_story_5080_50800701_82_dialog_content = "Porque estava se escondendo de uma certa pessoa.",
  ui_story_5080_50800701_83_dialog_content = "Naquela época, aquela pessoa estava vasculhando o deserto em busca de sua presa perigosa. Para evitar ela, o dragão não teve escolha senão se esconder profundamente no subsolo...",
  ui_story_5080_50800701_84_dialog_content = "O chão está tremendo de novo!",
  ui_story_5080_50800701_85_dialog_content = "Algo não está certo... A fonte do terremoto parece estar bem abaixo de nós! Será que o vulcão está prestes a entrar em erupção?!",
  ui_story_5080_50800701_86_dialog_content = "A missão encontrou um obstáculo impossível, Capitão! Precisamos recuar por agora!",
  ui_story_5080_50800701_87_dialog_content = "... O resto de vocês pode seguir sem mim. Vou continuar com a missão.",
  ui_story_5080_50800701_88_dialog_content = "Mas Capitão... É muito perigoso ficar aqui embaixo!",
  ui_story_5080_50800701_89_dialog_content = "A missão vem antes de tudo.",
  ui_story_5080_50800701_90_dialog_content = "É natural para um predador perseguir sua presa com tanta persistência.",
  ui_story_5080_50800701_91_dialog_content = "No entanto, sua disposição em sacrificar sua vida por algo tão ilusório me confunde. Diga-me, você está sendo muito inflexível sobre isso, ou você está realmente hesitando?",
  ui_story_5080_50800701_92_dialog_content = "Não há necessidade de arriscar nossas vidas nessa situação, Capitão! Sempre podemos voltar mais tarde!",
  ui_story_5080_50800701_93_dialog_content = "Isso não vai funcionar. Se o vulcão entrar em erupção, todo este lugar será inundado com magma, e quando esfriar...",
  ui_story_5080_50800701_94_dialog_content = "Apenas vá!",
  ui_story_5080_50800701_95_dialog_content = "Estamos saindo daqui juntos, Capitão!",
  ui_story_5080_50800701_96_dialog_content = "Filhote Dois... Por que você tinha que dizer isso assim...?",
  ui_story_5080_50800701_97_dialog_content = "Uhh?",
  ui_story_5080_50800701_98_dialog_content = "(Ela está falando sobre antes... O antigo companheiro de equipe de Rachel disse exatamente a mesma coisa...)",
  ui_story_5080_50800701_99_dialog_content = "Eu não posso fugir... Eu não vou...",
  ui_story_5080_50800701_100_dialog_content = "Cuidado! Sinto os Eclipsitas vindo em nossa direção!",
  ui_story_5080_50800701_101_dialog_content = "Podemos falar sobre a fuga mais tarde! Preparem-se para lutar, todos!",
  ui_story_5080_50800702_1_dialog_content = "A-Acabou finalmente.",
  ui_story_5080_50800702_2_dialog_content = "Os tremores também pararam... Isso significa que o vulcão está estável agora?",
  ui_story_5080_50800702_3_dialog_content = "Por que aqueles Eclipsitas eram tão poderosos? Em todas as minhas investigações, nunca vi nada parecido com eles aqui embaixo.",
  ui_story_5080_50800702_4_dialog_content = "Os corpos deles... São essas mutações?",
  ui_story_5080_50800702_5_dialog_content = "Está acontecendo de novo!",
  ui_story_5080_50800702_6_dialog_content = "É muito perigoso aqui, Capitão! Devemos pelo menos recuar para o túnel de antes!",
  ui_story_5080_50800702_7_dialog_content = "Estamos muito perto da cratera do vulcão aqui.",
  ui_story_5080_50800702_8_dialog_content = "Tudo bem... Faremos como o Filhote Dois sugere e procuraremos outra rota—",
  ui_story_5080_50800702_9_dialog_content = "Espere, esse tremor... Isso não é o vulcão de jeito nenhum!",
  ui_story_5080_50800702_10_dialog_content = "Cuidado, todos! O túnel está prestes a desabar—!!!",
  ui_story_5080_50800702_11_dialog_content = "A Rediesel Wrench sempre foi um grupo de pessoas tão indisciplinado.",
  ui_story_5080_50800702_12_dialog_content = "Ei Jeriah, venha construir este carro conosco! Aposto que podemos terminá-lo hoje se trabalharmos duro!",
  ui_story_5080_50800702_13_dialog_content = "Sim, e então podemos usá-lo para pegar toneladas de lagartos de areia!",
  ui_story_5080_50800702_14_dialog_content = "Não, obrigado.",
  ui_story_5080_50800702_15_dialog_content = "Ah, mas por quê? Você nunca quer sair, Jeriah!",
  ui_story_5080_50800702_16_dialog_content = "Sem problemas, vamos tentar novamente amanhã!",
  ui_story_5080_50800702_17_dialog_content = "Mesmo quando eu disse não, não fez diferença. Ainda assim, eu nunca consegui me encaixar com os outros.",
  ui_story_5080_50800702_18_dialog_content = "Ah! Parece que eu te encontrei de novo!",
  ui_story_5080_50800702_19_dialog_content = "Eu não estava brincando de esconde-esconde com você.",
  ui_story_5080_50800702_20_dialog_content = "Então isso significa que você estava esperando por mim, certo?",
  ui_story_5080_50800702_21_dialog_content = "Viu? Você só está corando porque eu estou certo!",
  ui_story_5080_50800702_22_dialog_content = "N-De jeito nenhum.",
  ui_story_5080_50800702_23_dialog_content = "Aqui está. Não foi fácil, mas consegui encontrar mais alguns materiais didáticos da Illumina.",
  ui_story_5080_50800702_24_dialog_content = "Você foi lá de novo?",
  ui_story_5080_50800702_25_dialog_content = "Sim! Eu tinha negócios a fazer com alguns comerciantes do mercado negro em Umbraton.",
  ui_story_5080_50800702_26_dialog_content = "Quer saber de uma coisa? Existe esse incrível conjunto de ruínas antigas logo fora de Umbraton, e é construído com materiais que nem mesmo conhecemos.",
  ui_story_5080_50800702_27_dialog_content = "Está cheio de gangsters e pessoas vendendo coisas no mercado negro. Eles transformaram todo o lugar em um tipo de labirinto louco.",
  ui_story_5080_50800702_28_dialog_content = "Todos estão procurando por qualquer coisa que possa gerar lucro. Eles nem percebem que as próprias ruínas são a coisa mais valiosa que existe!",
  ui_story_5080_50800702_29_dialog_content = "O que você quer dizer? Que outro valor algumas ruínas antigas podem ter, além de serem um ponto turístico?",
  ui_story_5080_50800702_30_dialog_content = "Você está perguntando isso sério?!",
  ui_story_5080_50800702_31_dialog_content = "Do que você acha que essas ruínas são feitas? Por que foram construídas? E quem exatamente as construiu?",
  ui_story_5080_50800702_32_dialog_content = "Que tipo de tecnologia podemos encontrar lá? E o que essa tecnologia pode fazer por nós?",
  ui_story_5080_50800702_33_dialog_content = "Como era a civilização antiga? Que tipo de mundo eles criaram para si mesmos e por que desapareceu?",
  ui_story_5080_50800702_34_dialog_content = "Essas ruínas podem responder todas essas perguntas e mais.",
  ui_story_5080_50800702_35_dialog_content = "Alguns corredores antigos realmente podem te dizer tanto assim?",
  ui_story_5080_50800702_36_dialog_content = "Com um pouco de tempo e persuasão, claro!",
  ui_story_5080_50800702_37_dialog_content = "Você quer dizer... Aquela vez que você me contou antes?",
  ui_story_5080_50800702_38_dialog_content = "Que horas?",
  ui_story_5080_50800702_39_dialog_content = "Quando você estava explorando o Território Secreto em Northland.",
  ui_story_5080_50800702_40_dialog_content = "Ah, você quer dizer aquela vez que eu te ensinei a empinar uma pipa!",
  ui_story_5080_50800702_41_dialog_content = "Isso mesmo, essas ruínas descreveram um tipo de máquina voadora. Quando a Illumina descobriu isso, começaram a investir toneladas de recursos na pesquisa.",
  ui_story_5080_50800702_42_dialog_content = "Mas para uma pessoa solitária como eu, tudo o que eu poderia fazer era fazer uma pipa para você.",
  ui_story_5080_50800702_43_dialog_content = "Então, o que você viu naquelas outras ruínas?",
  ui_story_5080_50800702_44_dialog_content = "Havia muitas pessoas vagando por aí, então não tive a chance de fazer nenhuma pesquisa.",
  ui_story_5080_50800702_45_dialog_content = "Mas vou me certificar de dar uma boa olhada ao redor na próxima vez que eu for.",
  ui_story_5080_50800702_46_dialog_content = "Eu até posso encontrar algo legal para trazer de volta para você, Jeriah!",
  ui_story_5080_50800702_47_dialog_content = "... Posso te perguntar uma coisa?",
  ui_story_5080_50800702_48_dialog_content = "Hã? Claro, vá em frente.",
  ui_story_5080_50800702_49_dialog_content = "Você basicamente já viu todo o Astra, então por que ainda fica tão animado com tudo?",
  ui_story_5080_50800702_50_dialog_content = "Nada neste mundo deveria te surpreender mais. Se for o caso, você já deveria estar totalmente entediado agora...",
  ui_story_5080_50800702_51_dialog_content = "Ei Jeriah, você leu todos os livros que eu trouxe para você?",
  ui_story_5080_50800702_52_dialog_content = "É. Todos os cinco mil, seiscentos e oitenta e três deles.",
  ui_story_5080_50800702_53_dialog_content = "Mas mesmo essa quantidade de livros não poderia começar a contar toda a história de Astra.",
  ui_story_5080_50800702_54_dialog_content = "Você também sabia que existem outros continentes no mundo além do nosso? Que tipo de pessoas e lugares existem lá fora, eu me pergunto?",
  ui_story_5080_50800702_55_dialog_content = "Não faço ideia, mas sempre tive curiosidade de saber.",
  ui_story_5080_50800702_56_dialog_content = "Estive na maioria dos lugares em Astra, mas ainda não consigo lembrar todas as estradas que percorri.",
  ui_story_5080_50800702_57_dialog_content = "Você pode não perceber isso agora, Jeriah, mas também tem um desejo ardente de explorar o mundo.",
  ui_story_5080_50800702_58_dialog_content = "Você não é como eu, passando por todas as paisagens do mundo sem parar para apreciá-las. É por isso que acho que você aprenderá mais sobre este mundo do que eu jamais aprenderei.",
  ui_story_5080_50800702_59_dialog_content = "Pare de acariciar minha cabeça...",
  ui_story_5080_50800702_60_dialog_content = "Tudo bem! Você queria uma resposta, então aqui está! Mesmo que eu tenha ido a muitos lugares diferentes, raramente faço memórias quando estou lá fora.",
  ui_story_5080_50800702_61_dialog_content = "E quando a noite cai sobre o deserto, percebo que mal me lembro de qualquer uma das coisas bonitas que vi na minha vida.",
  ui_story_5080_50800702_62_dialog_content = "Isso é porque... Como um soldado da Illumina, você está sempre sendo enviado para missões.",
  ui_story_5080_50800702_63_dialog_content = "Embora eu também possa estar errado! Hahaha!",
  ui_story_5080_50800702_64_dialog_content = "Você é uma criança inteligente, Jeriah. Eu sei que você tem muitas perguntas, e eu sei que é horrível quando você não encontra as respostas que está procurando.",
  ui_story_5080_50800702_65_dialog_content = "Mas não tem jeito. Você ainda é uma criança, afinal!",
  ui_story_5080_50800702_66_dialog_content = "Então cresça e aprenda tudo o que puder, Jeriah! Tenho certeza de que você será capaz de resolver qualquer questão que surgir no futuro!",
  ui_story_5080_50800702_67_dialog_content = "E não desperdice sua vida correndo por aí como eu fiz. Sempre lembre-se de parar e cheirar as rosas.",
  ui_story_5080_50800702_68_dialog_content = "Tenho certeza de que você encontrará o significado da sua vida e fará muitas memórias maravilhosas ao longo do caminho.",
  ui_story_5080_50800702_69_dialog_content = "Abra suas asas e viva livremente, Jeriah. Só então você encontrará... As respostas que você está tão desesperado para saber.",
  ui_story_5080_50800702_70_dialog_content = "Não entendi.",
  ui_story_5080_50800702_71_dialog_content = "<color=#FFB400>Ela</color> e eu deveríamos ser iguais. Ambos nascemos em lugares aos quais não pertencíamos.",
  ui_story_5080_50800702_72_dialog_content = "Eu queria deixar o deserto e deixar minha marca no mundo onde quer que eu fosse. Mas depois de se libertar da Illumina, ela escolheu vir para cá de todos os lugares.",
  ui_story_5080_50800702_73_dialog_content = "Por que... Por que você escolheu ficar?",
  ui_story_5080_50800702_74_dialog_content = "Você ainda se lembra da <color=#FFB400>história</color> que eu te contei, Jeriah?",
  ui_story_5080_50800702_75_dialog_content = "Uhum.",
  ui_story_5080_50800702_76_dialog_content = "E no final dessa história, você encontrou <color=#FFB400>esta chave inglesa</color> e um grupo de pessoas que dependiam de você. Você não estava mais sozinho.",
  ui_story_5080_50800702_77_dialog_content = "Então, para o bem de todos, você uniu todos os nômades do deserto e formou a Rediesel Wrench.",
  ui_story_5080_50800702_78_dialog_content = "Você nunca foi responsável por nenhum deles... Então por que escolheu ficar por eles? Você não quer guardar...",
  ui_story_5080_50800702_79_dialog_content = "Qual o problema em querer voltar para casa? Afinal, eu nasci e fui criada neste deserto. Além disso, eu também quero que eles tenham sua liberdade.",
  ui_story_5080_50800702_80_dialog_content = "Viver sem autoconsciência não nos torna diferentes dos Eclipsitas, você não acha? Eu quero libertar suas almas e dar a eles o poder de tomar suas próprias decisões.",
  ui_story_5080_50800702_81_dialog_content = "Eu já desperdicei a maior parte da minha própria vida.",
  ui_story_5080_50800702_82_dialog_content = "Então, eu desejo que eles entendam sua jornada e vivam uma vida de liberdade.",
  ui_story_5080_50800702_83_dialog_content = "Tornar-se espíritos livres que vivem o momento, alegremente causando travessuras - é isso que é a liberdade?",
  ui_story_5080_50800702_84_dialog_content = "Não entendo...",
  ui_story_5080_50800702_85_dialog_content = "É por causa das suas histórias que descobri que havia muito mais esperando por mim para descobrir.",
  ui_story_5080_50800702_86_dialog_content = "Naquela época, eu estava completamente absorto em explorar este mundo.",
  ui_story_5080_50800702_87_dialog_content = "Oh? Isso é bastante impressionante, Jeriah.",
  ui_story_5080_50800702_88_dialog_content = "Mas este mundo não é tão incrível quanto você descreveu. Você mentiu para mim.",
  ui_story_5080_50800702_89_dialog_content = "Os nobres de Lumópolis são arrogantes, a Federação Illumina é sempre tão monótona, e o povo de Northland permanece preso em seus próprios contos de fadas.",
  ui_story_5080_50800702_90_dialog_content = "O Corredor Suspirante de Umbraton se tornou o tesouro de Istvan. Essas chamadas ruínas lendárias são apenas as indiferentes paredes internas de seus cofres.",
  ui_story_5080_50800702_91_dialog_content = "Tudo parece tão vazio...",
  ui_story_5080_50800702_92_dialog_content = "Mesmo os Celestitas, que criaram tantos milagres científicos, acabaram se tornando memórias das quais as pessoas raramente falam.",
  ui_story_5080_50800702_93_dialog_content = "Os Eclipsitas atacam, nós contra-atacamos... Toda a vida neste mundo está presa em um ciclo vicioso desesperado pela sobrevivência.",
  ui_story_5080_50800702_94_dialog_content = "Tudo voltará ao nada.",
  ui_story_5080_50800702_95_dialog_content = "O pequeno Jeriah finalmente cresceu, mas você se preocupa demais.",
  ui_story_5080_50800702_96_dialog_content = "Eu não entendo... Devo parar de fazer perguntas?",
  ui_story_5080_50800702_97_dialog_content = "Se a inteligência apenas convida o vazio da solidão, devo escolher me juntar àqueles tolos despreocupados?",
  ui_story_5080_50800702_98_dialog_content = "Mas Jeriah, o último Celestita está aqui.",
  ui_story_5080_50800702_99_dialog_content = "Você deve saber que, a partir do momento em que ele voltar, Eraveil nunca mais será uma memória esquecida. Sua história começará de novo com um herdeiro para levar adiante essas memórias.",
  ui_story_5080_50800702_100_dialog_content = "A paisagem do mundo permanece sempre a mesma?",
  ui_story_5080_50800702_101_dialog_content = "A caprichosidade do destino não traz apenas tédio ou dor.",
  ui_story_5080_50800702_102_dialog_content = "Essas conexões, como cordas firmes, seguram você, a pipa incontrolável...",
  ui_story_5080_50800702_103_dialog_content = "Espere! Aonde você está indo? Não vá embora!",
  ui_story_5080_50800702_104_dialog_content = "Você deve ter sentido isso - eles estão te chamando.",
  ui_story_5080_50800702_105_dialog_content = "Em seus olhos, certamente não sou uma boa professora. Mas em meus olhos, Jeriah... Estou muito feliz por ter te conhecido.",
  ui_story_5080_50800702_106_dialog_content = "Espere! Volte! Não vá! Não vá—<color=#FFB400>Attar</color>—!",
  ui_story_5080_50800702_107_dialog_content = "Jeriah!",
  ui_story_5080_50800702_108_dialog_content = "...?",
  ui_story_5080_50800702_109_dialog_content = "Ótimo, você acordou.",
  ui_story_5080_50800702_110_dialog_content = "Esse pequeno punk estava surtando... Ele ficou aqui o tempo todo tentando usar seus \"movimentos especiais\" em você.",
  ui_story_5080_50800702_111_dialog_content = "Sinsa...?",
  ui_story_5080_50800702_112_dialog_content = "E nós também.",
  ui_story_5080_50800702_113_dialog_content = "... Por que parece que metade da Rediesel Wrench está aqui?",
  ui_story_5080_50800702_114_dialog_content = "Encantadora! Uau, você finalmente acordou! Onde dói?",
  ui_story_5080_50800702_115_dialog_content = "Por que você deixou seu lendário herói favorito para trás?! Acordei assim que ouvi você chegar!",
  ui_story_5080_50800702_116_dialog_content = "Eu estava lutando contra os Eclipsitas quando ela veio atrás de mim em uma fúria, bem a tempo de quebrar o cerco.",
  ui_story_5080_50800702_117_dialog_content = "Mas ela estava muito empolgada, não me ouviu por um segundo. Minha única opção era trazê-la aqui para encontrar você...",
  ui_story_5080_50800702_118_dialog_content = "E então a caverna desabou repentinamente! Não parece algo saído diretamente de uma história de aventura?",
  ui_story_5080_50800702_119_dialog_content = "Em relação ao colapso da caverna, senti na época que era um pouco diferente dos tremores de um vulcão...",
  ui_story_5080_50800702_120_dialog_content = "É tudo culpa de Sinsa, balançando aquela chave inglesa como um bruto... Eu te disse que a caverna era instável.",
  ui_story_5080_50800702_121_dialog_content = "Eu não te pedi para me seguir.",
  ui_story_5080_50800702_122_dialog_content = "Isso é outra coisa - por que você chamou tantas pessoas e não eu? Você deve realmente ter algo contra mim, hein...",
  ui_story_5080_50800702_123_dialog_content = "Ei, não culpe o Sinsa. Estávamos apenas procurando o tipo certo de ajuda, só isso.",
  ui_story_5080_50800702_124_dialog_content = "Hã? Você quer dizer que Jona é mais útil do que eu?",
  ui_story_5080_50800702_125_dialog_content = "Também é perigoso lá fora na selva. Jona precisava ficar em casa e segurar as pontas.",
  ui_story_5080_50800702_126_dialog_content = "Não se preocupe, uma vez que Azure volte, Jona virá para alcançar.",
  ui_story_5080_50800702_127_dialog_content = "Você está certo, Dawn. Jona pode rastrear Eclipsitas. E você... não se subestime, grandão. Você sabe que eu confio em você.",
  ui_story_5080_50800702_128_dialog_content = "Não, isso está todo errado! Os papéis de todos são bem claros - qual de vocês não consegue manter a boca fechada?! Por que você e Eve apareceram?!",
  ui_story_5080_50800702_129_dialog_content = "Desculpe... É porque eu percebi que você e Dawn estavam faltando, então eu perguntei por aí...",
  ui_story_5080_50800702_130_dialog_content = "Aaaaah!!! Esses caras não conseguem nem guardar um segredo do pequeno Eve?!",
  ui_story_5080_50800702_131_dialog_content = "Você estava planejando me deixar e ao Eve para trás, né? Inaceitável! Você me ouviu?! Eu dei tudo de mim apenas para alcançar vocês!",
  ui_story_5080_50800702_132_dialog_content = "Brock, você deveria levar Eve de volta, é muito perigoso aqui.",
  ui_story_5080_50800702_133_dialog_content = "A estrada desabou - seria muito perigoso tentar encontrar outro caminho de volta agora. Sugiro que os deixemos ficar.",
  ui_story_5080_50800702_134_dialog_content = "Chega de discussão! Caramba... Como as coisas acabaram assim...?",
  ui_story_5080_50800702_135_dialog_content = "Bem, já que realmente não temos mais escolha... Eve, Brock—vocês dois podem ficar. Mas Eve, apenas certifique-se de ficar por perto!",
  ui_story_5080_50800702_136_dialog_content = "Beleza!",
  ui_story_5080_50800702_137_dialog_content = "Vamos nos unir e enfrentar bravamente o desconhecido!",
  ui_story_5080_50800702_138_dialog_content = "Organizei uma pequena celebração de vitória só minha. Ninguém pode faltar - entenderam, pessoal?",
  ui_story_5080_50800702_139_dialog_content = "Lembre-se disso - não tente ser um herói! Se o problema te encontrar, se esconda atrás de mim - isso vale para vocês também, PlayerName.",
  ui_story_5080_50800702_140_dialog_content = "A Chave Rediesel... Então finalmente chegou a isso. Bem...",
  ui_story_5080_50800702_141_dialog_content = "Você, Garota Pirulito - você pode me seguir, eu...",
  ui_story_5080_50800702_142_dialog_content = "Eu vou te proteger.",
  ui_story_5080_50800802_1_dialog_content = "Já que chegamos tão longe juntos, acho que há algumas coisas que eu não preciso mais esconder de você.",
  ui_story_5080_50800802_2_dialog_content = "Roy, eu vou apenas contar a eles. O terreno aqui está ficando cada vez mais baixo... Podemos encontrar o jackpot a qualquer momento.",
  ui_story_5080_50800802_3_dialog_content = "Sem objeções aqui. Se houver algo que você não entendeu, eu vou explicar.",
  ui_story_5080_50800802_4_dialog_content = "Por que tudo isso parece tão formal de repente...?",
  ui_story_5080_50800802_5_dialog_content = "Deixe-me levá-lo de volta quinze anos. A Crise Darkover já havia irrompido por toda Astra - estávamos resistindo desesperadamente ao surto por um tempo.",
  ui_story_5080_50800802_6_dialog_content = "Ninguém teria adivinhado que havia um vulcão escondido sob o acampamento. Ele entrou em erupção sem aviso prévio, e uma enxurrada de Eclipsitas começou a jorrar da enorme fissura que criou.",
  ui_story_5080_50800802_7_dialog_content = "Fomos pegos de surpresa e tivemos que lutar enquanto recuávamos do acampamento.",
  ui_story_5080_50800802_8_dialog_content = "Eu tinha apenas dezesseis anos, ordenado a evacuar pelos chefões. Eu não era forte o suficiente... Eu só podia proteger Eve e os outros enquanto fugíamos.",
  ui_story_5080_50800802_9_dialog_content = "Eu estava seguindo os líderes naquela época também. Estávamos cobrindo a retaguarda juntos... mas no final, eles me disseram para correr à frente.",
  ui_story_5080_50800802_10_dialog_content = "Nossos líderes... Eles se sacrificaram naquela última batalha.",
  ui_story_5080_50800802_11_dialog_content = "Aquele dragão perverso também estava lá. A princípio, o chefe parecia ser capaz de lidar com isso, mas—",
  ui_story_5080_50800802_12_dialog_content = "As erupções se tornaram mais intensas, e um Eclipsita coberto de magma surgiu de debaixo da terra.",
  ui_story_5080_50800802_13_dialog_content = "Aquele Eclipsita coberto de magma, não há dúvida - esse é o nosso alvo.",
  ui_story_5080_50800802_14_dialog_content = "O chefe parecia ter algum tipo de conexão com isso. Ela ficou surpresa e... com medo quando viu.",
  ui_story_5080_50800802_15_dialog_content = "Ela disse que sabia o quão forte aquela coisa era. Foi por isso que ela nos disse para sairmos de lá.",
  ui_story_5080_50800802_16_dialog_content = "A maneira como ela deu aquele comando final... tudo o que eu podia fazer era correr. No final, ela avançou com alguns outros membros seniores da gangue.",
  ui_story_5080_50800802_17_dialog_content = "Hum...",
  ui_story_5080_50800802_18_dialog_content = "(Estou sentindo uma forte onda de emoção... É... Rachel?)",
  ui_story_5080_50800802_19_option_content = "(Ela está perdendo a calma?)",
  ui_story_5080_50800802_20_dialog_content = "(Certo. Aquela líder é a mesma desertora que arruinou a reputação de sua tia.)",
  ui_story_5080_50800802_21_option_content = "(Ela está se recusando a acreditar em tudo isso?)",
  ui_story_5080_50800802_22_dialog_content = "(Deve ser difícil para ela acreditar que a líder daquela época era do tipo que se sacrificava tão nobremente...)",
  ui_story_5080_50800802_23_dialog_content = "(Em seu coração, aquela líder sempre foi uma desertora, com medo da morte, mas para a Rediesel Wrench, ela é claramente uma heroína!)",
  ui_story_5080_50800802_24_dialog_content = "Não há muito a dizer sobre o que aconteceu depois disso.",
  ui_story_5080_50800802_25_dialog_content = "Graças ao pequeno Sinsa, embora fosse jovem, seu comando era claro como o dia. Mais importante, ele tinha a coragem de um verdadeiro chefe.",
  ui_story_5080_50800802_26_dialog_content = "Sob sua liderança, começamos a lançar operações de guerrilha e, eventualmente, encontramos Lepidoz.",
  ui_story_5080_50800802_27_dialog_content = "Não só conseguimos nos reerguer, como também salvamos um monte de nômades do deserto perdidos no processo, e nossos números começaram a crescer.",
  ui_story_5080_50800802_28_dialog_content = "Nosso antigo líder morreu, mas a crise não acabou. Todos os outros estavam ocupados chorando por nossas perdas, então o que mais eu poderia fazer senão pensar em maneiras de animá-los?",
  ui_story_5080_50800802_29_dialog_content = "Eve e eu éramos estranhos. A chefe fez o melhor para cuidar de nós, e todos nos ajudaram muito.",
  ui_story_5080_50800802_30_dialog_content = "Ninguém queria ser o vilão! Ninguém queria ter que dizer as duras verdades que as pessoas precisavam ouvir, então eu fiz tudo! O chefe se foi - não podíamos nos dar ao luxo de perder mais ninguém.",
  ui_story_5080_50800802_31_dialog_content = "Não me importava quem me chamava de grosseiro ou irracional, contanto que todos sobrevivessem, eu sentia que estava fazendo o certo pelo chefe.",
  ui_story_5080_50800802_32_dialog_content = "Na época, eu realmente não pensei muito em mais nada.",
  ui_story_5080_50800802_33_dialog_content = "Não seja modesto - não combina com você, grandão.",
  ui_story_5080_50800802_34_dialog_content = "Chega de coisas melosas! Isso é tudo além do ponto!",
  ui_story_5080_50800802_35_dialog_content = "Depois que o vulcão se acalmou, gradualmente eliminamos todos os Eclipsitas.",
  ui_story_5080_50800802_36_dialog_content = "E depois que a magma esfriou, tudo o que encontramos de volta no que restou do acampamento foi aquela chave inglesa.",
  ui_story_5080_50800802_37_dialog_content = "O dragão maligno, o chefe, aquele Eclipsite... não conseguimos encontrar um único rastro de nenhum deles.",
  ui_story_5080_50800802_38_dialog_content = "Embora ninguém tenha dito em voz alta, todos presumimos que o chefe deve ter descido com aqueles monstros, e que todos morreram na lava.",
  ui_story_5080_50800802_39_dialog_content = "Até que o dragão perverso levantou sua cabeça feia mais uma vez...",
  ui_story_5080_50800802_40_dialog_content = "Agora que o Eclipsita voltou também... Talvez o antigo chefe tenha sido devorado por essas coisas naquela época.",
  ui_story_5080_50800802_41_dialog_content = "De jeito nenhum! Ela era boa demais para isso!",
  ui_story_5080_50800802_42_dialog_content = "Bem, pelo menos finalmente podemos nos vingar. Este lugar que nunca conseguimos encontrar antes - parece que havia uma rota escondida aqui o tempo todo...",
  ui_story_5080_50800802_43_dialog_content = "No passado, o vulcão roncava e rugia de vez em quando.",
  ui_story_5080_50800802_44_dialog_content = "Embora todos soubessem que eram os Eclipsitas fazendo todo aquele barulho, não importa quantos deles matamos, simplesmente não conseguíamos exterminá-los todos. Sempre parecia que devia haver alguma passagem não descoberta de onde eles estavam surgindo.",
  ui_story_5080_50800802_45_dialog_content = "Hah, bem, finalmente encontramos. Mas ainda tivemos que voltar a este maldito lugar para fazer isso.",
  ui_story_5080_50800802_46_dialog_content = "Eu... gostava bastante de segui-la quando era pequeno.",
  ui_story_5080_50800802_47_dialog_content = "Eu vi o poder dela. Não era menos do que o relato exagerado de Sinsa. Ela não deveria ter perdido para aquele dragão.",
  ui_story_5080_50800802_48_dialog_content = "E... Eu podia sentir que ela estava suportando algo que eu ainda não conseguia entender.",
  ui_story_5080_50800802_49_dialog_content = "Ela estava desesperadamente escondendo algum segredo, suprimindo uma parte de si mesma.",
  ui_story_5080_50800802_50_dialog_content = "Agora que você mencionou, sim... o chefe e eu éramos de Illumina. Eu ouvi o nome dela mais vezes do que consigo me lembrar.",
  ui_story_5080_50800802_51_dialog_content = "Mas quando eu realmente a conheci, ela era diferente do que eu havia imaginado.",
  ui_story_5080_50800802_52_dialog_content = "Mas eu sempre senti que ela estava escondendo seu verdadeiro eu. Não importa contra quem estávamos lutando, eu tinha a sensação de que ela sempre estava se contendo.",
  ui_story_5080_50800802_53_dialog_content = "Ela parecia apenas liberar o que estava dentro dela no final. Foi quando vi o lado selvagem do nosso líder ser liberado pela primeira vez.",
  ui_story_5080_50800802_54_dialog_content = "Ela era mais selvagem que Sinsa em um dia ruim.",
  ui_story_5080_50800802_55_dialog_content = "Essa é uma comparação bem estranha a se fazer.",
  ui_story_5080_50800802_56_dialog_content = "Se até uma mulher como ela pode perder para <color=#FFB400>aquele Eclipsite</color>, que chance nós temos?",
  ui_story_5080_50800802_57_dialog_content = "O Rugido do Vulcão parece que está prestes a entrar em erupção, e o Darkover pode atacar novamente. A Rediesel Wrench realmente pode resistir a tais adversidades?",
  ui_story_5080_50800802_58_dialog_content = "Você realmente precisa perguntar?",
  ui_story_5080_50800802_59_dialog_content = "Apenas traga-o!",
  ui_story_5080_50800802_60_dialog_content = "Não importa o tipo de Eclipsita que enfrentamos. Vou mandá-los para o alto com esta minha chave de confiança!",
  ui_story_5080_50800802_61_dialog_content = "Se aquele Eclipsita tiver a coragem de me enfrentar novamente, oh garoto, não vou deixá-lo escapar desta vez! De jeito nenhum!",
  ui_story_5080_50800802_62_dialog_content = "Celestita Um, Filhote Dois - prestem atenção.",
  ui_story_5080_50800802_63_dialog_content = "E aí? Por que essa rotina repentina de segredos e mistérios?",
  ui_story_5080_50800802_64_dialog_content = "Nossa missão é... capturar aquele Eclipsite vivo, se possível.",
  ui_story_5080_50800802_65_dialog_content = "Quando chegar a hora, impeça Sinsa de matá-lo.",
  ui_story_5080_50800901_1_dialog_content = "Outro novo caminho, huh? O que realmente está acontecendo aqui embaixo?",
  ui_story_5080_50800901_2_dialog_content = "Está se abrindo. Parece que chegamos ao caminho verdadeiro.",
  ui_story_5080_50800901_3_dialog_content = "O mundo sob o deserto é um lugar complexo para se navegar, mas olhando para essa estrutura... isso poderia ter sido parte da parede do Corredor Leyline?",
  ui_story_5080_50800901_4_dialog_content = "Quando o vulcão entrou em erupção, a lava queimou tudo e os Eclipsitas cavaram através desses buracos para fazer um caminho.",
  ui_story_5080_50800901_5_dialog_content = "Pela aparência dessas paredes, elas foram definitivamente escavadas, mas com ferramentas, não garras.",
  ui_story_5080_50800901_6_dialog_content = "Então, isso não é trabalho do Eclipsite?",
  ui_story_5080_50800901_7_dialog_content = "As pessoas vivem no deserto há muito tempo. Talvez isso tenha sido obra da antiga civilização que desenvolveu o Corredor Leyline.",
  ui_story_5080_50800901_8_dialog_content = "Olhe aqui... Vibrações intensas racharam a estratificação.",
  ui_story_5080_50800901_9_dialog_content = "Há pedras cortadas aqui embaixo. Este era um chão, o que significa que este lugar foi construído por alguém.",
  ui_story_5080_50800901_10_dialog_content = "O quê? Bem ao lado de uma saída vulcânica subterrânea?!",
  ui_story_5080_50800901_11_dialog_content = "Isso explica as marcas de ferramentas nas paredes - eles não estavam apenas desenvolvendo a linha ley sem motivo, eles estavam construindo algo.",
  ui_story_5080_50800901_12_dialog_content = "Ei, o que o soldado Illumina está fazendo cavando na terra em um momento como este?",
  ui_story_5080_50800901_13_dialog_content = "Espere—ela está escavando os resquícios mais profundos nas fendas desses materiais de construção, procurando por quaisquer histórias que eles possam ser capazes de contar.",
  ui_story_5080_50800901_14_dialog_content = "Esta pedra tem evidentes três pontos de indentação, e há cinzas queimadas nas fendas.",
  ui_story_5080_50800901_15_dialog_content = "Não há como negar. Alguém montou uma panela e cozinhou algo aqui há muito tempo.",
  ui_story_5080_50800901_16_dialog_content = "Daqui até onde entramos, é do tamanho de um quarto - este era um abrigo subterrâneo.",
  ui_story_5080_50800901_17_dialog_content = "Há muito tempo atrás, provavelmente não havia nenhum Eclipsita aqui, mas era muito provável um refúgio para um grupo de pessoas.",
  ui_story_5080_50800901_18_dialog_content = "Eles se esconderam aqui até que a erupção vulcânica enterrou tudo.",
  ui_story_5080_50800901_19_dialog_content = "Muito impressionante. Com apenas algumas palavras, você desenterrou as histórias antigas enterradas aqui.",
  ui_story_5080_50800901_20_dialog_content = "Nunca vi nada assim antes... Não é à toa que você se tornou capitão batedor tão jovem.",
  ui_story_5080_50800901_21_dialog_content = "Sinsa, você já ouviu falar de pessoas vivendo subterraneamente aqui?",
  ui_story_5080_50800901_22_dialog_content = "Eve e eu somos basicamente estranhos também. Não conhecemos todas essas histórias antigas.",
  ui_story_5080_50800901_23_dialog_content = "Roy e eu somos de Illumina, e embora ele certamente tenha estado por aí, provavelmente também não sabe sobre esse tipo de coisa.",
  ui_story_5080_50800901_24_dialog_content = "Por que estão me olhando? Sou muito jovem para saber sobre essas coisas. Além disso, se Sinsa não sabe sobre isso, por que eu saberia?",
  ui_story_5080_50800901_25_dialog_content = "Se costumava haver pessoas aqui, como é que você nunca ouviu falar disso?",
  ui_story_5080_50800901_26_dialog_content = "Até eu não tinha ouvido falar sobre isso! Poderia ser algum relíquia super antiga? Talvez haja algum poder épico enterrado aqui, como um gigante Lumina mega-poderoso!?",
  ui_story_5080_50800901_27_dialog_content = "Minha culpa... Eu deveria ter garantido que as crianças estudassem a história, mas ninguém parecia se importar com o passado.",
  ui_story_5080_50800901_28_dialog_content = "Você me fez organizar e enviar livros todos os meses, e eles só têm acumulado poeira.",
  ui_story_5080_50800901_29_dialog_content = "Desculpe, Jeriah.",
  ui_story_5080_50800901_30_dialog_content = "Temos peixes maiores para fritar agora!",
  ui_story_5080_50800901_31_dialog_content = "Certo! Um guerreiro lendário como eu não tem tempo para histórias antigas!",
  ui_story_5080_50800901_32_dialog_content = "Ah... Eu esperava tanto, mas ouvir todos vocês dizerem isso... Realmente não há esperança para este mundo.",
  ui_story_5080_50800901_33_dialog_content = "Todos realmente só se importam com o presente, em vez de explorar o que a terra sob seus pés e o legado de seus antecessores realmente significam.",
  ui_story_5080_50800901_34_dialog_content = "Senhorita Jeriah, você deve saber de algo, certo? Por favor, nos conte!",
  ui_story_5080_50800901_35_dialog_content = "Minha pesquisa sobre o deserto não é exatamente extensa, mas quando se trata de abrigos, uma certa lenda vem à mente.",
  ui_story_5080_50800901_36_dialog_content = "É também a história de origem da Rediesel Wrench.",
  ui_story_5080_50800901_37_dialog_content = "Não foi porque nosso antigo chefe conquistou os bandidos que a Rediesel Wrench foi formada?",
  ui_story_5080_50800901_38_dialog_content = "Há muito tempo, o deserto era lar de nômades e foras da lei, vivendo sem qualquer semelhança real de ordem.",
  ui_story_5080_50800901_39_dialog_content = "Talvez eles tivessem medo do mundo exterior, ou estivessem cansados dele, preferindo viver no ambiente áspero do deserto.",
  ui_story_5080_50800901_40_dialog_content = "Eles acreditavam que este lugar era a sua liberdade.",
  ui_story_5080_50800901_41_dialog_content = "Liberdade...",
  ui_story_5080_50800901_42_dialog_content = "Um dia, uma jovem nobre de Lumópolis, perseguida por sua família, foi levada para o deserto por sua donzela.",
  ui_story_5080_50800901_43_dialog_content = "A donzela queria levá-la para sua cidade natal, longe de todos os conflitos.",
  ui_story_5080_50800901_44_dialog_content = "O conflito de Lumópolis... Eu vejo.",
  ui_story_5080_50800901_45_dialog_content = "Um guarda da cidade foi enviado atrás deles. Ele acreditava acima de tudo na honra de um cavaleiro.",
  ui_story_5080_50800901_46_dialog_content = "Curiosamente, um soldado da Illumina também se aventurou no deserto naquela época, procurando nas aldeias por desertores da Illumina.",
  ui_story_5080_50800901_47_dialog_content = "Ele estava atrás de um engenheiro Illumina desiludido que havia perdido a vontade de servir.",
  ui_story_5080_50800901_48_dialog_content = "Um soldado Illumina desiludido...",
  ui_story_5080_50800901_49_dialog_content = "Durante a perseguição, o agente Illumina, devido a uma confusão, pensou erroneamente que o Guarda Lumo estava atrás da mesma pessoa que ele.",
  ui_story_5080_50800901_50_dialog_content = "A jovem senhora e sua donzela, ao encontrar o engenheiro, confundiram-no com um caçador de recompensas.",
  ui_story_5080_50800901_51_dialog_content = "Eles temiam um ao outro, e começaram a perseguir um ao outro, mas estavam intimamente ligados pela inconstância do destino.",
  ui_story_5080_50800901_52_dialog_content = "Com a intervenção do engenheiro, a mocinha e sua donzela conseguiram escapar do cavaleiro com sucesso.",
  ui_story_5080_50800901_53_dialog_content = "E graças ao erro do cavaleiro, o agente perdeu seu desertor, acabando por rastreá-lo apenas até a Vila Saltstone.",
  ui_story_5080_50800901_54_dialog_content = "Parece que essa lenda é toda sobre tolos.",
  ui_story_5080_50800901_55_dialog_content = "De fato, mas porque eram tolos, nunca realmente se machucaram.",
  ui_story_5080_50800901_56_dialog_content = "Todos eles se apegaram às suas crenças, claramente tendo a oportunidade de atacar, mas não querendo machucar uns aos outros.",
  ui_story_5080_50800901_57_dialog_content = "Acho que gosto de histórias assim.",
  ui_story_5080_50800901_58_dialog_content = "Na última etapa de sua jornada, eles encontraram uma rara tempestade de areia. Tudo em seu caminho foi devorado pelas areias furiosas.",
  ui_story_5080_50800901_59_dialog_content = "Justo a tempo, a caça ajudou os caçadores, e os caçadores desistiram de sua perseguição.",
  ui_story_5080_50800901_60_dialog_content = "Depois de tudo que aconteceu, as missões dos caçadores estavam muito atrasadas, e eles mesmos seriam considerados desertores.",
  ui_story_5080_50800901_61_dialog_content = "Presos no mesmo barco, o apoio mútuo finalmente levou-os a se entenderem e confiarem um no outro.",
  ui_story_5080_50800901_62_dialog_content = "Eles fizeram um pacto para chegar juntos à Vila Saltstone, para se estabelecer e viver em paz lá.",
  ui_story_5080_50800901_63_dialog_content = "Eles conseguiram o final de conto de fadas deles?",
  ui_story_5080_50800901_64_dialog_content = "Não. Quando chegaram à cidade natal da donzela, o suposto oásis da Vila de Saltstone, descobriram que ela havia sido destruída por uma erupção vulcânica.",
  ui_story_5080_50800901_65_dialog_content = "Os sobreviventes também estavam sendo alvo de bandidos e estavam presos em um inferno vivo.",
  ui_story_5080_50800901_66_dialog_content = "O oásis não existia. Eles estavam condenados a nunca encontrar a paz.",
  ui_story_5080_50800901_67_dialog_content = "Os forasteiros perderam a esperança, percebendo que este lugar não era diferente do mundo que haviam deixado para trás...",
  ui_story_5080_50800901_68_dialog_content = "...",
  ui_story_5080_50800901_69_dialog_content = "Os sobreviventes, liderados pelo oráculo da aldeia, fugiram em direção aos portões da aldeia, bem a tempo de encontrar esses estrangeiros.",
  ui_story_5080_50800901_70_dialog_content = "Aqueles que buscavam um refúgio de repente se tornaram um refúgio para os outros.",
  ui_story_5080_50800901_71_dialog_content = "Confusos, nem o cavaleiro resoluto nem o soldado intransigente podiam entender o que estava sendo pedido a eles naquele momento.",
  ui_story_5080_50800901_72_dialog_content = "Diante de uma questão de vida ou morte, ninguém esperava que o engenheiro levantasse a chave inglesa em sua mão e avançasse contra os bandidos.",
  ui_story_5080_50800901_73_dialog_content = "Seu ato corajoso inspirou os outros e, finalmente, os bandidos foram expulsos.",
  ui_story_5080_50800901_74_dialog_content = "Que história heroica! Deixe-me adivinhar - essa chave é a lendária Rediesel Wrench, estou certo?",
  ui_story_5080_50800901_75_dialog_content = "Não se precipite, a história ainda não acabou.",
  ui_story_5080_50800901_76_dialog_content = "Por causa daquele engenheiro, as pessoas encontraram esperança novamente. E assim, partiram mais uma vez, em busca de um novo oásis no deserto.",
  ui_story_5080_50800901_77_dialog_content = "Ao longo do caminho, eles gradualmente absorveram mais nômades para o grupo, tornando-se uma força formidável sem mesmo perceber.",
  ui_story_5080_50800901_78_dialog_content = "Eventualmente, eles encontraram um pequeno oásis rico em rediesel e se estabeleceram lá.",
  ui_story_5080_50800901_79_dialog_content = "Essa é a lenda que Attar... não, o líder anterior me contou.",
  ui_story_5080_50800901_80_dialog_content = "Isso prova que há muito tempo, este deserto era habitado por Aurorianos.",
  ui_story_5080_50800901_81_dialog_content = "Essas pessoas, assim como nós, estavam todas se esforçando para encontrar seu próprio modo de vida.",
  ui_story_5080_50800901_82_dialog_content = "Esses abrigos subterrâneos provavelmente eram lugares para escapar de perseguidores ou bandidos, correto?",
  ui_story_5080_50800901_83_dialog_content = "Mas se essas pessoas foram engolidas pela erupção do vulcão ou abandonadas ao descobrir o vulcão nas profundezas dos túneis... Eu não sei.",
  ui_story_5080_50800901_84_dialog_content = "Tsk, estou ficando meio ciumento aqui... Isso não é justo! Por que o antigo chefe contou tudo isso para você e não para nós?",
  ui_story_5080_50800901_85_dialog_content = "Bem, isso é apenas porque você não mostrou o menor interesse.",
  ui_story_5080_50800901_86_dialog_content = "Estava cheio de curiosidade e muito interessado em suas histórias, sempre a importunando para me contar mais.",
  ui_story_5080_50800901_87_dialog_content = "Mas, refletindo, parece que quanto mais você sabe, mais você se envolve em um sentimento de vazio - uma sensação de que o passado acabará por desaparecer...",
  ui_story_5080_50800901_88_dialog_content = "Sabe, Sinsa, você era apenas um novato naquela época, sempre ocupado cuidando da sua irmã.",
  ui_story_5080_50800901_89_dialog_content = "A vida não era só sol e arco-íris naquela época - estávamos procurando comida dia após dia.",
  ui_story_5080_50800901_90_dialog_content = "Você também teve as mãos cheias, ensinando Azure a dirigir, lembra?",
  ui_story_5080_50800901_91_dialog_content = "Apenas estar vivo já era incrível o suficiente... Eu sempre pensei que viver o agora era tudo o que importava.",
  ui_story_5080_50800901_92_dialog_content = "Naquela época, não tínhamos meios para desenterrar o passado.",
  ui_story_5080_50800901_93_dialog_content = "Mas ei, os tempos mudaram!",
  ui_story_5080_50800901_94_dialog_content = "Agora, a vida na Rediesel Wrench é só alegria e felicidade... e eu estou prestes a me tornar a chave mais afiada da caixa de ferramentas!",
  ui_story_5080_50800901_95_dialog_content = "Espere só, Sinsa. Vou estudar muito quando voltarmos e me tornarei um líder melhor que você um dia!",
  ui_story_5080_50800901_96_dialog_content = "Seu pequeno punk... Não é a nossa vida confortável toda graças ao meu sangue, suor e lágrimas?",
  ui_story_5080_50800901_97_dialog_content = "Você quer dizer que na história, aquela pessoa que levantou sua chave inglesa se tornou algum tipo de símbolo espiritual.",
  ui_story_5080_50800901_98_dialog_content = "Mas uma chave de engenheiro da Illumina não é uma arma e nunca possuiu dimensões tão exageradas.",
  ui_story_5080_50800901_99_dialog_content = "A chave inglesa nas mãos de Sinsa provavelmente pesa uma tonelada agora, certo?",
  ui_story_5080_50800901_100_dialog_content = "Isso mesmo. Além de mim, você não encontrará muitos que podem simplesmente girá-lo no ar como se não fosse nada.",
  ui_story_5080_50800901_101_dialog_content = "Que tipo de engenheiro carregaria uma chave inglesa assim?",
  ui_story_5080_50800901_102_dialog_content = "Pequeno pássaro de rapina, você está dizendo que essa história não é verdadeira?",
  ui_story_5080_50800901_103_dialog_content = "Essa lenda pode ter sido inventada pelo seu líder para embelezar o passado da Rediesel Wrench.",
  ui_story_5080_50800901_104_dialog_content = "De acordo com os registros da Illumina, este deserto sempre foi invadido por bandidos, causando problemas e incitando muitos a se tornarem desertores.",
  ui_story_5080_50800901_105_dialog_content = "Essas pessoas se autodenominavam a Gangue Rediesel e constantemente ameaçavam outros Aurorianos.",
  ui_story_5080_50800901_106_dialog_content = "Aquela pessoa... primeiro transformou minha tia em uma desertora, depois se juntou à Gangue Rediesel após fugir para cá. Mais tarde, ela se tornou a líder deles.",
  ui_story_5080_50800901_107_dialog_content = "Ela forçou os nômades a se juntarem a ela para aumentar seu poder, expandindo lentamente seu domínio sobre o deserto e transformando-o na Rediesel Wrench.",
  ui_story_5080_50800901_108_dialog_content = "Essas histórias são apenas invenções que ela criou para retratar a história da Rediesel Wrench de uma maneira positiva.",
  ui_story_5080_50800901_109_dialog_content = "Ei, seu pirralho de Illumina! Ninguém nunca te ensinou a não falar bobagens sobre alguém que as pessoas admiram?",
  ui_story_5080_50800901_110_dialog_content = "Só porque somos amigos por enquanto, não significa que você pode falar o que quiser!",
  ui_story_5080_50800901_111_dialog_content = "Espere, por que você diria isso, Capitão? Se, como você diz, ela governava o deserto, por que ela precisaria se preocupar em embelezar o passado?",
  ui_story_5080_50800901_112_dialog_content = "Não consigo imaginar o líder Sinsa e os outros acreditando em ser esse tipo de pessoa.",
  ui_story_5080_50800901_113_dialog_content = "Ela... realmente queria proteger a todos?",
  ui_story_5080_50800901_114_dialog_content = "E assim, ela queria protegê-lo da verdade.",
  ui_story_5080_50800901_115_dialog_content = "...",
  ui_story_5080_50800901_116_dialog_content = "Tsk, então você consegue entender as pessoas, hein?",
  ui_story_5080_50800901_117_dialog_content = "Espere... É outro terremoto?",
  ui_story_5080_50800901_118_dialog_content = "Não, esse é o som da horda de Eclipsitas.",
  ui_story_5080_50800901_119_dialog_content = "Olhe aqui, Senhorita Formiga Soldado da Illumina. É assim que agimos na Rediesel Wrench, este é o compromisso que todos nós fizemos para manter nossa família segura!",
  ui_story_5080_50800901_120_dialog_content = "Agora, preste atenção - estamos prestes a mostrar exatamente como é a nossa marca de coragem!",
  ui_story_5080_50801000_1_dialog_content = "Olhe todas essas queimaduras... Você se empolgou demais.",
  ui_story_5080_50801000_2_dialog_content = "Heh, um arranhão aqui e ali... Já vi pior!",
  ui_story_5080_50801000_3_dialog_content = "Ei, Roy, já é hora do rango? A galera deve estar morrendo de fome!",
  ui_story_5080_50801000_4_dialog_content = "O que tem no cardápio?",
  ui_story_5080_50801000_5_dialog_content = "Isso mesmo—hora do jantar, hora do jantar! Crianças, preparem a panela!",
  ui_story_5080_50801000_6_dialog_content = "Vamos nessa, Dawn! Hora de pegar algumas iguarias vulcânicas para nós!",
  ui_story_5080_50801000_7_dialog_content = "O que está fazendo?",
  ui_story_5080_50801000_8_dialog_content = "Trabalhe duro, divirta-se muito, pequena senhora Illumina.",
  ui_story_5080_50801000_9_dialog_content = "Não fique tão chocado. Eles são sempre assim. Eles nunca relaxam quando se trata de comida.",
  ui_story_5080_50801000_10_dialog_content = "Se você não é fã da culinária exótica deles, nós também trouxemos alguma comida.",
  ui_story_5080_50801000_11_dialog_content = "Mas, estamos em uma missão agora mesmo!",
  ui_story_5080_50801000_12_dialog_content = "Como você pode simplesmente comer assim...? E se formos emboscados?",
  ui_story_5080_50801000_13_dialog_content = "Filhote Dois, Celestita Um, Lança Branca - continuem sua missão.",
  ui_story_5080_50801000_14_dialog_content = "Sim, Capitão!",
  ui_story_5080_50801000_15_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5080_50801000_16_dialog_content = "Ops... Me desculpe... Eu pulei o café da manhã hoje...",
  ui_story_5080_50801000_17_dialog_content = "...",
  ui_story_5080_50801000_18_dialog_content = "Capitão, um experiente soldado de Illumina costumava nos dizer: \"Comam! Uma barriga cheia te dá força para lutar até a próxima refeição!\"",
  ui_story_5080_50801000_19_dialog_content = "Ele jurou por essa regra, e todos concordaram.",
  ui_story_5080_50801000_20_dialog_content = "Zeta e Vice têm estado ocupados lutando e viajando desde que se levantaram...",
  ui_story_5080_50801000_21_dialog_content = "Aqueles velhos soldados de Illumina sabem tudo sobre lutar de estômago vazio.",
  ui_story_5080_50801000_22_dialog_content = "Ainda assim, eles perseveraram.",
  ui_story_5080_50801000_23_dialog_content = "É por isso que eles esperam que a geração mais jovem possa comer melhor do que eles.",
  ui_story_5080_50801000_24_dialog_content = "Suponho que não podemos prosseguir sem repor nossas energias. Para garantir que a missão seja concluída, vou conceder-lhe tempo para comer.",
  ui_story_5080_50801000_25_dialog_content = "Eu ficarei de guarda. Nem todos podem se dar ao luxo de relaxar...",
  ui_story_5080_50801000_26_dialog_content = "Capitão, pelo menos coma algumas dessas rações comprimidas! Capitão...!",
  ui_story_5080_50801000_27_dialog_content = "Deixe-a em paz, ela só quer garantir que essa missão seja executada perfeitamente.",
  ui_story_5080_50801000_28_dialog_content = "Estamos de volta—Ei, você começou sem nós!",
  ui_story_5080_50801000_29_dialog_content = "Heróis são todos sobre eficiência! Estou de saída para ficar de guarda!",
  ui_story_5080_50801000_30_dialog_content = "... A velocidade com que você come é louvável. Com treinamento, você poderia se tornar um excelente soldado.",
  ui_story_5080_50801000_31_dialog_content = "Eu não quero ser um soldado Illumina. Estou destinado a salvar o mundo!",
  ui_story_5080_50801000_32_dialog_content = "Experimente! Este inseto assado é delicioso! Eu trouxe especialmente para você.",
  ui_story_5080_50801000_33_dialog_content = "Obrigado... Garota Pirulito.",
  ui_story_5080_50801000_34_dialog_content = "Eu sou o Salvador do Mundo, não algum personagem secundário!",
  ui_story_5080_50801000_35_dialog_content = "Você é legal e tudo mais, mas seu gosto precisa de trabalho! Deve ser porque você foi criado pelo Rei Demônio, hein?",
  ui_story_5080_50801000_36_dialog_content = "Que azar, Salvador do Mundo, Irmã Arqui-inimiga há muito perdida!",
  ui_story_5080_50801000_37_dialog_content = "Irmã?",
  ui_story_5080_50801000_38_dialog_content = "Sim! Somos Irmãs Guerreiras agora! Não se preocupe, vou encontrar uma maneira de libertá-la dessas correntes mentais suas!",
  ui_story_5080_50801000_39_dialog_content = "Hã? Você está sorrindo? Essa é a primeira vez que vejo você sorrir... Deve ser o poder da família, certo?!",
  ui_story_5080_50801000_40_dialog_content = "Não se importe com ela; ela só gosta de brincar de faz de conta, inventar histórias e assim por diante.",
  ui_story_5080_50801000_41_dialog_content = "Irmãs... Hmm...",
  ui_story_5080_50801000_42_dialog_content = "Parece que você se lembrou de algo. Por acaso, você tem uma irmã?",
  ui_story_5080_50801000_43_dialog_content = "Sim... ela é muito inteligente, mais forte do que eu, e... simplesmente adorável.",
  ui_story_5080_50801000_44_dialog_content = "Assim que ela terminar os estudos, se tornará uma soldata exemplar.",
  ui_story_5080_50801000_45_dialog_content = "Tenho orgulho dela.",
  ui_story_5080_50801000_46_dialog_content = "O que...? Ai...",
  ui_story_5080_50801000_47_dialog_content = "Zeta, você parece não convencido.",
  ui_story_5080_50801000_48_dialog_content = "Ela está me deixando com ciúmes... Quer dizer! Não com ciúmes! Apenas...",
  ui_story_5080_50801000_49_dialog_content = "Ter uma irmã como você, sua irmãzinha deve ser muito feliz.",
  ui_story_5080_50801000_50_dialog_content = "'Porque Eagleshot é muito mais legal do que aquela bruxa.",
  ui_story_5080_50801000_51_dialog_content = "Não, ainda estou longe de ser bom o suficiente.",
  ui_story_5080_50801000_52_dialog_content = "Vou continuar tentando... tentando... não causar mais problemas para minha família.",
  ui_story_5080_50801000_53_dialog_content = "Oh, la, la, la!",
  ui_story_5080_50801000_54_dialog_content = "O que é essa serenata repentina? Eu nem consigo ouvir meus próprios pensamentos!",
  ui_story_5080_50801000_55_dialog_content = "Você não ouviu? Barbara disse a ele que ele tem mais potencial do que você, então ele tem treinado como um louco ultimamente.",
  ui_story_5080_50801000_56_dialog_content = "O quê?!",
  ui_story_5080_50801000_57_dialog_content = "\"O Primeiro Tenor da Rediesel, mais emocionante que Sinsa\"—palavras de Barbara.",
  ui_story_5080_50801000_58_dialog_content = "Então ele está treinando como um louco, se preparando para encantar a todos com seu estilo vocal.",
  ui_story_5080_50801000_59_dialog_content = "Uau, então acho que também tenho que praticar. Eu prometi a eles que entraria na banda.",
  ui_story_5080_50801000_60_dialog_content = "Onde estão aquelas baquetas... Não é isso... nem isso, também... Bingo!",
  ui_story_5080_50801000_61_dialog_content = "Tudo bem, estou aqui para manter a batida. Vamos lá!",
  ui_story_5080_50801000_62_dialog_content = "Essas pessoas...",
  ui_story_5080_50801000_63_dialog_content = "Aumente o volume, Fleur! Coloque seu coração e alma nessas baquetas!",
  ui_story_5080_50801000_64_dialog_content = "Você está em harmonia comigo? Já conseguiu acompanhar minha voz?",
  ui_story_5080_50801000_65_dialog_content = "A menos que você abaixe o tom, até os Eclipsitas vão conseguir acompanhar sua voz.",
  ui_story_5080_50801000_66_dialog_content = "Não bata nas paredes, Fleur! Cuidado para não alertar os Eclipsitas!",
  ui_story_5080_50801000_67_dialog_content = "É uma coisa boa que Sinsa tenha algum bom senso, Rediesel Wrench...",
  ui_story_5080_50801000_68_dialog_content = "Pegue a chave inglesa. Se você quer praticar, comece a bater com isso! Vá em frente, arrase!",
  ui_story_5080_50801000_69_dialog_content = "Você não tem medo de atrair os Eclipsitas?",
  ui_story_5080_50801000_70_dialog_content = "Isso não é realmente um grande problema, é? Estamos ansiosos para encontrá-los de qualquer maneira. Aumente o tom, mais alto! Mais alto!",
  ui_story_5080_50801000_71_dialog_content = "Ah... Verdadeiramente incorrigível.",
  ui_story_5080_50801000_72_dialog_content = "Vivendo neste vasto deserto, eles nunca desenvolveram um espírito de investigação. Tudo o que fazem é brincar todos os dias...",
  ui_story_5080_50801000_73_dialog_content = "Mas Jeriah, o que é exatamente o espírito de investigação?",
  ui_story_5080_50801000_74_dialog_content = "Pequeno celestita, você também está começando a ter suas dúvidas?",
  ui_story_5080_50801000_75_dialog_content = "Não, eu só acho que... mesmo vivendo em um ambiente tão severo, você nunca ouve Sinsa e os outros reclamando.",
  ui_story_5080_50801000_76_dialog_content = "Eles estão sempre tentando encontrar a alegria na vida, e parecem ser bastante bons nisso.",
  ui_story_5080_50801000_77_dialog_content = "Sempre tenho a sensação de que eles já estão cheios do espírito de investigação, quando se trata de explorar suas próprias vidas.",
  ui_story_5080_50801000_78_dialog_content = "Sim, Senhorita Jeriah. Você sabe tanto, mas parece que você é um pouco negativa demais sobre a vida em geral...",
  ui_story_5080_50801000_79_dialog_content = "Sem ofensa, claro, mas... é realmente assim que você quer ser?",
  ui_story_5080_50801000_80_dialog_content = "Vindo de um soldado da Illumina como Vice, não tenho certeza de como responder.",
  ui_story_5080_50801000_81_dialog_content = "Talvez você acredite que as pessoas de Illumina não têm o direito de dar lições sobre vida e liberdade aos outros.",
  ui_story_5080_50801000_82_dialog_content = "Mas eu cresci lá, e sei muito bem - o propósito de Illumina é servir como um escudo, para proteger todos aqueles que estão atrás de nós.",
  ui_story_5080_50801000_83_dialog_content = "Podemos ter que fazer sacrifícios, mas sei que as pessoas atrás desse escudo podem viver felizes.",
  ui_story_5080_50801000_84_dialog_content = "Os sorrisos em seus rostos são o que eu me esforço para proteger.",
  ui_story_5080_50801000_85_dialog_content = "Estou feliz em vê-los fazendo tudo o que podem para viver suas vidas. Vê-los tão livres já é bom o suficiente para mim.",
  ui_story_5080_50801000_86_dialog_content = "O significado de... proteção...?!",
  ui_story_5080_50801000_87_dialog_content = "Então, todos vocês têm visões diferentes sobre a vida.",
  ui_story_5080_50801000_88_dialog_content = "Viver para os outros? Na minha visão, não é exatamente o que eu chamaria de ser totalmente livre, mas ainda é admirável.",
  ui_story_5080_50801000_89_dialog_content = "Hmm, como devo entender isso? Você deveria explorar a vida em seus próprios termos, mas está tão intimamente conectado aos outros...",
  ui_story_5080_50801000_90_dialog_content = "Ainda acredito que os laços que existem entre as pessoas não podem ser cortados.",
  ui_story_5080_50801000_91_dialog_content = "Mesmo você, Jeriah, não pode apagar os laços que formou conosco... mesmo que não queira se tornar um tolo despreocupado.",
  ui_story_5080_50801000_92_dialog_content = "... Certo, a casa agora é uma tela de rabiscos, uma montanha de presentes e livros para as crianças.",
  ui_story_5080_50801000_93_dialog_content = "Não importa o quão sorrateira eu tente ser, essas crianças ainda conseguem me pegar, e até mesmo levaram meu carro para dar uma volta.",
  ui_story_5080_50801000_94_dialog_content = "Eles deram uma boa amassada, mas eu consertei direitinho!",
  ui_story_5080_50801000_95_dialog_content = "Algumas manchas bastante únicas também.",
  ui_story_5080_50801000_96_dialog_content = "Depois de tudo isso, Jeriah, você ainda acha que está completamente sozinho?",
  ui_story_5080_50801000_97_dialog_content = "O que é isso, pequeno celestita? Você está realmente tão preocupado com minhas conexões sociais? Você está tão preocupado comigo?",
  ui_story_5080_50801000_98_dialog_content = "Mesmo que eu tente me misturar com essas pessoas, isso não diminuirá minha vontade de viajar.",
  ui_story_5080_50801000_99_dialog_content = "Tudo bem, essa é a batida!",
  ui_story_5080_50801000_100_dialog_content = "Eu posso sentir seu fogo, sinto sua vibração - agora vamos realmente soltar a voz!",
  ui_story_5080_50801000_101_dialog_content = "<color=#e8d9bb>Sob o comando de Sinsa, a Rediesel Wrench canta sua música como loucos.</color>",
  ui_story_5080_50801000_102_dialog_content = "<color=#e8d9bb>É um coro totalmente discordante, mas todos dão o seu melhor, nunca pensando em parar - é a sua própria harmonia especial.</color>",
  ui_story_5080_50801000_103_dialog_content = "As personalidades deles são simplesmente muito distintas e proeminentes, não do tipo que se misturam.",
  ui_story_5080_50801000_104_dialog_content = "No entanto, este grupo diversificado de personagens únicos se tornou uma família.",
  ui_story_5080_50801000_105_dialog_content = "Continue cantando, apenas observe a panela de sopa.",
  ui_story_5080_50801000_106_dialog_content = "Ah, Jeriah, eu vi uma coisa incrível que eles têm lá chamada hot pot quando eu estava em Longzhou.",
  ui_story_5080_50801000_107_dialog_content = "Você prepara um caldo picante, joga nele a comida que quiser e só pesca quando quiser comer.",
  ui_story_5080_50801000_108_dialog_content = "Não importa o que você coloque naquela panela quente apimentada, os sabores não se misturam.",
  ui_story_5080_50801000_109_dialog_content = "Todos que vivem no deserto agora são meio que como uma panela quente.",
  ui_story_5080_50801000_110_dialog_content = "Rediesel é inacreditável. O deserto é tão vasto, com espaço suficiente para todos se esticarem e explorarem a jornada de suas vidas...",
  ui_story_5080_50801000_111_dialog_content = "Panela quente... você disse?",
  ui_story_5080_50801000_112_dialog_content = "Jeriah, escute—você ouve isso? Esse falcão está cantando.",
  ui_story_5080_50801000_113_dialog_content = "É apenas um grito de pássaro, nada mais.",
  ui_story_5080_50801000_114_dialog_content = "Hahaha... Jeriah, como você sabe que ele não está cantando uma música para sua própria jornada?",
  ui_story_5080_50801000_115_dialog_content = "... Por que você me contou essa lenda?",
  ui_story_5080_50801000_116_dialog_content = "Não é incrível? Estranhos nascidos em Rediesel, Lumópolis e Illumina eventualmente se tornam uma grande família, apesar das diferenças de todos.",
  ui_story_5080_50801000_117_dialog_content = "Embora vivam neste mundo de calamidades infinitas, as almas solitárias ainda estão dispostas a compartilhar suas emoções.",
  ui_story_5080_50801000_118_dialog_content = "Alguns estão dispostos a levantar uma chave para proteger os outros e se tornarem líderes. Outros estão dispostos a seguir essas pessoas e trabalhar juntos.",
  ui_story_5080_50801000_119_dialog_content = "O deserto se tornou nossa casa.",
  ui_story_5080_50801000_120_dialog_content = "Apenas passando pelo céu em sua jornada, eles se reúnem em bandos, encontrando seu próprio oásis.",
  ui_story_5080_50801000_121_dialog_content = "Jeriah, esforce-se para explorar a amplitude de sua própria vida, voe alto e cante com todo o seu coração!",
  ui_story_5080_50801000_122_dialog_content = "Como você pode continuar vagando para sempre? Já existe um lugar para você aqui—",
  ui_story_5080_50801101_1_dialog_content = "<color=#e8d9bb>O som da guitarra, queimando como o sol, atravessa o calor do deserto, acalmando o solo trêmulo.</color>",
  ui_story_5080_50801101_2_dialog_content = "Avante, avante! Meu espírito nunca morrerá!",
  ui_story_5080_50801101_3_dialog_content = "Está um forno aqui fora, e ela ainda está praticando novas melodias. Bom para ela.",
  ui_story_5080_50801101_4_dialog_content = "Não vou ser superado! Tiny One, é a nossa vez!",
  ui_story_5080_50801101_5_dialog_content = "O palco está pronto. Tenho coisas para fazer, você pode continuar.",
  ui_story_5080_50801101_6_dialog_content = "Olá? Aqui é a Rediesel Wrench...",
  ui_story_5080_50801101_7_dialog_content = "Bopper, Jona está me apressando para voltar. O que está acontecendo?",
  ui_story_5080_50801101_8_dialog_content = "Cuidado! A ídola sempre brilhante está aqui! A Gracinha Diesel, Barbara!",
  ui_story_5080_50801101_9_dialog_content = "Olá? Aqui é a Rediesel Wrench... Azure, é você?",
  ui_story_5080_50801101_10_dialog_content = "Uau, está zumbindo por lá.",
  ui_story_5080_50801101_11_dialog_content = "O sol feroz está ardendo! O sol feroz continua a rugir!!!",
  ui_story_5080_50801101_12_dialog_content = "Olá? Aqui é a Rediesel Wrench...",
  ui_story_5080_50801101_13_dialog_content = "Olá? Não consigo ouvir nada. Esquece, vou apenas esperar a irmã voltar.",
  ui_story_5080_50801101_14_dialog_content = "Ei, Maggie, você armou corretamente essas minas terrestres?",
  ui_story_5080_50801101_15_dialog_content = "Está tão quente... Entendi, entendi, vou fazer isso agora!",
  ui_story_5080_50801101_16_dialog_content = "Vamos cobrir todo o perímetro do acampamento antes do pôr do sol!",
  ui_story_5080_50801101_17_dialog_content = "Realmente precisamos de todas essas armadilhas?",
  ui_story_5080_50801101_18_dialog_content = "<color=#e8d9bb>Os tremores do deserto continuam. O vulcão distante ruge, liberando sua fúria.</color>",
  ui_story_5080_50801101_19_dialog_content = "Os líderes se foram há muito tempo...",
  ui_story_5080_50801101_20_dialog_content = "Sem resposta às comunicações.",
  ui_story_5080_50801101_21_dialog_content = "Tiny One, Fleur está fora agora, venha me ajudar a consertar o caminhão.",
  ui_story_5080_50801101_22_dialog_content = "Hmph, isso é um desafio? Você ainda não vai admitir que eu sou melhor?",
  ui_story_5080_50801101_23_dialog_content = "Do que você está falando!?",
  ui_story_5080_50801101_24_dialog_content = "Devemos partir a bordo do Lepidoz?",
  ui_story_5080_50801101_25_dialog_content = "Ei, Bopper, era o Azure na linha?",
  ui_story_5080_50801101_26_dialog_content = "Não sei mesmo.",
  ui_story_5080_50801101_27_dialog_content = "Como você pode não saber se atendeu a chamada?",
  ui_story_5080_50801101_28_dialog_content = "Volte para a patrulha, e mais tarde...",
  ui_story_5080_50801101_29_dialog_content = "Esqueça, tem que ser o Azure. Quem mais poderia ser?",
  ui_story_5080_50801101_30_dialog_content = "Não posso perder essa chance rara. Afinal, tenho que levá-la para beber depois de tudo isso.",
  ui_story_5080_50801101_31_dialog_content = "... Ouça-me.",
  ui_story_5080_50801101_32_dialog_content = "Estamos aqui, bem ao lado da boca do vulcão.",
  ui_story_5080_50801101_33_dialog_content = "Tudo o que temos que fazer é pular aqui, e estaremos dentro do vulcão—",
  ui_story_5080_50801101_34_dialog_content = "O nível de atividade deste vulcão... Eagle Hunter One, ative o modo de detecção!",
  ui_story_5080_50801101_35_dialog_content = "... Como esperado, este vulcão é extremamente ativo.",
  ui_story_5080_50801101_36_dialog_content = "Por que ainda não entrou em erupção?",
  ui_story_5080_50801101_37_dialog_content = "Isso não é um vulcão adormecido despertando. Sempre foi tão ativo.",
  ui_story_5080_50801101_38_dialog_content = "Não entrou em erupção todos esses anos.",
  ui_story_5080_50801101_39_dialog_content = "Estranho...",
  ui_story_5080_50801101_40_dialog_content = "Uau, isso é real? Eclipsitas estão saindo da boca do vulcão!",
  ui_story_5080_50801101_41_dialog_content = "Esses Eclipsitas... a energia de lava deles deve estar vindo daqui.",
  ui_story_5080_50801101_42_dialog_content = "Hora de ir! Pule!",
  ui_story_5080_50801101_43_dialog_content = "Vice... Carleen... Espere por mim! É tão alto!",
  ui_story_5080_50801102_1_dialog_content = "Eclipsitas contam como criaturas vivas, certo?",
  ui_story_5080_50801102_2_dialog_content = "Como eles são capazes de viver na boca deste vulcão, não apenas utilizando a energia da lava, mas também completamente sem medo dela?",
  ui_story_5080_50801102_3_dialog_content = "Fleur, faça os cálculos para nós, não vai? Como vamos explodir a boca deste vulcão bem alto?",
  ui_story_5080_50801102_4_dialog_content = "Se os Eclipsitas não têm medo da lava, essa pode ser a única maneira de impedi-los de voltar.",
  ui_story_5080_50801102_5_dialog_content = "Isso não vai funcionar. Aquela senhora está certa, este é um vulcão ativo. Qualquer explosão imprudente pode desencadear uma erupção.",
  ui_story_5080_50801102_6_dialog_content = "Os tremores não vão parar. Os Eclipsitas vão continuar saindo das profundezas do vulcão...",
  ui_story_5080_50801102_7_dialog_content = "Não sabemos o que está acontecendo lá fora, então precisamos fazer isso rápido.",
  ui_story_5080_50801102_8_dialog_content = "Por que este vulcão tem sido tão ativo e, ao mesmo tempo, aparentemente adormecido por tanto tempo?",
  ui_story_5080_50801102_9_dialog_content = "Qual poderia ser o motivo?",
  ui_story_5080_50801102_10_dialog_content = "A fúria do vulcão provavelmente se deve à instabilidade da energia da linha ley.",
  ui_story_5080_50801102_11_dialog_content = "Se conseguirmos encontrar a causa, talvez possamos resolver essa crise.",
  ui_story_5080_50801102_12_dialog_content = "Não importa o que aconteça, temos que nos mover rápido.",
  ui_story_5080_50801102_13_dialog_content = "Se esse tremor continuar, até mesmo os Eclipsitas serão assustados para a superfície.",
  ui_story_5080_50801102_14_dialog_content = "Os Rediesels podem ser durões, mas e os moradores da vila?",
  ui_story_5080_50801102_15_dialog_content = "Muito verdade. Alguma opinião, Sinsa?",
  ui_story_5080_50801102_16_dialog_content = "Não tem outra opção. Se esses caras estão vindo de dentro, vou ter que entrar.",
  ui_story_5080_50801102_17_dialog_content = "<size=45>O quê?!</size>",
  ui_story_5080_50801102_18_dialog_content = "Você está se sentindo bem? Estamos falando de um vulcão, Sinsa.",
  ui_story_5080_50801102_19_dialog_content = "Estou me sentindo bem como a chuva, muito obrigado. É por isso que não posso simplesmente ignorar essa coisa.",
  ui_story_5080_50801102_20_dialog_content = "Estou cansado do seu resmungo. Seja por rancores antigos ou novos, vou acertar as contas de uma vez por todas.",
  ui_story_5080_50801102_21_dialog_content = "Por que... você está se esforçando tanto?",
  ui_story_5080_50801102_22_dialog_content = "Hah! Engraçado ouvir isso de você.",
  ui_story_5080_50801102_23_dialog_content = "Afinal, a Rediesel Wrench é conhecida como desertores, e você vem de um contexto semelhante.",
  ui_story_5080_50801102_24_dialog_content = "Vocês todos sobreviveram até agora saqueando os outros, não é? Apenas seguindo o fluxo, vivendo dia após dia.",
  ui_story_5080_50801102_25_dialog_content = "Por que você arriscaria sua vida agora?",
  ui_story_5080_50801102_26_dialog_content = "Tudo bem, agora é a minha vez de interrogar você. O que você estava fazendo em Illumina? Por que viajar até este vulcão?",
  ui_story_5080_50801102_27_dialog_content = "Eu sou o capitão do Esquadrão Eagleeye! Lidero minha equipe em mais de quarenta operações especiais de alto risco.",
  ui_story_5080_50801102_28_dialog_content = "Sem mim, os outros teriam enfrentado um perigo ainda maior.",
  ui_story_5080_50801102_29_dialog_content = "Eu vim pela glória. Não sou nada como vocês.",
  ui_story_5080_50801102_30_dialog_content = "Sabe, Fleur e aquele outro velhote nasceram ambos na cidade de Gannon.",
  ui_story_5080_50801102_31_dialog_content = "Eles não obtiveram nenhuma glória lá - em vez disso, tiveram que fugir para o deserto porque sentiam que estavam sufocando.",
  ui_story_5080_50801102_32_dialog_content = "Afinal, o que é glória?",
  ui_story_5080_50801102_33_dialog_content = "A glória é—",
  ui_story_5080_50801102_34_dialog_content = "Senhorita Illumina, me ilumine - você realmente compreende o significado de \"sacrifício\"?",
  ui_story_5080_50801102_35_dialog_content = "Pela Illumina, pela libertação de todos os Aurorianos, não importa o custo!",
  ui_story_5080_50801102_36_dialog_content = "Estou pronto para sacrificar tudo por essa grande causa!",
  ui_story_5080_50801102_37_dialog_content = "...",
  ui_story_5080_50801102_38_dialog_content = "Por que você está olhando assim para mim?",
  ui_story_5080_50801102_39_dialog_content = "É assim que você se convence?",
  ui_story_5080_50801102_40_dialog_content = "Deixa para lá. É inútil falar com você sobre isso agora.",
  ui_story_5080_50801102_41_dialog_content = "Roy, ela ainda está vivendo em um mundo de sonhos.",
  ui_story_5080_50801102_42_dialog_content = "Você...",
  ui_story_5080_50801102_43_dialog_content = "Com licença, eu preciso limpar um monte de insetos infestando minha casa. Fique fora do meu caminho.",
  ui_story_5080_50801102_44_dialog_content = "Ei, Sinsa, quem disse que você poderia limpar sozinho? Não se esqueça de nós!",
  ui_story_5080_50801102_45_dialog_content = "Pessoal, não se aglomerem todos. É perigoso.",
  ui_story_5080_50801102_46_dialog_content = "Você é quem fala, idiota!",
  ui_story_5080_50801102_47_dialog_content = "Pular em um vulcão juntos? Isso parece uma escolha imprudente.",
  ui_story_5080_50801102_48_dialog_content = "Prontos, pessoal... Nossa!",
  ui_story_5080_50801102_49_dialog_content = "É um terremoto! Seja cuidadoso!",
  ui_story_5080_50801102_50_dialog_content = "<color=#e8d9bb>Do nada, um terremoto atinge, e aqueles de nós que estão perto da borda do vulcão caem dentro dele.</color>",
  ui_story_5080_50801102_51_dialog_content = "Sinsa!",
  ui_story_5080_50801102_52_dialog_content = "Eve! Todos! Estou chegando!",
  ui_story_5080_50801102_53_dialog_content = "Nem pense em tirar mais alguém de mim!",
  ui_story_5080_50801102_54_dialog_content = "<color=#e8d9bb>Sinsa desce como uma bola de canhão, usando sua força monstruosa para lançar todos em segurança.</color>",
  ui_story_5080_50801102_55_dialog_content = "<color=#e8d9bb>Enquanto eu o observo se aproximar, ficando cada vez mais perto - eu não sei por quê, mas de repente me sinto à vontade.</color>",
  ui_story_5080_50801102_56_dialog_content = "Segura a minha mão, PlayerName!",
  ui_story_5080_50801102_57_dialog_content = "Espere, Sinsa, isso é lava derretida abaixo de nós! O que você está fazendo!?",
  ui_story_5080_50801102_58_dialog_content = "Quem se importa! Apenas me leve até lá!",
  ui_story_5080_50801102_59_dialog_content = "Não se atreva a pensar em morrer em mim, criança!",
  ui_story_5080_50801102_60_dialog_content = "<size=50>Sinsa!!!</size>",
  ui_story_5080_50801201_1_dialog_content = "Missão cumprida! As contribuições de Eagleeye foram significativas!",
  ui_story_5080_50801201_2_dialog_content = "Obrigado pelo seu árduo trabalho, Rachel. A Illumina lembrará do seu sacrifício.",
  ui_story_5080_50801201_3_dialog_content = "Avance, soldado. O Grande Marechal agora irá pessoalmente lhe conceder a Medalha de Honra!",
  ui_story_5080_50801201_4_dialog_content = "Em relação à operação de resgate, fizemos tudo o que pudemos... Desculpe, Rachel, é tudo que tenho para você. Obrigado pelos seus esforços.",
  ui_story_5080_50801201_5_dialog_content = "Aaai...!",
  ui_story_5080_50801201_6_dialog_content = "Que pesado...",
  ui_story_5080_50801201_7_dialog_content = "Uhh?",
  ui_story_5080_50801201_8_dialog_content = "Eles estão bem aqui... nas minhas mãos... tão pesados...",
  ui_story_5080_50801201_9_dialog_content = "Por minha causa... todos os meus colegas de equipe... todos se sacrificaram...",
  ui_story_5080_50801201_10_dialog_content = "Alguém venha aqui! Ela está prestes a desmaiar!",
  ui_story_5080_50801201_11_dialog_content = "Meu peito dói... Não estou ferido, mas a dor não para... Tia...",
  ui_story_5080_50801201_12_dialog_content = "Obrigado, Capitão... Obrigado por dar tudo de si para completar a missão.",
  ui_story_5080_50801201_13_dialog_content = "Agora, nossas crianças não serão mais lembradas como \"fracassos\".",
  ui_story_5080_50801201_14_dialog_content = "Eles finalmente podem descansar como heróis.",
  ui_story_5080_50801201_15_dialog_content = "Não...",
  ui_story_5080_50801201_16_dialog_content = "Estou tão triste, Tia... Completei a missão, mas... dói tanto...",
  ui_story_5080_50801201_17_dialog_content = "Rachel, meu bem, não chore... não chore...",
  ui_story_5080_50801201_18_dialog_content = "É tudo culpa minha. Por que todos os adultos estão me agradecendo quando foi tudo por causa do meu erro...?",
  ui_story_5080_50801201_19_dialog_content = "Você salvou o último resquício de dignidade deles.",
  ui_story_5080_50801201_20_dialog_content = "Mas eles deveriam ter voltado em segurança e estar com seus pais.",
  ui_story_5080_50801201_21_dialog_content = "Rachel, olhe para mim. Você realmente seria capaz de suportar essa responsabilidade? Transformar todos em desertores apenas para levá-los para casa em segurança?",
  ui_story_5080_50801201_22_dialog_content = "Eu... eu não sei... eu não sei...",
  ui_story_5080_50801201_23_dialog_content = "O que está acontecendo, Rachel? Esta é a sua sexta missão fracassada.",
  ui_story_5080_50801201_24_dialog_content = "Você já descansou o suficiente, então por que isso está acontecendo de novo?",
  ui_story_5080_50801201_25_dialog_content = "Desculpe, é tudo minha culpa. Por favor, não culpe os outros.",
  ui_story_5080_50801201_26_dialog_content = "Os outros todos reclamaram de você. Você nem consegue se lembrar dos nomes ou rostos deles... O que aconteceu?",
  ui_story_5080_50801201_27_dialog_content = "Eu... sinto muito... sinto muito...",
  ui_story_5080_50801201_28_dialog_content = "Você deve fazer uma pausa nas missões por enquanto. Vou arranjar um tempo de folga para você.",
  ui_story_5080_50801201_29_dialog_content = "Sinto muito mesmo... Comandante...",
  ui_story_5080_50801201_30_dialog_content = "Asa Cinza... Seu nome era Louis. Ele nasceu no Norte e sempre sonhou em explorar o deserto.",
  ui_story_5080_50801201_31_dialog_content = "Ele uma vez disse que queria esculpir uma flauta de um galho das árvores brancas de Northland para dar de presente para o Ganso Branco.",
  ui_story_5080_50801201_32_dialog_content = "Ganso Branco... Seu nome era Merry. Ela sempre falava sobre aprender a tocar um instrumento, mas nunca realmente chegou a fazê-lo.",
  ui_story_5080_50801201_33_dialog_content = "Ela prometeu tocar para mim no meu aniversário, mas continuou adiando, ano após ano.",
  ui_story_5080_50801201_34_dialog_content = "E então temos o Peneireiro Vermelho e a Coruja Verde...",
  ui_story_5080_50801201_35_dialog_content = "Eles agora se tornaram este colar, pendurado em meu pescoço para sempre.",
  ui_story_5080_50801201_36_dialog_content = "\"Você realmente seria capaz de suportar essa responsabilidade? Transformar todos em desertores apenas para levá-los em segurança para casa?\"",
  ui_story_5080_50801201_37_dialog_content = "PlayerName!",
  ui_story_5080_50801201_38_dialog_content = "...!",
  ui_story_5080_50801201_39_dialog_content = "Vice, estou aqui! Capitão, Fleur, Zeta, estão todos bem?",
  ui_story_5080_50801201_40_dialog_content = "Eu tô bem.",
  ui_story_5080_50801201_41_dialog_content = "Ótimo, PlayerName também está seguro.",
  ui_story_5080_50801201_42_dialog_content = "Parece que a boca do vulcão desmoronou. Onde estão os outros?",
  ui_story_5080_50801201_43_dialog_content = "Parece que não estamos no mesmo nível... Heh, isso é como uma configuração clássica antes do chefe final no castelo do Rei Demônio!",
  ui_story_5080_50801201_44_dialog_content = "O líder da Rediesel... Para pensar que ele realmente pulou na lava por nós...",
  ui_story_5080_50801201_45_dialog_content = "Vamos descer. Precisamos encontrar Sinsa.",
  ui_story_5080_50801201_46_dialog_content = "Está tudo cheio de lava aqui... Nossa única opção é navegar ao redor dessas áreas.",
  ui_story_5080_50801201_47_dialog_content = "A missão vem em primeiro lugar. Devemos evitar zonas de perigo desnecessárias.",
  ui_story_5080_50801201_48_dialog_content = "Sinsa nos salvou... então eu tenho que encontrá-los. Siga-me, eu deveria ser capaz de senti-los.",
  ui_story_5080_50801201_49_dialog_content = "Último celestita, suas falas são sempre tão legais! Pare de roubar meu brilho! Eu também vou!",
  ui_story_5080_50801201_50_dialog_content = "Capitão, eu também quero ajudar no resgate.",
  ui_story_5080_50801201_51_dialog_content = "... Seu braço está machucado. Isso aconteceu quando caímos?",
  ui_story_5080_50801201_52_dialog_content = "Ahn? Ah... está sangrando.",
  ui_story_5080_50801201_53_dialog_content = "Pegue isso e enfaixe-se. Você não está apto para o serviço de linha de frente. Fique atrás de mim quando formos.",
  ui_story_5080_50801201_54_dialog_content = "Vai?",
  ui_story_5080_50801201_55_dialog_content = "Lá embaixo. O alvo pode estar abaixo de nós.",
  ui_story_5080_50801201_56_dialog_content = "Sim, senhora!",
  ui_story_5080_50801201_57_dialog_content = "Esse lugar está infestado de Eclipsitas... Como eles conseguem viver em um vulcão ativo?",
  ui_story_5080_50801201_58_dialog_content = "Os Eclipsitas também são criaturas vivas. Certamente eles deveriam evitar áreas tão perigosas.",
  ui_story_5080_50801201_59_dialog_content = "Isso não é nada como o que eu aprendi na academia.",
  ui_story_5080_50801201_60_dialog_content = "... Esses Eclipsitas foram descobertos pela Illumina há muito tempo.",
  ui_story_5080_50801201_61_dialog_content = "Que? Por que eu não tinha ouvido falar disso?",
  ui_story_5080_50801201_62_dialog_content = "Naquela época, o Comitê designou a equipe da minha tia para uma missão igual à nossa.",
  ui_story_5080_50801201_63_dialog_content = "O capitão dela foi quem fundou oficialmente a Rediesel Wrench.",
  ui_story_5080_50801201_64_dialog_content = "Sabe, sua tia serviu no Esquadrão Freebird.",
  ui_story_5080_50801201_65_dialog_content = "Sua última missão foi uma importante tarefa diretamente designada pelo Comitê, mas não só ela falhou, como seu capitão também desertou da Illumina posteriormente.",
  ui_story_5080_50801201_66_dialog_content = "Muitas pessoas disseram que o Esquadrão Freebird abandonou sua missão sem permissão para se salvar. O que você acha disso?",
  ui_story_5080_50801201_67_dialog_content = "Estou envergonhado! Grande Marechal. Me sinto muito... culpado pelo fracasso da minha tia.",
  ui_story_5080_50801201_68_dialog_content = "Mas ela sempre foi leal. Ela apenas foi arrastada para baixo por aquele capitão!",
  ui_story_5080_50801201_69_dialog_content = "Por favor, me dê uma chance de restaurar a honra da minha família.",
  ui_story_5080_50801201_70_dialog_content = "Mas se aquela desgraça não tivesse acontecido, sua tia poderia ter morrido como uma heroína.",
  ui_story_5080_50801201_71_dialog_content = "Isso teria sido mais fácil para você aceitar?",
  ui_story_5080_50801201_72_dialog_content = "Hum... eu... eu...",
  ui_story_5080_50801201_73_dialog_content = "Hahaha... Eu só estava perguntando.",
  ui_story_5080_50801201_74_dialog_content = "Agora, deixe-me dizer por que te chamei aqui - tenho uma missão para você.",
  ui_story_5080_50801201_75_dialog_content = "A última missão da sua tia é a que eu desejo atribuir a você.",
  ui_story_5080_50801201_76_dialog_content = "Grande Marechal?",
  ui_story_5080_50801201_77_dialog_content = "Naquela época, o Comitê ordenou que o Esquadrão Freebird trouxesse aquele Eclipsita observado de volta vivo.",
  ui_story_5080_50801201_78_dialog_content = "Eles queriam um espécime vivo para fins de experimentação.",
  ui_story_5080_50801201_79_dialog_content = "Ainda estou cético sobre se tal pesquisa tem implicações positivas para a Illumina, então não vou forçá-lo a nada.",
  ui_story_5080_50801201_80_dialog_content = "(Eu...)",
  ui_story_5080_50801201_81_dialog_content = "Claro, capturar aquele Eclipsita vivo pode compensar o seu arrependimento sobre sua tia.",
  ui_story_5080_50801201_82_dialog_content = "No entanto, Rachel, você pode decidir o que fazer por si mesmo.",
  ui_story_5080_50801201_83_dialog_content = "Escolhi um colega de equipe especial para sua missão. Você já ouviu o nome \"Vice\", eu presumo?",
  ui_story_5080_50801201_84_dialog_content = "O jovem capitão rumores de trabalhar de perto com um Celestita? Mas ela tem trabalhado com Celestita por tanto tempo...",
  ui_story_5080_50801201_85_dialog_content = "Certo. Se ela fosse com você, como o parceiro dela não seguiria?",
  ui_story_5080_50801201_86_dialog_content = "Eles são indivíduos incríveis. Tenho certeza de que você encontrará algumas respostas nesta missão.",
  ui_story_5080_50801201_87_dialog_content = "Este também é um pedido cuidadosamente emitido por Hiiro. Você tem um superior excelente, Rachel.",
  ui_story_5080_50801201_88_dialog_content = "Muito obrigado, e obrigado, Comandante Hiiro. Obrigado por ainda acreditar em mim e me dar essa oportunidade!",
  ui_story_5080_50801201_89_dialog_content = "Vou me preparar para partir imediatamente!",
  ui_story_5080_50801201_90_dialog_content = "Espere um momento, Rachel.",
  ui_story_5080_50801201_91_dialog_content = "Fique tranquilo, vou completar a missão!",
  ui_story_5080_50801201_92_dialog_content = "Só quero te perguntar uma coisa—",
  ui_story_5080_50801201_93_dialog_content = "Você ainda consegue encontrar a Illumina no seu coração?",
  ui_story_5080_50801201_94_dialog_content = "Eu... Eu sei o que te preocupa, Grande Marechal.",
  ui_story_5080_50801201_95_dialog_content = "De fato, cometi erros no comando, erros que levaram à queda da minha equipe. E parece que não consigo me dar bem com os membros da minha equipe no estado em que me encontro...",
  ui_story_5080_50801201_96_dialog_content = "Mas fique tranquilo, não vou cometer os mesmos erros novamente.",
  ui_story_5080_50801201_97_dialog_content = "Não foi isso que eu quis dizer, mas tudo bem. Vá em frente.",
  ui_story_5080_50801201_98_dialog_content = "Tê-los por perto pode alterar seu pensamento.",
  ui_story_5080_50801201_99_dialog_content = "Eles são parceiros lendários, pessoas incríveis. Suas palavras têm grande poder.",
  ui_story_5080_50801201_100_dialog_content = "Vou prestar mais atenção e continuar a manter o meu... Não vou me envolver com nenhum colega de equipe, e não vou colocar mais ninguém em apuros...",
  ui_story_5080_50801201_101_dialog_content = "Tia, tenho boas notícias.",
  ui_story_5080_50801201_102_dialog_content = "Eu tenho uma nova missão.",
  ui_story_5080_50801201_103_dialog_content = "Sério? Isso é maravilhoso. Mas você está bem? Não se esforce demais.",
  ui_story_5080_50801201_104_dialog_content = "Estou bem, tia. E desta vez, eu talvez tenha a chance de investigar o que aconteceu naquela época.",
  ui_story_5080_50801201_105_dialog_content = "Vou limpar seu nome.",
  ui_story_5080_50801201_106_dialog_content = "Não pense assim, Rachel.",
  ui_story_5080_50801201_107_dialog_content = "Nunca me arrependi do que aconteceu naquela época. Sou profundamente grato ao capitão por me permitir sobreviver.",
  ui_story_5080_50801201_108_dialog_content = "Se não fosse por ela, eu estaria perdendo o prazer da sua companhia.",
  ui_story_5080_50801201_109_dialog_content = "Por que você ainda está defendendo ela... Ela desertou Illumina.",
  ui_story_5080_50801201_110_dialog_content = "A capitã não é uma desertora, nem é uma traidora!",
  ui_story_5080_50801201_111_dialog_content = "Deve haver algum motivo para as ações dela que desconhecemos, mas eu acredito absolutamente nela com todo o meu coração!",
  ui_story_5080_50801201_112_dialog_content = "Ela transformou todos vocês em traidores e nem uma vez pensou em voltar em todos esses anos! Por que você ainda acredita nela?!",
  ui_story_5080_50801201_113_dialog_content = "Ela é a única que nos trouxe de volta daquele inferno derretido sozinha!",
  ui_story_5080_50801201_114_dialog_content = "Ela é uma verdadeira heroína!",
  ui_story_5080_50801201_115_dialog_content = "Eu só quero limpar o seu nome...",
  ui_story_5080_50801201_116_dialog_content = "Nossa família não fez nada de errado...",
  ui_story_5080_50801201_117_dialog_content = "Onde você está indo, Rachel?",
  ui_story_5080_50801201_118_dialog_content = "Volte, Rachel! Eu te proíbo de ir lá!",
  ui_story_5080_50801201_119_dialog_content = "Rachel...",
  ui_story_5080_50801201_120_dialog_content = "Embora a missão da Freebird tenha falhado, eles ainda conseguiram reunir uma grande quantidade de inteligência.",
  ui_story_5080_50801201_121_dialog_content = "A informação que eles deixaram para trás mencionava como o Eclipsite que observaram naquela época era uma espécie mutante que poderia absorver energia geotérmica para sobreviver.",
  ui_story_5080_50801201_122_dialog_content = "E este vulcão, sempre ativo mas nunca atingindo o ponto crítico de erupção, está repleto de tais Eclipsitas.",
  ui_story_5080_50801201_123_dialog_content = "Provavelmente é porque esses Eclipsitas estão absorvendo a energia do vulcão.",
  ui_story_5080_50801201_124_dialog_content = "A instabilidade do vulcão do Deserto Rediesel deve-se à energia geotérmica instável.",
  ui_story_5080_50801201_125_dialog_content = "A atividade desses Eclipsitas causa um desequilíbrio na energia geotérmica, mas sua alimentação no vulcão suprime suas erupções.",
  ui_story_5080_50801201_126_dialog_content = "Desta perspectiva, é provável que esses Eclipsitas tenham prosperado no subsolo todo esse tempo.",
  ui_story_5080_50801201_127_dialog_content = "Embora apenas um tenha sido observado naquela época, eles se tornaram uma colônia inteira agora.",
  ui_story_5080_50801201_128_dialog_content = "E eles até passaram essa característica terrível geneticamente.",
  ui_story_5080_50801201_129_dialog_content = "Espere, isso significa que devemos ser gratos a essas criaturas?",
  ui_story_5080_50801201_130_dialog_content = "É graças a eles que o vulcão não entrou em erupção? Bem, isso é simplesmente irritante.",
  ui_story_5080_50801201_131_dialog_content = "Mas se não fosse por esses Eclipsitas, a energia geotérmica não seria tão instável, e o ambiente não seria tão severo.",
  ui_story_5080_50801201_132_dialog_content = "Não teríamos que lidar com todos esses terremotos irritantes quando estamos dirigindo!",
  ui_story_5080_50801201_133_dialog_content = "Ainda mais do que isso - a desolação do deserto tem algo a ver com essas criaturas?",
  ui_story_5080_50801201_134_dialog_content = "De qualquer forma, o fato de que esses Eclipsitas podem <color=#FFB400>absorver</color> o poder do vulcão já é um passo longe demais para mim.",
  ui_story_5080_50801201_135_dialog_content = "Se <color=#FFB400>aquela Eclipsita</color> de antes conseguiu sobreviver todo esse tempo, quão poderosa é essa coisa?",
  ui_story_5080_50801201_136_dialog_content = "Não podemos permitir que isso exista por mais tempo...",
  ui_story_5080_50801201_137_dialog_content = "Nós absolutamente não podemos permitir que isso continue...",
  ui_story_5080_50801201_138_dialog_content = "Então vamos continuar avançando, mais fundo no vulcão! Em direção a Sinsa!",
  ui_story_5080_50801202_1_dialog_content = "Caramba... Isso que é um aperto.",
  ui_story_5080_50801202_2_dialog_content = "E tem lava por toda parte... Cuidado!",
  ui_story_5080_50801202_3_dialog_content = "Filhote Dois, Garota Pirulito, fique na minha cola!",
  ui_story_5080_50801202_4_dialog_content = "Caçador de Águia Um, Dois, Três - atirar!",
  ui_story_5080_50801202_5_dialog_content = "Capitão, não se esforce demais! Esses Eclipsitas têm defesas realmente duras!",
  ui_story_5080_50801202_6_dialog_content = "Chega de conversa! Ataque concentrado!",
  ui_story_5080_50801202_7_dialog_content = "Sem medo! Minha doce bomba vai resolver isso rapidinho!",
  ui_story_5080_50801202_8_dialog_content = "Rugido-!",
  ui_story_5080_50801202_9_dialog_content = "Capitão!",
  ui_story_5080_50801202_10_dialog_content = "É só um arranhão—fique parado.",
  ui_story_5080_50801202_11_dialog_content = "Aqui vem a segunda rodada!",
  ui_story_5080_50801202_12_dialog_content = "Águia Caçador Um, recue e defenda-se!",
  ui_story_5080_50801202_13_dialog_content = "Não! Tarde demais...",
  ui_story_5080_50801202_14_dialog_content = "Ataque do Herói!",
  ui_story_5080_50801202_15_dialog_content = "Rugido-!",
  ui_story_5080_50801202_16_dialog_content = "Zeta?!",
  ui_story_5080_50801202_17_dialog_content = "Garota Pirulito!!!",
  ui_story_5080_50801202_18_dialog_content = "Fleur, eu o tenho na coleira com meu Impulso de Força! Ataque agora!",
  ui_story_5080_50801202_19_dialog_content = "Te vejo no inferno!",
  ui_story_5080_50801202_20_dialog_content = "Caiu na lava?",
  ui_story_5080_50801202_21_dialog_content = "Groooar!!!",
  ui_story_5080_50801202_22_dialog_content = "Foi engolido pela lava... Esses Eclipsitas não deveriam ser capazes de resistir à lava?",
  ui_story_5080_50801202_23_dialog_content = "Menina Pirulito, você está bem?!",
  ui_story_5080_50801202_24_dialog_content = "Heh, e aí, Eagleshot? A Rediesel Wrench não é nada mal.",
  ui_story_5080_50801202_25_dialog_content = "Por que você faria isso... por mim...?",
  ui_story_5080_50801202_26_dialog_content = "'Porque você é a irmã perdida há muito tempo do herói que se desviou...",
  ui_story_5080_50801202_27_dialog_content = "Garota Pirulito? Garota Pirulito!",
  ui_story_5080_50801202_28_dialog_content = "(Droga, sem kits médicos e Zeta está em péssimas condições... Espere... Hã?)",
  ui_story_5080_50801202_29_dialog_content = "Falhei novamente no meu comando? Deixei, mais uma vez, outra pessoa...",
  ui_story_5080_50801202_30_dialog_content = "Eu deveria ser o protetor...",
  ui_story_5080_50801202_31_dialog_content = "Por que eu continuo estragando tudo? Estou muito cheio de mim mesmo?",
  ui_story_5080_50801202_32_dialog_content = "Não seja tão duro consigo mesmo, Zeta ainda tem uma chance de lutar! Rápido, coloque-a nas minhas costas, precisamos nos mover.",
  ui_story_5080_50801202_33_dialog_content = "Aguente firme, Zeta! Eu vou te tirar daqui, eu prometo!",
  ui_story_5080_50801202_34_dialog_content = "O demônio mecânico reformado, parece que minha jornada pode estar no fim. Apenas esqueça de mim...",
  ui_story_5080_50801202_35_dialog_content = "Pare de brincar!",
  ui_story_5080_50801202_36_dialog_content = "Saia disso! Lembra da nova válvula que você encomendou de mim?",
  ui_story_5080_50801202_37_dialog_content = "Apenas me dê um pouco mais de tempo, e eu descobrirei um motor twin-V8 ainda mais avançado! Não quer dar uma volta?",
  ui_story_5080_50801202_38_dialog_content = "Hã?!",
  ui_story_5080_50801202_39_dialog_content = "Se você aguentar até sairmos daqui, vou personalizar seu carro exclusivamente - sem mais ajudar para Azure! Fechado?",
  ui_story_5080_50801202_40_dialog_content = "Além disso, você sempre quis saber o que está debaixo do capô do carro de Azure? Eu vou descobrir para você!",
  ui_story_5080_50801202_41_dialog_content = "Vamos encontrar o Roy e fazê-lo vir conosco... Zeta, acorde!",
  ui_story_5080_50801202_42_dialog_content = "Estou planejando uma pegadinha com Azure com aquele cara! Você só espera e verá!",
  ui_story_5080_50801202_43_dialog_content = "Certo, certo. Garota Pirulito, eu também posso dar uma mão. Eu me formei em engenharia mecânica na academia!",
  ui_story_5080_50801202_44_dialog_content = "Mas você nem me chama pelo meu nome...",
  ui_story_5080_50801202_45_dialog_content = "Eu também posso modificar o seu veículo. A tecnologia da Illumina é de primeira, você sabe.",
  ui_story_5080_50801202_46_dialog_content = "Já sonhou em dirigir uma carruagem de princesa ao estilo Illumina?",
  ui_story_5080_50801202_47_dialog_content = "O quê?! De jeito nenhum! Eu quero ver agora! Tem alguma planta?",
  ui_story_5080_50801202_48_dialog_content = "Zeta? Você... você está bem?",
  ui_story_5080_50801202_49_dialog_content = "Uh... Heh, parece que o Doce Caçador nas minhas costas levou o golpe por mim... Acho que eu sou a heroína escolhida afinal.",
  ui_story_5080_50801202_50_dialog_content = "Senhora Zeta está de volta à ação!",
  ui_story_5080_50801202_51_dialog_content = "Irmã, você...",
  ui_story_5080_50801202_52_dialog_content = "Esta é a história da Criança Selvagem, Guerreira Zeta! Ela não vai desistir sem lutar... Hum...",
  ui_story_5080_50801202_53_dialog_content = "Eu não estava tentando enganar vocês, eu só queria que Fleur me carregasse por um tempo.",
  ui_story_5080_50801202_54_dialog_content = "Você me assustou agora... Por que está brincando em um momento como este... Sério... Mas estou feliz que você está bem.",
  ui_story_5080_50801202_55_dialog_content = "(Quando eu percebi pela primeira vez, não sabia como contar a eles... Estou feliz que essa piada não durou muito.)",
  ui_story_5080_50801202_56_dialog_content = "Minhas costas estão me matando!",
  ui_story_5080_50801202_57_dialog_content = "Eagleshot, você parece chateado. Você não está bravo comigo, está...?",
  ui_story_5080_50801202_58_dialog_content = "Huh? Seu rosto está tão sério agora... Você parece que está prestes a se transformar em um vilão! Está planejando transformar isso em uma história de terror?!",
  ui_story_5080_50801202_59_dialog_content = "Não—",
  ui_story_5080_50801202_60_dialog_content = "Hã?!",
  ui_story_5080_50801202_61_dialog_content = "Zeta... Estou tão feliz que você está bem.",
  ui_story_5080_50801202_62_dialog_content = "Você não pode simplesmente acariciar a cabeça de um herói de qualquer maneira! Mas já que você está agindo de forma tão fofa, eu realmente não consigo te recusar... Hã?",
  ui_story_5080_50801202_63_dialog_content = "V-Você disse meu nome!",
  ui_story_5080_50801202_64_dialog_content = "Você não deveria assustar as pessoas com piadas assim...",
  ui_story_5080_50801202_65_dialog_content = "Capitão...",
  ui_story_5080_50801202_66_dialog_content = "Não se preocupe, um herói nunca usa o mesmo truque duas vezes, hehe.",
  ui_story_5080_50801202_67_dialog_content = "Bem, já que está tudo bem, depois de tudo isso... vamos sair dessa armadilha de lava! Continue se movendo!",
  ui_story_5080_50801202_68_dialog_content = "Celestita Um, Filhote Dois - não fique para trás!",
  ui_story_5080_50801202_69_dialog_content = "Por que ela ainda está me chamando pelo meu codinome...",
  ui_story_5080_50801202_70_dialog_content = "Não vamos nos preocupar com os pequenos detalhes por agora. Hora de ir.",
  ui_story_5080_50801202_71_dialog_content = "A missão deve continuar. Apresse-se!",
  ui_story_5080_50801202_72_dialog_content = "(Ela coloca aquela máscara fria de indiferença tão rapidamente, mas agora parece tão fora do lugar, Rachel...)",
  ui_story_5080_50801202_73_dialog_content = "Vamos lá, Vice. Tenho a sensação de que está quase acabando.",
  ui_story_5080_50801202_74_dialog_content = "Mova-se rapidamente! Fique longe das zonas de perigo. Uh...",
  ui_story_5080_50801202_75_dialog_content = "O que houve?",
  ui_story_5080_50801202_76_dialog_content = "Nada, vamos lá!",
  ui_story_5080_50801202_77_dialog_content = "Águia Caçador Um, batedor à frente. Todos os outros, sigam Águia Caçador Um!",
  ui_story_5080_50801202_78_dialog_content = "As vidas deles ainda estão em minhas mãos... Eu não posso... cair agora...",
  ui_story_5080_50801301_1_dialog_content = "Graaaaah—!",
  ui_story_5080_50801301_2_dialog_content = "Eles estão invadindo.",
  ui_story_5080_50801301_3_dialog_content = "Cheio de maldade, transbordando de ódio.",
  ui_story_5080_50801301_4_dialog_content = "Jeriah, comece a se mover, eu posso lidar com isso.",
  ui_story_5080_50801301_5_dialog_content = "Do que você está falando? Sua visão está prejudicada. Não vou te deixar para trás.",
  ui_story_5080_50801301_6_dialog_content = "Suas habilidades... não são adequadas para esta batalha.",
  ui_story_5080_50801301_7_dialog_content = "Afinal, ainda sou um membro sênior.",
  ui_story_5080_50801301_8_dialog_content = "O chão... está afundando... Eu vou cair na lava!",
  ui_story_5080_50801301_9_dialog_content = "Dawn! Um pouco para a esquerda—pegue minha mão!",
  ui_story_5080_50801301_10_dialog_content = "Você vá em frente, Jeriah.",
  ui_story_5080_50801301_11_dialog_content = "Eu segurei sua mão. Não solte, Dawn.",
  ui_story_5080_50801301_12_dialog_content = "Os Eclipsitas, eles estão chegando.",
  ui_story_5080_50801301_13_dialog_content = "Não tenho tempo para pensar sobre isso agora.",
  ui_story_5080_50801301_14_dialog_content = "Por quê? Jeriah, você precisa viver!",
  ui_story_5080_50801301_15_dialog_content = "Se você morrer, todos ficarão tão tristes.",
  ui_story_5080_50801301_16_dialog_content = "Consegue imaginar o rosto de Eve banhado em lágrimas?",
  ui_story_5080_50801301_17_dialog_content = "Ela estaria te abraçando e chorando!",
  ui_story_5080_50801301_18_dialog_content = "...",
  ui_story_5080_50801301_19_dialog_content = "Essa linha de pipa realmente tem uma forte ligação com você.",
  ui_story_5080_50801301_20_dialog_content = "Agora que essa conexão entre nós foi estabelecida, não vou deixar que seja facilmente cortada!",
  ui_story_5080_50801301_21_dialog_content = "Jeriah... Cuidado!",
  ui_story_5080_50801301_22_dialog_content = "Attar, eu tentei o meu melhor...",
  ui_story_5080_50801301_23_dialog_content = "<color=#FFB400>Torrente Rápida!</color>",
  ui_story_5080_50801301_24_dialog_content = "Na hora certa! Zeta, bloqueie-os com suas bombas!",
  ui_story_5080_50801301_25_dialog_content = "Ei-ei, a bomba de açúcar definitiva está vindo em sua direção!",
  ui_story_5080_50801301_26_dialog_content = "Jeriah, estou aqui para ajudar! Fleur, por favor, ajude a puxar Dawn...",
  ui_story_5080_50801301_27_dialog_content = "<color=#FFB400>Flor de Gelo!</color>",
  ui_story_5080_50801301_28_dialog_content = "A ponte está pronta, vamos, suba!",
  ui_story_5080_50801301_29_dialog_content = "Carleen? E Eve?",
  ui_story_5080_50801301_30_dialog_content = "Dawn, estou aqui para te ajudar!",
  ui_story_5080_50801301_31_dialog_content = "Você tem sido de grande ajuda, Pequena Princesa de Lumópolis.",
  ui_story_5080_50801301_32_dialog_content = "Não há necessidade de me agradecer. Você também está lutando duro para proteger aqueles que se importa, não está?",
  ui_story_5080_50801301_33_dialog_content = "Venha comigo, Dawn. Não solte a minha mão!",
  ui_story_5080_50801301_34_dialog_content = "Jeriah... minha mão...",
  ui_story_5080_50801301_35_dialog_content = "Finalmente nos reagrupamos. Carleen, vocês estão todos bem?",
  ui_story_5080_50801301_36_dialog_content = "Estamos bem, mas a lava aqui é muito perigosa. Não conseguiremos lutar aqui por muito tempo.",
  ui_story_5080_50801301_37_dialog_content = "Pequeno pássaro de rapina, Princesa, apresse-se e leve Zeta para longe daqui.",
  ui_story_5080_50801301_38_dialog_content = "Celestita, receio que devo pedir para você usar suas habilidades psíquicas para nos levar até Sinsa.",
  ui_story_5080_50801301_39_dialog_content = "Você não está saindo?",
  ui_story_5080_50801301_40_dialog_content = "Hah... Como eu poderia possivelmente abandoná-lo em um momento como este?",
  ui_story_5080_50801301_41_dialog_content = "Eu não vou embora! Eu também quero salvar o Berserker!",
  ui_story_5080_50801301_42_dialog_content = "Eu também não posso simplesmente me afastar.",
  ui_story_5080_50801301_43_dialog_content = "Por que vocês escolheram um momento como este para se tornarem tão teimosos?",
  ui_story_5080_50801301_44_dialog_content = "Vamos mais fundo, então.",
  ui_story_5080_50801301_45_dialog_content = "Capitão?",
  ui_story_5080_50801301_46_dialog_content = "A missão deve continuar. Precisamos reunir mais informações... e salvar o líder da Rediesel também é uma opção.",
  ui_story_5080_50801301_47_dialog_content = "Técnico da Rediesel, me empreste suas ferramentas. Filhote Dois, me dê sua arma.",
  ui_story_5080_50801301_48_dialog_content = "Hã? Eu?",
  ui_story_5080_50801301_49_dialog_content = "Tudo bem, eu melhorei sua arma. Pode levar algum tempo para se acostumar, mas deve ser mais fácil de usar agora que você está machucado.",
  ui_story_5080_50801301_50_dialog_content = "Caçador de Águia Um, Dois, Três - retornem!",
  ui_story_5080_50801301_51_dialog_content = "Caçador de Águias Um e Três, é a vez do Caçador de Águias Dois liderar.",
  ui_story_5080_50801301_52_dialog_content = "Prepare-se—continue a missão.",
  ui_story_5080_50801301_53_dialog_content = "Meu arco parece mais leve. A corda do arco parece mais responsiva...",
  ui_story_5080_50801301_54_dialog_content = "A capitã se lembra exatamente do que eu gosto. Ela é tão atenciosa, então por que ela sempre mantém distância de nós?",
  ui_story_5080_50801301_55_dialog_content = "Como capitã, ela tem que completar a missão e manter seus companheiros de equipe vivos.",
  ui_story_5080_50801301_56_dialog_content = "Minimizar o afeto de sua equipe por ela pode ser seu último recurso para evitar que mais alguém se machuque por causa dela.",
  ui_story_5080_50801301_57_dialog_content = "Eu entendo o peso que ela está carregando.",
  ui_story_5080_50801301_58_dialog_content = "Sinsa!",
  ui_story_5080_50801301_59_dialog_content = "Seu idiota... Consegue me ouvir?",
  ui_story_5080_50801301_60_dialog_content = "Sinsa?! Responda-nos!",
  ui_story_5080_50801301_61_dialog_content = "Roy, olhe lá embaixo! Aquele ponto ao lado da lava - é o cabelo vermelho de Sinsa?",
  ui_story_5080_50801301_62_dialog_content = "Seja como for, eu vou descer para verificar!",
  ui_story_5080_50801301_63_dialog_content = "Ei! Isso é lava! Como você pode simplesmente pular lá assim?! Ei!",
  ui_story_5080_50801301_64_dialog_content = "Esqueça isso, eu sou o que vai superar o Sinsa algum dia, então como eu poderia recuar em um momento como este?",
  ui_story_5080_50801301_65_dialog_content = "Estou pulando!",
  ui_story_5080_50801301_66_dialog_content = "Waaaahhhh—!",
  ui_story_5080_50801301_67_dialog_content = "Há lava por todo o lado!",
  ui_story_5080_50801301_68_dialog_content = "Saia do caminho!",
  ui_story_5080_50801301_69_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5080_50801301_70_dialog_content = "Você está me esmagando, velho...",
  ui_story_5080_50801301_71_dialog_content = "Olha, é o Sinsa! É realmente o Sinsa! Ele está vivo!",
  ui_story_5080_50801301_72_dialog_content = "Sinsa, você—",
  ui_story_5080_50801301_73_dialog_content = "Uau... Olhe para todos esses Eclipsitas mortos... Ele matou todos eles sozinho?",
  ui_story_5080_50801301_74_dialog_content = "Mesmo com ferimentos tão graves após cair todo o caminho até aqui, ele ainda conseguiu matar tantos deles.",
  ui_story_5080_50801301_75_dialog_content = "Ei, vocês vieram... Eu acabei de estrangular esse grandão aqui...",
  ui_story_5080_50801301_76_dialog_content = "Sinsa?!",
  ui_story_5080_50801301_77_dialog_content = "Sinsa, saia disso. Já está morto, solte e venha conosco!",
  ui_story_5080_50801301_78_dialog_content = "Hã? Sinsa?!",
  ui_story_5080_50801301_79_dialog_content = "Não comi muito bem mais cedo... Estou com fome de novo...",
  ui_story_5080_50801301_80_dialog_content = "Eu realmente quero voltar e comer com todos. A comida sempre tem um sabor melhor assim...",
  ui_story_5080_50801301_81_dialog_content = "Roy, estou tão sonolento. Devo ter me preocupado demais nos últimos dias.",
  ui_story_5080_50801301_82_dialog_content = "Vamos voltar para o nosso banquete de vitória. Não devemos fazer os outros esperar muito tempo...",
  ui_story_5080_50801301_83_dialog_content = "O que há de errado com ele? Verifique se ele está bem - não o deixe simplesmente desmaiar assim!",
  ui_story_5080_50801301_84_dialog_content = "... Ele está bem. Ele apenas se cansou e adormeceu.",
  ui_story_5080_50801301_85_dialog_content = "Ele saiu à procura de pessoas ontem à noite e não comeu muito quando voltou, coitado.",
  ui_story_5080_50801301_86_dialog_content = "Hmph, eu sabia que esse cara não era tão frágil.",
  ui_story_5080_50801301_87_dialog_content = "Além disso, eu sou o único que tem permissão para bater nele!",
  ui_story_5080_50801301_88_dialog_content = "Vamos, coloque-o nas minhas costas.",
  ui_story_5080_50801301_89_dialog_content = "Quando ele acordar e descobrir que teve que depender de mim, ele vai ficar tão envergonhado!",
  ui_story_5080_50801301_90_dialog_content = "Deixo ele com você então, e eu vou na frente. Vamos apressar o retorno—",
  ui_story_5080_50801301_91_dialog_content = "Onde está a chave dele?",
  ui_story_5080_50801301_92_dialog_content = "Talvez ele tenha perdido quando caiu... Eu preciso procurar por isso...",
  ui_story_5080_50801301_93_dialog_content = "<color=#828282>Tum!</color>",
  ui_story_5080_50801301_94_dialog_content = "Você ouviu isso?",
  ui_story_5080_50801301_95_dialog_content = "Esse é o som de lava?",
  ui_story_5080_50801301_96_dialog_content = "<color=#e8d9bb>Tum, tum!</color>",
  ui_story_5080_50801301_97_dialog_content = "Aí está de novo!",
  ui_story_5080_50801301_98_dialog_content = "... Passos! Brock, corre!",
  ui_story_5080_50801301_99_dialog_content = "<color=#e8d9bb>Bate, baque, baque!</color>",
  ui_story_5080_50801301_100_dialog_content = "Corra!",
  ui_story_5080_50801302_1_dialog_content = "Socooooorro!!!",
  ui_story_5080_50801302_2_dialog_content = "Quem está aí?",
  ui_story_5080_50801302_3_dialog_content = "Quem é aquele?",
  ui_story_5080_50801302_4_dialog_content = "Uau! É aquele capitão da Illumina! Roy, venha aqui!",
  ui_story_5080_50801302_5_dialog_content = "O que houve?",
  ui_story_5080_50801302_6_dialog_content = "<size=45><color=#e8d9bb>Bate, baque, baque, baque, baque, baque, baque, baque, baque, baque!</color></size>",
  ui_story_5080_50801302_7_dialog_content = "<color=#e8d9bb>Rugido-!</color>",
  ui_story_5080_50801302_8_dialog_content = "Um Eclipsite?! Não... é o <color=#FFB400>alvo</color>!",
  ui_story_5080_50801302_9_dialog_content = "Obrigado pela ajuda, pequena senhora Illumina.",
  ui_story_5080_50801302_10_dialog_content = "Vou fazer uma chuva de balas para suprimi-los. Vocês vão embora, o resto está logo atrás!",
  ui_story_5080_50801302_11_dialog_content = "Depressa, Roy, nós—",
  ui_story_5080_50801302_12_dialog_content = "Cuidado!",
  ui_story_5080_50801302_13_dialog_content = "Rugido-!",
  ui_story_5080_50801302_14_dialog_content = "Sugador sorrateiro... Ele prefere apanhar do que nos deixar passar.",
  ui_story_5080_50801302_15_dialog_content = "O que é isso? Aquele Eclipsita bloqueou o caminho?",
  ui_story_5080_50801302_16_dialog_content = "Aquela coisa... É a que matou Attar...?",
  ui_story_5080_50801302_17_dialog_content = "Deixe-me cuidar disso!",
  ui_story_5080_50801302_18_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_19_dialog_content = "<color=#e8d9bb>O teto é estourado por um raio, derrubando o Eclipsita, mas essa explosão violenta de poder também faz o vulcão rugir, e a terra começa a tremer novamente.</color>",
  ui_story_5080_50801302_20_dialog_content = "Esse poder... Más notícias, pessoal—o vulcão está prestes a explodir!",
  ui_story_5080_50801302_21_dialog_content = "Garota Rediesel, continue atacando!",
  ui_story_5080_50801302_22_dialog_content = "Mas isso poderia desencadear uma erupção.",
  ui_story_5080_50801302_23_dialog_content = "Já foi despertado. Se sair daqui, os outros estarão em perigo!",
  ui_story_5080_50801302_24_dialog_content = "Acertei em cheio, mas não sinto que causei algum dano... Onde está o ponto fraco dele?",
  ui_story_5080_50801302_25_dialog_content = "Os Caçadores de Águia já fizeram o reconhecimento. A casca dele ainda não atingiu a verdadeira temperatura da lava.",
  ui_story_5080_50801302_26_dialog_content = "E, qualquer forma de vida é mais vulnerável quando está se alimentando.",
  ui_story_5080_50801302_27_dialog_content = "Se conseguirmos extinguir a sua casca, ele pode tentar absorver energia. Então, ele vai expor seu ponto fraco!",
  ui_story_5080_50801302_28_dialog_content = "Era claramente maior naquela época... Como conseguiu encolher e ficar aqui escondido por mais de uma década...?",
  ui_story_5080_50801302_29_dialog_content = "<color=#FFB400>Reconhecimento Mortal!</color>",
  ui_story_5080_50801302_30_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_31_dialog_content = "<color=#FFB400>Torrente Rápida!</color>",
  ui_story_5080_50801302_32_dialog_content = "<color=#FFB400>Flor de Gelo!</color>",
  ui_story_5080_50801302_33_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_34_dialog_content = "Está ferido! Nossos ataques estão funcionando!",
  ui_story_5080_50801302_35_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5080_50801302_36_dialog_content = "Droga, a parede está quebrada! A lava está entrando!",
  ui_story_5080_50801302_37_dialog_content = "Cuidado, pode absorver a energia da lava!",
  ui_story_5080_50801302_38_dialog_content = "Brock, puxe Sinsa para cima. Eve, cuidado!",
  ui_story_5080_50801302_39_dialog_content = "Wahhhhhh!!! Meu robô está pegando fogo!",
  ui_story_5080_50801302_40_dialog_content = "Zeta, vamos apenas atrasá-los. Venha se retirar comigo por agora!",
  ui_story_5080_50801302_41_dialog_content = "Mas, a heroína não pode simplesmente sair do palco em um momento como este!",
  ui_story_5080_50801302_42_dialog_content = "Escute, Zeta, você não quer que eu me preocupe, quer?",
  ui_story_5080_50801302_43_dialog_content = "Graaaaah—!",
  ui_story_5080_50801302_44_dialog_content = "Os Eclipsitas estão fugindo do ninho!",
  ui_story_5080_50801302_45_dialog_content = "Já que o velho disse... Dawn, eu te cubro—vamos reunir alguns novos amigos!",
  ui_story_5080_50801302_46_dialog_content = "Nem pense em machucar meu irmão!",
  ui_story_5080_50801302_47_dialog_content = "Eve, recue-se—Jeriah, você também...",
  ui_story_5080_50801302_48_dialog_content = "Vou mantê-lo ocupado. Vocês saiam daqui Sinsa!",
  ui_story_5080_50801302_49_dialog_content = "Jeriah?",
  ui_story_5080_50801302_50_dialog_content = "Se realmente é o mesmo que matou Attar... como eu poderia possivelmente deixá-lo ir?!",
  ui_story_5080_50801302_51_dialog_content = "Mesmo com a lava fluindo para dentro, ela não está sendo absorvida... Por quê?",
  ui_story_5080_50801302_52_dialog_content = "Parece que está... até mesmo evitando a lava?",
  ui_story_5080_50801302_53_dialog_content = "Espere, Vice, você está em um lugar perigoso - fique perto de mim!",
  ui_story_5080_50801302_54_dialog_content = "Carleen, use seu poder para criar um ponto de apoio na cabeça dele!",
  ui_story_5080_50801302_55_dialog_content = "Vou te dar cobertura! Vá em frente!",
  ui_story_5080_50801302_56_dialog_content = "<color=#FFB400>Caixas de som!</color>",
  ui_story_5080_50801302_57_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_58_dialog_content = "Está desacelerando? Deixe-me ajudar também!",
  ui_story_5080_50801302_59_option_content = "Aumento de Força!",
  ui_story_5080_50801302_60_dialog_content = "Aqueles depravados o suficiente para quebrar as asas de um pássaro pagarão o preço!",
  ui_story_5080_50801302_61_dialog_content = "Agora é a hora! Está pronta, Princesinha?!",
  ui_story_5080_50801302_62_dialog_content = "<color=#FFB400>Flor de Gelo!</color>",
  ui_story_5080_50801302_63_dialog_content = "Sua casca de magma é muito quente, e não estamos causando dano suficiente.",
  ui_story_5080_50801302_64_dialog_content = "Está funcionando, precisamos continuar atacando...",
  ui_story_5080_50801302_65_dialog_content = "Caçador de Águia Um, Caçador de Águia Dois—me perdoe.",
  ui_story_5080_50801302_66_dialog_content = "<color=#FFB400>Ataque de Autodestruição!</color>",
  ui_story_5080_50801302_67_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_68_dialog_content = "(Oh não, a energia de magma dele está muito forte agora. Não importa qual ataque usemos, ele simplesmente vai rebater.)",
  ui_story_5080_50801302_69_dialog_content = "Escapou do meu controle... cuidado, todos!",
  ui_story_5080_50801302_70_dialog_content = "(Minha cabeça... dói tanto...)",
  ui_story_5080_50801302_71_dialog_content = "Ei, a caverna está desabando! Vocês precisam se apressar e subir aqui!",
  ui_story_5080_50801302_72_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5080_50801302_73_dialog_content = "Está ficando cada vez mais quente. Neste ritmo...",
  ui_story_5080_50801302_74_dialog_content = "Eu peguei a pequena princesa. Pegue-a e corra!",
  ui_story_5080_50801302_75_dialog_content = "Oh não, Carleen e Jeriah estão presos!",
  ui_story_5080_50801302_76_dialog_content = "Pode ser um pouco lento, mas vou abrir um caminho. Vocês, cuidado!",
  ui_story_5080_50801302_77_dialog_content = "Por que isso está acontecendo? Nós já o escaneamos... Por que sua energia ainda é tão avassaladora?",
  ui_story_5080_50801302_78_dialog_content = "Eu me enganei?",
  ui_story_5080_50801302_79_dialog_content = "Pode continuar a reabastecer sua força em meio à batalha?",
  ui_story_5080_50801302_80_dialog_content = "A lava está vindo, Capitão! Corra!",
  ui_story_5080_50801302_81_dialog_content = "Continue sem mim! Eu devo assumir essa responsabilidade... Eu vou cobrir sua retirada!",
  ui_story_5080_50801302_82_dialog_content = "Trazem!",
  ui_story_5080_50801302_83_dialog_content = "<color=#FFB400>Torrente Rápida!</color>",
  ui_story_5080_50801302_84_dialog_content = "Deste jeito, isso mesmo!",
  ui_story_5080_50801302_85_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_86_dialog_content = "Filhote Dois!",
  ui_story_5080_50801302_87_dialog_content = "Não ouse tocar em Vice novamente!!!",
  ui_story_5080_50801302_88_option_content = "Aumento de Força!",
  ui_story_5080_50801302_89_dialog_content = "Filhote Dois, você está bem? Acorde!",
  ui_story_5080_50801302_90_dialog_content = "(O fanático por eficiência desistiu de uma chance de atacar por Vice...)",
  ui_story_5080_50801302_91_dialog_content = "Por que estou me sentindo tão feliz agora... mesmo que minha cabeça esteja doendo tanto...?",
  ui_story_5080_50801302_92_dialog_content = "Não temos tempo para nos preocupar com isso agora! Eve, vocês vão!",
  ui_story_5080_50801302_93_dialog_content = "Aí vem eles!",
  ui_story_5080_50801302_94_dialog_content = "<color=#FFB400>Punho de Ferro!</color>",
  ui_story_5080_50801302_95_dialog_content = "Pequena Princesa, vou deixar você para estabilizar a ponte!",
  ui_story_5080_50801302_96_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_97_dialog_content = "Funcionou! Eu acertei de tão longe!",
  ui_story_5080_50801302_98_dialog_content = "Está muito quente—Não consigo ver nada daqui de cima.",
  ui_story_5080_50801302_99_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_100_dialog_content = "Está tentando escapar.",
  ui_story_5080_50801302_101_dialog_content = "Nem pense em escapar!",
  ui_story_5080_50801302_102_dialog_content = "Não persiga, Jeriah! O chão abaixo de nós está prestes a ser engolido pela lava!",
  ui_story_5080_50801302_103_dialog_content = "... Não tenham medo, todos... Eu estou aqui.",
  ui_story_5080_50801302_104_dialog_content = "Os Alto-falantes encontraram um ponto fraco na parede. Por aqui.",
  ui_story_5080_50801302_105_dialog_content = "Arf... arf... Ponte de Gelo, implantar...",
  ui_story_5080_50801302_106_dialog_content = "Esta é toda a força que me resta.",
  ui_story_5080_50801302_107_dialog_content = "Eu tenho o Filhote Dois nas minhas costas... Todos, saiam daqui.",
  ui_story_5080_50801401_1_dialog_content = "<color=#FFB400>Flor de Gelo!</color>",
  ui_story_5080_50801401_2_dialog_content = "Não quebrou?",
  ui_story_5080_50801401_3_dialog_content = "A temperatura desta parede é muito alta. É difícil rompê-la à força.",
  ui_story_5080_50801401_4_dialog_content = "É tudo minha culpa... Eagle Hunter Um e Três se perderam em vão.",
  ui_story_5080_50801401_5_dialog_content = "Está muito quente aqui - muito quente para usar explosivos sem um cálculo cuidadoso...",
  ui_story_5080_50801401_6_dialog_content = "Apenas me dê um segundo, e eu vou calcular uma explosão precisa.",
  ui_story_5080_50801401_7_dialog_content = "Ei, Roy, você está vendo isso? Eles estão presos naquele corredor.",
  ui_story_5080_50801401_8_dialog_content = "Não consigo acertar um bom tiro daqui...",
  ui_story_5080_50801401_9_dialog_content = "Espere, Eve, seu poder é muito volátil para algo assim!",
  ui_story_5080_50801401_10_dialog_content = "Apenas Sinsa pode conseguir isso - eu tenho que acordá-lo!",
  ui_story_5080_50801401_11_dialog_content = "Roy, traga todas as rações!",
  ui_story_5080_50801401_12_dialog_content = "Huh? O que você está planejando fazer com o cara...?",
  ui_story_5080_50801401_13_dialog_content = "Hohoho! Não é óbvio? Vou enchê-lo de comida!",
  ui_story_5080_50801401_14_dialog_content = "Mastigar, mastigar, mastigar, mastigar, mastigar, mastigar...",
  ui_story_5080_50801401_15_dialog_content = "Pare! Você está tentando sufocá-lo?!",
  ui_story_5080_50801401_16_dialog_content = "<size=45>Já pare com isso!</size>",
  ui_story_5080_50801401_17_dialog_content = "Vice... Vice... Não me assuste assim...",
  ui_story_5080_50801401_18_dialog_content = "Filhote Dois, Filhote Dois - acorde.",
  ui_story_5080_50801401_19_dialog_content = "Caçador de Águia Dois, ative o modo de emergência imediatamente! Ajuste o desfibrilador para o nível dois! Carregando!",
  ui_story_5080_50801401_20_dialog_content = "<color=#FFB400>Zap!</color>",
  ui_story_5080_50801401_21_dialog_content = "Hum...",
  ui_story_5080_50801401_22_dialog_content = "Graças a Deus você está bem...",
  ui_story_5080_50801401_23_dialog_content = "Filhote Dois! Você consegue ouvir minha voz? Não se preocupe, eu vou tirá-lo daqui...",
  ui_story_5080_50801401_24_dialog_content = "Capitão...",
  ui_story_5080_50801401_25_dialog_content = "Filhote Dois? Filhote Dois?",
  ui_story_5080_50801401_26_dialog_content = "...Já chega, Rachel!",
  ui_story_5080_50801401_27_dialog_content = "Se você quer despertar o coração dela, pelo menos chame-a pelo nome dela!",
  ui_story_5080_50801401_28_dialog_content = "Diga o nome dela! Ela não é \"Filhote Dois\", ela tem um nome–Vice!",
  ui_story_5080_50801401_29_dialog_content = "Celestita Um...",
  ui_story_5080_50801401_30_dialog_content = "Não importa o que aconteça comigo, mas Vice...",
  ui_story_5080_50801401_31_dialog_content = "Ela te idolatra e respeita. Ela estava nas nuvens só de poder fazer equipe com você.",
  ui_story_5080_50801401_32_dialog_content = "E ainda assim, você nunca a chamou pelo nome dela nem uma vez!",
  ui_story_5080_50801401_33_dialog_content = "...",
  ui_story_5080_50801401_34_dialog_content = "O nome dela é Vice! Ela ficaria acordada a noite toda trabalhando em relatórios de missão para você, exausta, mas sempre tão animada...",
  ui_story_5080_50801401_35_dialog_content = "Mesmo que você nunca tenha chamado ela pelo nome, só de conversar com o oficial superior dela fez o dia dela!",
  ui_story_5080_50801401_36_dialog_content = "Vice adora seus superiores - ela vive por seus elogios. Ela não fez nada de errado... É apenas um nome! Do que você tem tanto medo...?",
  ui_story_5080_50801401_37_dialog_content = "Por favor, pelo menos... pelo menos agora, chame-a pelo nome dela...",
  ui_story_5080_50801401_38_dialog_content = "Eu... não posso me dar ao luxo de formar mais nenhum vínculo desnecessário...",
  ui_story_5080_50801401_39_dialog_content = "Pequeno pássaro de presa...",
  ui_story_5080_50801401_40_dialog_content = "Já nos desviamos da missão... Eu não posso... não posso arrastar mais ninguém para baixo...",
  ui_story_5080_50801401_41_dialog_content = "... Me desculpe, ela se saiu tão bem... É tudo culpa minha...",
  ui_story_5080_50801401_42_dialog_content = "Tenho medo de me tornar um fardo novamente... Não quero que mais ninguém morra por minha causa...",
  ui_story_5080_50801401_43_dialog_content = "Se eu formar novos laços... se mais do meu pessoal morrer por causa das minhas ordens... eu... não posso aceitar isso...",
  ui_story_5080_50801401_44_dialog_content = "Não! Eu não estou tentando culpar ninguém!",
  ui_story_5080_50801401_45_dialog_content = "Você sempre escondeu sua bondade enquanto genuinamente se importava com todos. Por que continuar escondendo?",
  ui_story_5080_50801401_46_dialog_content = "É porque quando você se importa sinceramente com os outros, eles estão dispostos a arriscar suas vidas para protegê-lo.",
  ui_story_5080_50801401_47_dialog_content = "Como você pode chamar isso de um anexo desnecessário...?",
  ui_story_5080_50801401_48_dialog_content = "Celestita Um, você não entenderia...",
  ui_story_5080_50801401_49_dialog_content = "Como eu poderia não entender?! Eu assisti impotente enquanto outros se sacrificavam por mim! Como eu poderia não entender?!",
  ui_story_5080_50801401_50_dialog_content = "Perdi toda a minha raça e os amigos que finalmente encontrei... tudo por causa de mim...",
  ui_story_5080_50801401_51_dialog_content = "Eu entendo a dor de perder pessoas, a solidão e a culpa...",
  ui_story_5080_50801401_52_dialog_content = "Eu realmente agradeço a todos que me ajudaram. O apoio deles permite que Vice, eu e todos os nossos amigos continuemos seguindo em frente.",
  ui_story_5080_50801401_53_dialog_content = "Eu não acho que esses anexos sejam desnecessários de forma alguma.",
  ui_story_5080_50801401_54_dialog_content = "Apenas poder conhecer todos foi uma experiência verdadeiramente maravilhosa... Eu gostaria de chamar seus nomes e conversar com eles novamente se pudesse.",
  ui_story_5080_50801401_55_dialog_content = "PlayerName...",
  ui_story_5080_50801401_56_dialog_content = "Chega... Celestita Um...",
  ui_story_5080_50801401_57_dialog_content = "As pessoas se sacrificam pelos outros porque possuem um amor profundo em seus corações.",
  ui_story_5080_50801401_58_dialog_content = "Aqueles que te cobriram, e Vice, eles não estavam fazendo isso pela missão!",
  ui_story_5080_50801401_59_dialog_content = "Eles só queriam proteger você... e o fato de você ter sobrevivido é mais do que suficiente para deixá-los felizes.",
  ui_story_5080_50801401_60_dialog_content = "Assim como o capitão do Esquadrão Freebird... ela deve ter tido tanto amor por sua equipe, que estava disposta a manchar sua reputação apenas para trazê-los de volta.",
  ui_story_5080_50801401_61_dialog_content = "O sacrifício é sobre proteger as pessoas atrás de você...",
  ui_story_5080_50801401_62_dialog_content = "Para aqueles que finalmente se entendem, não é motivo suficiente...?",
  ui_story_5080_50801401_63_dialog_content = "Não diga mais nada... Eu...",
  ui_story_5080_50801401_64_dialog_content = "Rachel, você sabe disso no seu coração... Você frequentemente arriscou sua vida por nós...",
  ui_story_5080_50801401_65_dialog_content = "Foi realmente tudo sobre eficiência?",
  ui_story_5080_50801401_66_dialog_content = "Você só tem medo de alguém se machucar... é por isso que você se esforça tanto para proteger a todos...",
  ui_story_5080_50801401_67_dialog_content = "Se for esse o caso... por que resistir a formar conexões...?",
  ui_story_5080_50801401_68_dialog_content = "PlayerName... não chore... você já se esforçou demais...",
  ui_story_5080_50801401_69_dialog_content = "... Precisamos nos preparar para a explosão, espere só mais um pouco.",
  ui_story_5080_50801401_70_dialog_content = "Pequeno pássaro de rapina... não, Rachel.",
  ui_story_5080_50801401_71_dialog_content = "Os céus do deserto costumam ver pássaros migratórios... mesmo quando se desviam sozinhos, eventualmente retornam ao bando.",
  ui_story_5080_50801401_72_dialog_content = "Eu... não entendia isso antes. Mas agora, percebo que escolher ser uma ave de rapina ainda significa que posso ter amigos.",
  ui_story_5080_50801401_73_dialog_content = "Eu... Eu... Eu não preciso de amigos...",
  ui_story_5080_50801401_74_dialog_content = "Você é tão... teimoso...",
  ui_story_5080_50801401_75_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5080_50801401_76_dialog_content = "O que aconteceu? Isso foi uma explosão?",
  ui_story_5080_50801401_77_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801401_78_dialog_content = "Cuidado!",
  ui_story_5080_50801401_79_dialog_content = "Rachel! Estou chegando!",
  ui_story_5080_50801401_80_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801401_81_dialog_content = "Droga, está atacando o chão.",
  ui_story_5080_50801401_82_dialog_content = "Alto-falantes, levem a princesinha para cima!",
  ui_story_5080_50801401_83_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5080_50801401_84_dialog_content = "A parede foi explodida! Venha comigo!",
  ui_story_5080_50801401_85_dialog_content = "PlayerName e os outros ainda estão lá embaixo!",
  ui_story_5080_50801401_86_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801401_87_dialog_content = "Você não vai... machucar meus amigos de novo!",
  ui_story_5080_50801401_88_dialog_content = "PlayerName! Saia daqui com Carleen e os outros!",
  ui_story_5080_50801401_89_dialog_content = "Rachel... você... finalmente se abriu…",
  ui_story_5080_50801401_90_dialog_content = "Talvez o corpo seja mais honesto que a mente... PlayerName, no momento em que te protegi daquele ataque...",
  ui_story_5080_50801401_91_dialog_content = "Essas palavras teimosas me escaparam.",
  ui_story_5080_50801401_92_dialog_content = "Então... vamos lá.",
  ui_story_5080_50801401_93_dialog_content = "A lava está vindo! Celestita, pegue minha mão!",
  ui_story_5080_50801401_94_dialog_content = "Merry, Louis, Louis, Tarsi... Meus companheiros, por favor, emprestem-me sua força.",
  ui_story_5080_50801401_95_dialog_content = "Deixe meus amigos irem!",
  ui_story_5080_50801401_96_dialog_content = "Não... eu não vou fugir...",
  ui_story_5080_50801401_97_dialog_content = "PlayerName?!",
  ui_story_5080_50801401_98_dialog_content = "Eu disse que agradeço a todos que me ajudaram... Eu valorizo essas conexões acima de tudo...",
  ui_story_5080_50801401_99_dialog_content = "Então eu não vou desistir de nenhum dos meus amigos, Rachel.",
  ui_story_5080_50801401_100_dialog_content = "...Você realmente é um soldado insubordinado.",
  ui_story_5080_50801401_101_dialog_content = "Mas, PlayerName, estou feliz...",
  ui_story_5080_50801401_102_dialog_content = "Estou honrado em fazer parte da mesma equipe que todos vocês.",
  ui_story_5080_50801401_103_dialog_content = "Vamos subir juntos.",
  ui_story_5080_50801401_104_dialog_content = "Carleen, use sua última força para reforçar nossa posição!",
  ui_story_5080_50801401_105_dialog_content = "Jeriah, os Oradores devem ser capazes de suportar a parede que está desmoronando, certo?",
  ui_story_5080_50801401_106_dialog_content = "Fleur, você é responsável por atacá-lo de frente.",
  ui_story_5080_50801401_107_dialog_content = "Vamos lutar lado a lado.",
  ui_story_5080_50801402_1_dialog_content = "A lava está ficando mais turbulenta, meu <color=#FFB400>Caminho de Gelo</color> está... prestes a quebrar!",
  ui_story_5080_50801402_2_dialog_content = "Só um pouco mais, a armadura dele está quase sem energia!",
  ui_story_5080_50801402_3_dialog_content = "Não! PlayerName, Rachel!",
  ui_story_5080_50801402_4_dialog_content = "(Oh não... a lava cortou o caminho. Estamos todos separados...)",
  ui_story_5080_50801402_5_dialog_content = "Esqueçam de nós... Estou esgotado... vocês saem pelo buraco que Fleur explodiu...",
  ui_story_5080_50801402_6_dialog_content = "Que tipo de absurdo é esse? Aguente firme. Nós vamos conseguir.",
  ui_story_5080_50801402_7_dialog_content = "De todos os lugares... Tentar criar outra ponte de gelo aqui... será quase impossível.",
  ui_story_5080_50801402_8_dialog_content = "<size=40>Ah!!!</size>",
  ui_story_5080_50801402_9_dialog_content = "Eu não vou recuar, monstro... mesmo que tudo que me reste seja esta pistola...",
  ui_story_5080_50801402_10_dialog_content = "<color=#e8d9bb>Bam, bam, bam!</color>",
  ui_story_5080_50801402_11_dialog_content = "<color=#e8d9bb>As balas de Rachel atingem o Eclipsite uma por uma, mas são bloqueadas pelo seu último pouco de calor.</color>",
  ui_story_5080_50801402_12_dialog_content = "<color=#e8d9bb>Clique-</color>",
  ui_story_5080_50801402_13_dialog_content = "Sem munição...",
  ui_story_5080_50801402_14_dialog_content = "Estou sem armas, mas ainda tenho meus punhos.",
  ui_story_5080_50801402_15_dialog_content = "PlayerName, se esconda atrás de mim e não se mexa nem um centímetro!",
  ui_story_5080_50801402_16_dialog_content = "Rachel... vamos lá... Eu não consigo mais me mexer...",
  ui_story_5080_50801402_17_dialog_content = "Eu... nunca vou te abandonar!",
  ui_story_5080_50801402_18_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5080_50801402_19_dialog_content = "Outra erupção de lava, este vulcão parece que está prestes a... espera, o que é isso?!",
  ui_story_5080_50801402_20_dialog_content = "Uma chave... A chave de Sinsa? Como ela veio parar aqui?",
  ui_story_5080_50801402_21_dialog_content = "Momento perfeito.",
  ui_story_5080_50801402_22_dialog_content = "Pare, Rachel, essa chave é pesada demais para você! Não se machuque!",
  ui_story_5080_50801402_23_dialog_content = "Huff... Huff... Estamos de volta... Ah!",
  ui_story_5080_50801402_24_dialog_content = "Espere, ela está realmente levantando a chave inglesa do Sinsa! Isso é pura exibição!",
  ui_story_5080_50801402_25_dialog_content = "Eu... ha... odeio quando os membros do time se exibem...",
  ui_story_5080_50801402_26_dialog_content = "Mas eu realmente amo me exibir.",
  ui_story_5080_50801402_27_dialog_content = "Grah!!!",
  ui_story_5080_50801402_28_dialog_content = "Não se atreva a machucar meus companheiros de equipe!",
  ui_story_5080_50801402_29_dialog_content = "Grooo—!!!",
  ui_story_5080_50801402_30_dialog_content = "Como isso é possível? Eu nunca pensei que veria alguém além de Sinsa balançando aquela chave...",
  ui_story_5080_50801402_31_dialog_content = "Awuu... Awuu... Awuu...!!!",
  ui_story_5080_50801402_32_dialog_content = "Não está morto ainda?!",
  ui_story_5080_50801402_33_dialog_content = "Então... vamos fazer isso mais uma vez...",
  ui_story_5080_50801402_34_dialog_content = "(Isso é ruim... Eu posso sentir que o corpo de Rachel atingiu seu limite... Ela está se esforçando demais... só um pouco mais, e...)",
  ui_story_5080_50801402_35_dialog_content = "Eu... nunca vou desistir... Mais uma vez!",
  ui_story_5080_50801402_36_dialog_content = "Grah!!!",
  ui_story_5080_50801402_37_dialog_content = "Ponte de Gelo... Rápido!",
  ui_story_5080_50801402_38_dialog_content = "Ela está sem forças... Se isso continuar... ambos vão...",
  ui_story_5080_50801402_39_dialog_content = "O que é toda essa barulheira?! Não dá pra um cara descansar por aqui?!",
  ui_story_5080_50801402_40_dialog_content = "Você... Sinsa?!",
  ui_story_5080_50801402_41_dialog_content = "Ei, pequena senhora, você tem espírito.",
  ui_story_5080_50801402_42_dialog_content = "Ser capaz de levantar esta chave inglesa significa que você tem verdadeira força.",
  ui_story_5080_50801402_43_dialog_content = "Usar essa força para proteger os outros mostra que você tem uma vontade ainda mais brilhante.",
  ui_story_5080_50801402_44_dialog_content = "Vamos lá! Pela <color=#FFB400>justiça</color> em seu coração, empunhe esse <color=#FFB400>poder supremo</color>!",
  ui_story_5080_50801402_45_dialog_content = "<size=45>Hyaaaaaaah—!!!</size>",
  ui_story_5080_50801402_46_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5080_50801402_47_dialog_content = "Pessoas de mundos completamente diferentes, erguendo aquela chave para os corações que protegem...",
  ui_story_5080_50801402_48_dialog_content = "Aquelas duas silhuetas...",
  ui_story_5080_50801402_49_dialog_content = "Nem pense em machucá-los!",
  ui_story_5080_50801402_50_dialog_content = "Você não vai passar por mim!",
  ui_story_5080_50801402_51_dialog_content = "Mesmo aquele que não conseguia te entender no início, agora levanta essa chave—",
  ui_story_5080_50801402_52_dialog_content = "Heh... sua vontade vive até hoje... Attar...",
  ui_story_5080_50801402_53_dialog_content = "Continua vivendo como... <color=#FFB400>a Rediesel Wrench</color>.",
  ui_story_5080_50801402_54_dialog_content = "Finalmente terminado... Aí vem a lava, vamos nos mover.",
  ui_story_5080_50801402_55_dialog_content = "A última ponte de gelo está erguida. Vamos.",
  ui_story_5080_50801402_56_dialog_content = "Ei—! Por aqui!",
  ui_story_5080_50801402_57_dialog_content = "Por aqui! Eu joguei um gancho de agarrar lá em cima, podemos subir!",
  ui_story_5080_50801402_58_dialog_content = "PlayerName... vamos lá... ugh!",
  ui_story_5080_50801402_59_dialog_content = "Ei, você está bem? Se esforçando demais com todas essas lesões - você não tem mais nada em você, tem?",
  ui_story_5080_50801402_60_dialog_content = "Acho que você não tem escolha. Precisa de uma mão deste bandido da Rediesel?",
  ui_story_5080_50801402_61_dialog_content = "...",
  ui_story_5080_50801402_62_dialog_content = "Ei!",
  ui_story_5080_50801402_63_dialog_content = "<color=#e8d9bb>Uma pedra passa raspando pelos dois e cai na lava.</color>",
  ui_story_5080_50801402_64_dialog_content = "... Quem disse que eu não posso me levantar? Precisa de uma mão deste soldado de Illumina?",
  ui_story_5080_50801402_65_dialog_content = "Hahahaha! Você é muito mais fofa do que deixa transparecer.",
  ui_story_5080_50801402_66_dialog_content = "Uma pedrinha como essa não é grande coisa... mas eu não deveria fazer Eve se preocupar com a minha ferida.",
  ui_story_5080_50801402_67_dialog_content = "Muito obrigado.",
  ui_story_5080_50801402_68_dialog_content = "Desculpe... mas alguém pode me dar uma mão? Eu exagerei na minha habilidade psíquica. Estou totalmente esgotado...",
  ui_story_5080_50801402_69_dialog_content = "...",
  ui_story_5080_50801402_70_dialog_content = "Heh...",
  ui_story_5080_50801402_71_dialog_content = "Hahaha!",
  ui_story_5080_50801402_72_dialog_content = "Pare de rir aí, vamos seguir em frente!",
  ui_story_5080_50801402_73_dialog_content = "<color=#e8d9bb>Estrondo, estrondo!</color>",
  ui_story_5080_50801402_74_dialog_content = "Oh ho! Finalmente fora! Ar fresco e uma temperatura perfeita!",
  ui_story_5080_50801402_75_dialog_content = "Uau! Como vocês ficaram tão rápidos?!",
  ui_story_5080_50801402_76_dialog_content = "Parece que deixar vocês dois seguirem na frente foi a decisão certa. Essa habilidade de encontrar caminhos é realmente algo...",
  ui_story_5080_50801402_77_dialog_content = "Zeta liderou o caminho.",
  ui_story_5080_50801402_78_dialog_content = "O-O que tem isso?! Eu sou uma lenda do rally! E daí se eu não sou um profissional em exploração de cavernas!",
  ui_story_5080_50801402_79_dialog_content = "Hahahaha!",
  ui_story_5080_50801402_80_dialog_content = "Ei, Berserker! Sem rir!",
  ui_story_5080_50801402_81_dialog_content = "Bem, é claro, temos que rir, pequeno Zeta.",
  ui_story_5080_50801402_82_dialog_content = "Você?! Até você deseja intimidar este grande herói...?!",
  ui_story_5080_50801402_83_dialog_content = "Na verdade, podemos voltar a tempo para o banquete! Sério!",
  ui_story_5080_50801402_84_dialog_content = "Por que estamos enrolando aqui? Eles podem começar sem nós!",
  ui_story_5080_50801402_85_dialog_content = "O quê? Com a Grande Heroína Zeta aqui? Eu vou te trazer de volta num piscar de olhos!",
  ui_story_5080_50801402_86_dialog_content = "Entre no carro!",
  ui_story_5080_50801402_87_dialog_content = "Olá... Jonah?",
  ui_story_5080_50801402_88_dialog_content = "Azure?",
  ui_story_5080_50801402_89_dialog_content = "Oh céus... Eu raramente volto, e quando volto, o lugar está morto.",
  ui_story_5080_50801402_90_dialog_content = "Espere! O que é aquilo ali?",
  ui_story_5080_50801402_91_dialog_content = "<color=#e8d9bb>Bang!!! Bam, bam, bam!</color>",
  ui_story_5080_50801402_92_dialog_content = "<color=#e8d9bb>Uma explosão de uma armadilha desencadeia uma reação em cadeia entre todas as minas terrestres. Em questão de momentos, todo o acampamento fica irreconhecível.</color>",
  ui_story_5080_50801402_93_dialog_content = "Esse é o campo minado...",
  ui_story_5080_50801402_94_dialog_content = "O que houve?",
  ui_story_5080_50801402_95_dialog_content = "Como o acampamento acabou neste estado? Uh... ainda vamos ter uma festa hoje à noite?",
  ui_story_5080_50801402_96_dialog_content = "Ahhhhhh!",
  ui_story_5080_50801402_97_dialog_content = "Seus idiotas! O que vocês fizeram?!",
  ui_story_5080_50801402_98_dialog_content = "Apenas um pequeno erro de cálculo, chefe!",
  ui_story_5080_50801402_99_dialog_content = "Pare de correr! Fique parado! Vou te ensinar uma lição!",
  ui_story_5080_50801402_100_dialog_content = "Tudo bem, tudo bem, pare de bater na criança por enquanto. Vamos ver o que ainda é comestível aqui, não é?",
  ui_story_5080_50801402_101_dialog_content = "Uauuu! Meu lindo palco...!",
  ui_story_5080_50801402_102_dialog_content = "Não chore, deixe-me ver se consigo consertar...",
  ui_story_5080_50801402_103_dialog_content = "Heh, nunca pensei que veria você ter um dia tão difícil, bruxa!",
  ui_story_5080_50801402_104_dialog_content = "Certamente você não deve ter ideia do tipo de façanhas que Zeta o Grande é capaz de realizar?!",
  ui_story_5080_50801402_105_dialog_content = "... Ah, esquece... Estou feliz em te ver, mana.",
  ui_story_5080_50801402_106_dialog_content = "O que é tudo isso?",
  ui_story_5080_50801402_107_dialog_content = "Sério—",
  ui_story_5080_50801402_108_dialog_content = "Ei? Rachel! Rachel!",
  ui_story_5080_50801402_109_dialog_content = "E aí? Deixa eu dar uma olhada...",
  ui_story_5080_50801402_110_dialog_content = "Ah, ela está bem. Ela estava tão relaxada que acabou desmaiando.",
  ui_story_5080_50801402_111_dialog_content = "O drone dela quebrou de novo? Hmph, Odi, observe e aprenda enquanto eu mostro minhas habilidades de reparo requintadas!",
  ui_story_5080_50801402_112_dialog_content = "Como pode ser a sua vez comigo aqui?",
  ui_story_5080_50801402_113_dialog_content = "É esta... a cidade de Gannon?",
  ui_story_5080_50801402_114_dialog_content = "Quando eu voltei para casa...?",
  ui_story_5080_50801402_115_dialog_content = "Capitão! Capitão!",
  ui_story_5080_50801402_116_dialog_content = "Eu...",
  ui_story_5080_50801402_117_dialog_content = "Cisne Branco... não, Merry, você...",
  ui_story_5080_50801402_118_dialog_content = "Ah, faz tanto tempo... Hum?!",
  ui_story_5080_50801402_119_dialog_content = "Capitão, você... Por que está chorando?",
  ui_story_5080_50801402_120_dialog_content = "Desculpe, me desculpe... Eu queria te contar isso há tanto tempo.",
  ui_story_5080_50801402_121_dialog_content = "Não sou um bom capitão... Eu deixei você... deixei você...",
  ui_story_5080_50801402_122_dialog_content = "Hahaha, nunca pensei que o capitão derramaria lágrimas tão livremente.",
  ui_story_5080_50801402_123_dialog_content = "É a primeira vez que vejo isso... e espero que seja a última.",
  ui_story_5080_50801402_124_dialog_content = "Você é o único que sobreviveu, Capitão. Não é ótimo?",
  ui_story_5080_50801402_125_dialog_content = "Estamos tão felizes que pudemos salvar você.",
  ui_story_5080_50801402_126_dialog_content = "E agora você está ainda mais perfeito do que antes! Quer dizer, você salvou todo mundo, não foi?",
  ui_story_5080_50801402_127_dialog_content = "Agora você é o capitão supremo.",
  ui_story_5080_50801402_128_dialog_content = "Vocês...",
  ui_story_5080_50801402_129_dialog_content = "Estou tão feliz por ter te conhecido, Capitão.",
  ui_story_5080_50801402_130_dialog_content = "De todas as equipes, eu tive a sorte de ser escolhido por você... Eu sou muito sortudo.",
  ui_story_5080_50801402_131_dialog_content = "Então você também precisa ser feliz, Capitão.",
  ui_story_5080_50801402_132_dialog_content = "Pra onde vocês vão? Voltem aqui! Me escutem...",
  ui_story_5080_50801402_133_dialog_content = "Hora de voltar, Capitão. Nós não somos os que você precisa manter seguros agora.",
  ui_story_5080_50801402_134_dialog_content = "Por favor, viva bem... Ria mais - é tudo o que queremos!",
  ui_story_5080_50801402_135_dialog_content = "Espere, todos, não vão!",
  ui_story_5080_50801402_136_dialog_content = "Capitão...",
  ui_story_5080_50801402_137_dialog_content = "E-espere por mim!",
  ui_story_5080_50801402_138_dialog_content = "Capitão...!",
  ui_story_5080_50801402_139_dialog_content = "Irmã, você...",
  ui_story_5080_50801402_140_dialog_content = "Vice?",
  ui_story_5080_50801402_141_dialog_content = "Capitão...?",
  ui_story_5080_50801402_142_dialog_content = "Você está bem... Que alívio.",
  ui_story_5080_50801402_143_dialog_content = "Espere! Você acabou de... dizer meu nome?",
  ui_story_5080_50801402_144_dialog_content = "Uaaau! Capitão! Capitão!!!",
  ui_story_5080_50801402_145_dialog_content = "<color=#e8d9bb>Vice, transbordando de alegria, abraça Rachel com força, sem se importar com o quão rígido o destinatário de seu abraço está.</color>",
  ui_story_5080_50801402_146_dialog_content = "(Mas... esse coração sincero definitivamente não ficará sem recompensa.)",
  ui_story_5080_50801402_147_dialog_content = "Está tudo bem agora... Tudo está bem...",
  ui_story_5080_50801402_148_dialog_content = "Obrigado, Vice.",
  ui_story_5080_50801402_149_dialog_content = "Obrigada a todos.",
  ui_story_5080_50801500_1_dialog_content = "Matamos aquele Eclipsita para nos salvar, mas agora, o terremoto diminuiu e o vulcão não entrou em erupção.",
  ui_story_5080_50801500_2_dialog_content = "Quer dizer... ainda há algo suprimindo a energia do vulcão?",
  ui_story_5080_50801500_3_dialog_content = "É apenas um palpite, mas antes de partirmos, os Oradores encontraram-",
  ui_story_5080_50801500_4_dialog_content = "O local onde você achatou aquele Eclipsita foi perfurado. Havia outra camada abaixo, com seu próprio caminho.",
  ui_story_5080_50801500_5_dialog_content = "Um caminho dentro do núcleo do vulcão?",
  ui_story_5080_50801500_6_dialog_content = "Mas agora está tudo coberto de lava, então talvez não consigamos investigar.",
  ui_story_5080_50801500_7_dialog_content = "... Roy acredita que aquele Eclipsite não era o de antes.",
  ui_story_5080_50801500_8_dialog_content = "De fato. Se não fosse pelo terreno, as coisas não teriam sido tão difíceis. Se este fosse o de antigamente, Attar não teria morrido...",
  ui_story_5080_50801500_9_dialog_content = "Parece que tudo está intimamente relacionado com as verdadeiras profundezas do vulcão.",
  ui_story_5080_50801500_10_dialog_content = "Nosso verdadeiro <color=#FFB400>inimigo</color>... pode estar se escondendo lá.",
  ui_story_5080_50801500_11_dialog_content = "Vamos investigar juntos assim que a lava esfriar e todos estiverem curados de suas lesões.",
  ui_story_5080_50801500_12_dialog_content = "Deve ser bastante incômodo para a Rediesel Wrench, dormir acima de um vulcão tão ativo, não é?",
  ui_story_5080_50801500_13_dialog_content = "Quem pode dizer... Somos todos apenas um grande bando de tolos vivendo o momento. Realmente existe alguém entre nós que se preocuparia tanto com algo assim?",
  ui_story_5080_50801500_14_dialog_content = "O palco está pronto... Eu estive trabalhando nele sem parar, e garoto, como estou cansado!!!",
  ui_story_5080_50801500_15_dialog_content = "Não se preocupe, deixe a próxima parte comigo! Deixe minha paixão queimar pelo céu noturno—!",
  ui_story_5080_50801500_16_dialog_content = "Hã? Zeta?! Você, você...",
  ui_story_5080_50801500_17_dialog_content = "Por que você se maquiou como um fantasma?",
  ui_story_5080_50801500_18_dialog_content = "Eh? Essa foi toda ideia da garota bruxa, fazendo Zeta se parecer com um adulto!",
  ui_story_5080_50801500_19_dialog_content = "Você quer dizer... aquela garota bruxa!!!",
  ui_story_5080_50801500_20_dialog_content = "Não corra! Você não disse que dançaria comigo? Estamos prestes a subir ao palco para o confronto final!",
  ui_story_5080_50801500_21_dialog_content = "Brock, você também viu, certo? Todos estão com fome.",
  ui_story_5080_50801500_22_dialog_content = "Sem dúvida, o lavador de vegetais mais rápido será aclamado como o verdadeiro herói que resolveu essa crise - um herói digno do respeito de todos.",
  ui_story_5080_50801500_23_dialog_content = "Ah, ah, ah! Você não precisa me dizer duas vezes - eu tenho treinado para isso, apenas observe!",
  ui_story_5080_50801500_24_dialog_content = "Sério? Uau, eu queria que todos fossem tão ingênuos... Ei! Eu tenho uma lavadora de vegetais aqui! Interessado?",
  ui_story_5080_50801500_25_dialog_content = "O acampamento está uma bagunça... Eu também quero ajudar.",
  ui_story_5080_50801500_26_dialog_content = "Concordo.",
  ui_story_5080_50801500_27_dialog_content = "Saia do caminho! Ninguém vai roubar meu trovão!",
  ui_story_5080_50801500_28_dialog_content = "Apenas deixe-o fazer isso, se você quer uma vida pacífica.",
  ui_story_5080_50801500_29_dialog_content = "Azure? Azure? Para onde você foi?",
  ui_story_5080_50801500_30_dialog_content = "Eu praticamente esvaziei o depósito. Você precisa tomar uma bebida de verdade comigo esta noite!",
  ui_story_5080_50801500_31_dialog_content = "Sério, que público barulhento...",
  ui_story_5080_50801500_32_dialog_content = "Não sou nenhum velho experiente, apenas um pirralho que tropeçou nisso tudo pela metade do caminho.",
  ui_story_5080_50801500_33_dialog_content = "Astra é tão vasto... mas este é o único lugar que nos acolheu, a mim e ao Eve, quando não tínhamos para onde ir.",
  ui_story_5080_50801500_34_dialog_content = "Finalmente chegamos tão longe. Finalmente podemos confiar em nós mesmos para continuar e viver juntos como uma família.",
  ui_story_5080_50801500_35_dialog_content = "Não se preocupe mais em agradar aos outros ou temer a rejeição.",
  ui_story_5080_50801500_36_dialog_content = "Sabe de uma coisa? Esta é a primeira vez que ouço você dizer isso.",
  ui_story_5080_50801500_37_dialog_content = "Somos todos tão estranhos, como grãos de areia desesperadamente se esfregando juntos. Se é verdade que o sangue é mais espesso que a água, então devemos ter misturado nosso sangue há muito tempo.",
  ui_story_5080_50801500_38_dialog_content = "Então, estou feliz em passar todos os dias com esses caras.",
  ui_story_5080_50801500_39_dialog_content = "Não importa quais desafios apareçam em nosso caminho, sempre nos unimos para construir uma vida feliz. Isso é o que a liberdade significa para nós!",
  ui_story_5080_50801500_40_dialog_content = "E para preservar nosso modo de vida, levantarei minha chave inglesa vez após vez para afastar qualquer um que mexa conosco!",
  ui_story_5080_50801500_41_dialog_content = "Você é um líder extraordinário, Sinsa.",
  ui_story_5080_50801500_42_dialog_content = "Agora, eu tenho um favor a pedir. Minha missão está concluída, mas ainda não estou satisfeito.",
  ui_story_5080_50801500_43_dialog_content = "Se ainda houver perigo por perto, quero enfrentá-lo junto com todos aqui.",
  ui_story_5080_50801500_44_dialog_content = "Além disso, o velho líder salvou minha tia, e eu quero retribuir a dívida.",
  ui_story_5080_50801500_45_dialog_content = "Então, deixe-me perguntar agora - você entende o significado de \"sacrifício\"?",
  ui_story_5080_50801500_46_dialog_content = "Heh...",
  ui_story_5080_50801500_47_dialog_content = "Hã? Por que está olhando para nós?",
  ui_story_5080_50801500_48_dialog_content = "Decidi. Para poupar meus colegas de equipe de preocupações constantes, não falarei levianamente sobre sacrifício.",
  ui_story_5080_50801500_49_dialog_content = "Mas... se alguma vez estivermos em perigo, darei minha vida por aqueles ao meu lado.",
  ui_story_5080_50801500_50_dialog_content = "Não importa o que aconteça, desejo proteger aqueles que caminham comigo.",
  ui_story_5080_50801500_51_dialog_content = "Sim... Os soldados de Illumina não deveriam agir apenas em função da missão ou por honra.",
  ui_story_5080_50801500_52_dialog_content = "Mas porque queremos proteger tudo em nossas vidas.",
  ui_story_5080_50801500_53_dialog_content = "Rachel...",
  ui_story_5080_50801500_54_dialog_content = "Mesmo que eu tenha que me tornar um fogo ardente para iluminar o caminho e garantir o futuro daqueles ao meu redor - este é o verdadeiro propósito de Illumina!",
  ui_story_5080_50801500_55_dialog_content = "Meus ancestrais foram ajudados por outros e se sacrificaram por outros em troca, e eu não serei uma exceção!",
  ui_story_5080_50801500_56_dialog_content = "De agora em diante, lutarei para proteger meus desejos sinceros e me tornarei uma linha de defesa inabalável para Illumina.",
  ui_story_5080_50801500_57_dialog_content = "Suas palavras soam meio que as mesmas de sempre, mas seus olhos contam uma história diferente.",
  ui_story_5080_50801500_58_dialog_content = "Tem certeza de que está pronto para começar a tomar suas próprias decisões agora?",
  ui_story_5080_50801500_59_dialog_content = "O credo da Illumina é \"um por todos, todos por um.\"",
  ui_story_5080_50801500_60_dialog_content = "Mesmo assim, ainda podemos fazer nossas próprias decisões através de nossa própria vontade. Podemos decidir pelo que lutamos e pelo que estamos dispostos a sacrificar nossas vidas.",
  ui_story_5080_50801500_61_dialog_content = "Esse tipo de determinação nunca poderia ser falso... Ah!",
  ui_story_5080_50801500_62_dialog_content = "Você ainda consegue encontrar a Illumina no seu coração?",
  ui_story_5080_50801500_63_dialog_content = "O que foi, Capitão Rachel? Suas feridas estão te incomodando?",
  ui_story_5080_50801500_64_dialog_content = "...Não, não se preocupe, Vice.",
  ui_story_5080_50801500_65_dialog_content = "Eu apenas... finalmente sei como responder a essa pergunta.",
  ui_story_5080_50801500_66_dialog_content = "Que pergunta...?",
  ui_story_5080_50801500_67_dialog_content = "Heh... parece que você finalmente sabe o que está procurando.",
  ui_story_5080_50801500_68_dialog_content = "Certo, eu concordo em deixar você dar uma mãozinha na investigação.",
  ui_story_5080_50801500_69_dialog_content = "Mas com essas lesões, não pense em se apressar ainda.",
  ui_story_5080_50801500_70_dialog_content = "Fique aqui esta noite, aproveite uma boa refeição e descanse.",
  ui_story_5080_50801500_71_dialog_content = "Hum... Mas...",
  ui_story_5080_50801500_72_dialog_content = "Mas?",
  ui_story_5080_50801500_73_dialog_content = "Mesmo sendo aliados, se a Rediesel Wrench causar problemas novamente, vou lidar com você da mesma maneira que lidaria com qualquer um!",
  ui_story_5080_50801500_74_dialog_content = "Se você manchar a vontade que essa chave inglesa representa, farei você entregá-la.",
  ui_story_5080_50801500_75_dialog_content = "Hã...",
  ui_story_5080_50801500_76_dialog_content = "Se você quer, venha e pegue você mesmo.",
  ui_story_5080_50801500_77_dialog_content = "Sinceramente, seu louco cérebro da Illumina está com alguns parafusos soltos.",
  ui_story_5080_50801500_78_dialog_content = "Hahahaha!",
  ui_story_5080_50801500_79_dialog_content = "Do que você está rindo?",
  ui_story_5080_50801500_80_dialog_content = "Essa é a primeira vez que te vejo tão desamparado, Sinsa! Hahahaha!",
  ui_story_5080_50801500_81_dialog_content = "Me dá um tempo...",
  ui_story_5080_50801500_82_dialog_content = "Chefe! Chefe! Olhe para isso!",
  ui_story_5080_50801500_83_dialog_content = "Encontramos isso enquanto limpávamos os destroços - parece que pode ser o diário do antigo chefe.",
  ui_story_5080_50801500_84_dialog_content = "Descobrimos isso em uma pequena caixa que foi aberta pela explosão... Parece que estava escondido todo esse tempo.",
  ui_story_5080_50801500_85_dialog_content = "... Entendido. Por agora, vamos apenas guardar isso.",
  ui_story_5080_50801500_86_dialog_content = "Afinal, é hora da festa. Vamos nos preocupar com todo o resto amanhã - vamos nos divertir!",
  ui_story_5080_50801500_87_dialog_content = "Entendi! Ei! Pare de empurrar... Ai!",
  ui_story_5080_50801500_88_dialog_content = "Agora é minha vez de rir! Hahahaha!",
  ui_story_5080_50801500_89_dialog_content = "Meu pequeno pássaro de rapina, por favor, espere um momento.",
  ui_story_5080_50801500_90_dialog_content = "O que houve?",
  ui_story_5080_50801500_91_dialog_content = "Quero te contar a parte final da história que Attar compartilhou comigo.",
  ui_story_5080_50801500_92_dialog_content = "Depois de salvar sua colega de equipe e abandonar sua missão, ela deixou Illumina. Sem rumo, ela vagou pelo mundo por um tempo.",
  ui_story_5080_50801500_93_dialog_content = "Ela chegou coincidentemente neste mesmo deserto onde havia falhado em sua missão, sabendo que seu inimigo ainda persistia.",
  ui_story_5080_50801500_94_dialog_content = "Ela disse que nasceu neste deserto. Ela sabe que este deserto é um lugar sem lei e que é livre. É só que ela nunca morou aqui antes.",
  ui_story_5080_50801500_95_dialog_content = "Então ela queria ver por si mesma. No mínimo, ela queria encontrar um lugar de descanso para seus membros do time mortos.",
  ui_story_5080_50801500_96_dialog_content = "...",
  ui_story_5080_50801500_97_dialog_content = "Ela encontrou bandidos enquanto vagava pelo deserto e, por algum truque do destino, ela os levou para lutar contra os Eclipsitas, pegando aquela chave lendária para batalhar contra eles.",
  ui_story_5080_50801500_98_dialog_content = "Para essas pessoas, ela ergueu sua chave, uniu os bandidos do deserto e pôs fim ao caos nesta terra árida.",
  ui_story_5080_50801500_99_dialog_content = "Ela liderou essas pessoas para se estabelecerem no oásis e aprendeu a história lendária por trás da chave inglesa.",
  ui_story_5080_50801500_100_dialog_content = "E assim, ela manchou a chave com rediesel extraído do oásis, estabelecendo oficialmente a Rediesel Wrench.",
  ui_story_5080_50801500_101_dialog_content = "Ela viveu bem, não apenas encontrando a verdadeira liberdade, mas finalmente sacrificando tudo para protegê-la.",
  ui_story_5080_50801500_102_dialog_content = "Por que... está me contando tudo isso?",
  ui_story_5080_50801500_103_dialog_content = "Por favor, conte à sua tia quando você retornar.",
  ui_story_5080_50801500_104_dialog_content = "Seu capitão não abandonou sua nação sem motivo. Ao longo de sua jornada na vida, ela empunhou sua arma pela liberdade dos outros, até o fim.",
  ui_story_5080_50801500_105_dialog_content = "Espero que essa informação traga algum conforto para sua tia.",
  ui_story_5080_50801500_106_dialog_content = "Obrigado... Eu realmente não sei como mais expressar minha gratidão.",
  ui_story_5080_50801500_107_dialog_content = "Cante, pequeno pássaro de rapina! Não consegue ouvir a canção?",
  ui_story_5080_50801500_108_dialog_content = "A música...?",
  ui_story_5080_50801500_109_dialog_content = "Queime brilhantemente, belo paraíso, nossa casa!",
  ui_story_5080_50801500_110_dialog_content = "Cante, cante, mesmo se o mundo de amanhã estiver cheio de feridas!",
  ui_story_5080_50801500_111_dialog_content = "Levante sua voz na canção... Isso é... o poder da vida.",
  ui_story_5080_50801500_112_dialog_content = "Capitão Rachel! Por aqui! A festa está prestes a começar!",
  ui_story_5080_50801500_113_dialog_content = "Ah... Eu já vou!",
  ui_story_5080_50801500_114_dialog_content = "... Também é hora de eu ir...",
  ui_story_5080_50801500_115_dialog_content = "Para onde você está indo? Ei, pegue isso.",
  ui_story_5080_50801500_116_dialog_content = "Isto é...",
  ui_story_5080_50801500_117_dialog_content = "Cacto com fígado de escorpião cristalizado grelhado. É delicioso! Estou adivinhando que você nunca experimentou antes.",
  ui_story_5080_50801500_118_dialog_content = "Você explorou tanto, em tantos lugares que eu nem sabia que existiam.",
  ui_story_5080_50801500_119_dialog_content = "Falar sobre afirmar o óbvio...",
  ui_story_5080_50801500_120_dialog_content = "Ei... Jeriah, você também deveria voltar para casa de vez em quando. Vamos fazer uma grande refeição juntos.",
  ui_story_5080_50801500_121_dialog_content = "... Parece que não há saída deste banquete,",
  ui_story_5080_50801500_122_dialog_content = "Então, o que mais há para dizer? Vamos lá!",
  ui_story_5080_50801500_123_dialog_content = "Rachel, por aqui! Eu guardei um lugar para você.",
  ui_story_5080_50801500_124_dialog_content = "Assim que a carne estiver grelhada, pegue sua parte enquanto pode - esses caras geralmente não têm tempo para formalidades!",
  ui_story_5080_50801500_125_dialog_content = "Obrigado... Obrigado a todos.",
  ui_story_5080_50801500_126_dialog_content = "Para quê? Isso não é nada, realmente.",
  ui_story_5080_50801500_127_dialog_content = "Não... Eu sou grato pela maneira como você constantemente fez um esforço para me aceitar, apesar dos meus defeitos.",
  ui_story_5080_50801500_128_dialog_content = "Vamos apertar as mãos - é uma tradição da Illumina.",
  ui_story_5080_50801500_129_dialog_content = "... OK!",
  ui_story_5080_50801500_130_dialog_content = "Curioso, não é? Apesar de você ser um Celestita, por que sinto essa familiaridade quando estou com você?",
  ui_story_5080_50801500_131_dialog_content = "E você nunca me julga. Você parece à vontade com os Illuminans.",
  ui_story_5080_50801500_132_dialog_content = "(Por onde devo começar? Foi uma longa jornada... com Gram, Revy, Reinhardt, Barton e os outros...)",
  ui_story_5080_50801500_133_dialog_content = "PlayerName, vamos fazer isso juntos, como eu acabei de dizer!",
  ui_story_5080_50801500_134_dialog_content = "Direita!",
  ui_story_5080_50801500_135_dialog_content = "Esplendor Ilumina!! Uma saudação a você!",
  ui_story_5080_50801500_136_dialog_content = "Obrigado por me salvar e Vice!",
  ui_story_5080_50801500_137_dialog_content = "Que bela saudação militar... Heh, parece que vocês dois passaram por muita coisa. Deve ser por isso que são companheiros lendários.",
  ui_story_5080_50801500_138_dialog_content = "Agora entendo por que o Grande Marechal te chamou de incrível.",
  ui_story_5080_50801500_139_dialog_content = "Mas por enquanto, vocês também são meus companheiros...",
  ui_story_5080_50801500_140_dialog_content = "Vamos aproveitar este jantar juntos, todos!",
  ui_story_5080_50801500_141_dialog_content = "<color=#e8d9bb>A canção áspera da Rediesel Wrench, embora não refinada, exala um senso de liberdade irrestrita. Ela incendeia o deserto, ecoando pela noite em uma melodia frenética.</color>",
  ui_story_5080_50801500_142_dialog_content = "Merry... Louis... Tarsi... Lina... vocês conseguem ouvir?",
  ui_story_5080_50801500_143_dialog_content = "Dizem que este deserto acolhe todas as almas... Então...",
  ui_story_5080_50801500_144_dialog_content = "Certamente ele te abraça também.",
  ui_story_5080_50801500_145_dialog_content = "Voe... nesta noite de liberdade.",
  ui_story_5080_50801500_146_dialog_content = "Até que suas almas encontrem descanso."
}
return config
